  /// administrator.
  actor_type String

  /// Current available coin balance. Must be non-negative.
  balance Int

  /// Total coins earned through all transactions.
  total_earned Int

  /// Total coins spent through all transactions.
  total_spent Int

  /// Type of digital currency. Examples: loyalty_points, reward_coins,
  /// bonus_coins.
  coin_type String

  /// Account creation timestamp.
  created_at DateTime

  /// Last balance update timestamp.
  updated_at DateTime

