/// Formal support tickets for tracking complex customer issues.
///
/// Represents structured support cases that require extended tracking,
/// multiple interactions, and formal resolution processes. Tickets are
/// typically created for complex issues that cannot be resolved through
/// simple inquiry responses.
///
/// Support tickets include comprehensive tracking of issue details, assigned
/// support agents, SLA compliance, and resolution documentation. The system
/// manages ticket priority, categorization, and workflow states throughout
/// the support lifecycle.
///
/// @namespace Inquiries
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_support_tickets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Original inquiry that escalated to a support ticket. {@link
  /// shopping_mall_inquiries.id}
  shopping_mall_inquiry_id String?

  /// Support agent assigned to the ticket. {@link
  /// shopping_mall_administrators.id}
  shopping_mall_administrator_id String?

  /// Unique ticket identifier for customer reference and support tracking.
  ticket_number String

  /// Brief summary of the ticket issue or problem description.
  title String

  /// Detailed description of the issue including symptoms, steps to reproduce,
  /// and impact assessment.
  description String

  /// Ticket categorization such as technical_issue, billing_problem, or
  /// account_security.
  category String

  /// Urgency level (low, medium, high, critical) determining response and
  /// resolution timelines.
  priority String

  /// Current workflow state (new, open, in_progress, resolved, closed).
  status String

  /// Target resolution deadline based on service level agreements.
  sla_deadline DateTime?

  /// Documentation of the solution applied to resolve the ticket.
  resolution_notes String?

  /// Timestamp when the support ticket was created.
  created_at DateTime

  /// Timestamp of the last modification to the ticket record.
  updated_at DateTime

  /// Timestamp when the ticket was marked as resolved.
  resolved_at DateTime?

  /// Timestamp when the ticket was formally closed after resolution
  /// verification.
  closed_at DateTime?

  /// Timestamp when the ticket was soft deleted for audit trail purposes.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  inquiry shopping_mall_inquiries? @relation(fields: [shopping_mall_inquiry_id], references: [id], onDelete: Cascade)
  assignedAdministrator shopping_mall_administrators? @relation(fields: [shopping_mall_administrator_id], references: [id], onDelete: Cascade)

  shopping_mall_ticket_status_history shopping_mall_ticket_status_history[]

  @@unique([shopping_mall_inquiry_id])

  @@unique([ticket_number])
  @@index([status, priority])
  @@index([category, created_at])
  @@index([sla_deadline])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_administrator_id, status], map: "shopping_mall_support_tickets_shopping_mall_administra_67d51e38")
}

/// Historical tracking of support ticket status changes.
///
/// Maintains a complete audit trail of all status transitions for support
/// tickets. Each record captures the previous status, new status, change
/// reason, and the administrator who made the change.
///
/// This historical data enables tracking of ticket lifecycle, response time
