/// Main entity for digital currency balances with polymorphic ownership
/// support.
///
/// Tracks coin balances for platform users across multiple actor types
/// (customers, sellers, administrators). Each record represents a specific
/// actor's coin account with current balance, total earned, and total spent
/// metrics.
///
/// Uses actor_type field for efficient filtering and supports multiple coin
/// types with separate balances per actor. Balances are updated through
/// transaction records to ensure audit trail integrity. Soft deletion allows
/// for account closure while preserving transaction history.
///
/// The main entity contains shared business attributes while subtype
/// entities handle actor-specific relationships and metadata.
///
/// @namespace Coins
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_coins {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Type of actor owning the coin account. Valid values: customer, seller,
  /// administrator.
  actor_type String

  /// Current available coin balance. Must be non-negative.
  balance Int

  /// Total coins earned through all transactions.
  total_earned Int

  /// Total coins spent through all transactions.
  total_spent Int

  /// Type of digital currency. Examples: loyalty_points, reward_coins,
  /// bonus_coins.
  coin_type String

  /// Account creation timestamp.
  created_at DateTime

  /// Last balance update timestamp.
  updated_at DateTime

  /// Account closure timestamp for soft deletion.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  shopping_mall_coin_transactions      shopping_mall_coin_transactions[]
  shopping_mall_reward_redemptions     shopping_mall_reward_redemptions[]
  shopping_mall_coin_of_customers      shopping_mall_coin_of_customers?
  shopping_mall_coin_of_sellers        shopping_mall_coin_of_sellers?
  shopping_mall_coin_of_administrators shopping_mall_coin_of_administrators?

  @@unique([actor_type, coin_type])
  @@index([actor_type])
  @@index([coin_type])
  @@index([balance])
  @@index([created_at])
}

/// Audit trail for all coin transactions.
///
/// Records every coin movement including earning, spending, transfers, and
/// adjustments. Each transaction represents a complete accounting entry with
/// debit/credit amounts and business context.
///
/// Transactions maintain referential integrity with the coin balance table
/// and support various transaction types like purchases, rewards, refunds,
/// and administrative adjustments. The actor_type field enables polymorphic
/// ownership across different user types.
///
/// This main entity contains shared transaction attributes while subtype
/// entities handle actor-specific context and relationships.
///
/// @namespace Coins
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_coin_transactions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id

  /// Coin account reference. {@link shopping_mall_coins.id}
  shopping_mall_coins_id String

  /// Type of actor initiating the transaction. Valid values: customer, seller,
  /// administrator.
  actor_type String

  /// Type of transaction. Examples: purchase, reward, refund, transfer,
  /// adjustment.
  transaction_type String

  /// Transaction amount. Positive for earnings, negative for spending.
  amount Int

  /// Coin balance before this transaction.
  previous_balance Int

  /// Coin balance after this transaction.
  new_balance Int

  /// External reference ID for business context.
  reference_id String?

  /// Human-readable transaction description.
  description String

  /// Transaction status. Valid values: pending, completed, cancelled, failed.
  status String

  /// Transaction creation timestamp.
  created_at DateTime

  /// Last status update timestamp.
  updated_at DateTime

  /// Transaction deletion timestamp for soft deletion.
  deleted_at DateTime?

  //----
  // RELATIONS
  //----
  coins shopping_mall_coins @relation(fields: [shopping_mall_coins_id], references: [id], onDelete: Cascade)

  shopping_mall_coin_transaction_of_customers      shopping_mall_coin_transaction_of_customers?
  shopping_mall_coin_transaction_of_sellers        shopping_mall_coin_transaction_of_sellers?
  shopping_mall_coin_transaction_of_administrators shopping_mall_coin_transaction_of_administrators?

  @@unique([reference_id])
  @@index([actor_type])
  @@index([transaction_type])
  @@index([status])
  @@index([created_at])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_coins_id, created_at], map: "shopping_mall_coin_transactions_shopping_mall_coins_id_acf0d6fa")
}

