  /// Support agent assigned to the ticket. {@link
  /// shopping_mall_administrators.id}
  shopping_mall_administrator_id String?

  /// Unique ticket identifier for customer reference and support tracking.
  ticket_number String

  /// Brief summary of the ticket issue or problem description.
  title String

  /// Detailed description of the issue including symptoms, steps to reproduce,
  /// and impact assessment.
  description String

  /// Ticket categorization such as technical_issue, billing_problem, or
  /// account_security.
  category String

  /// Urgency level (low, medium, high, critical) determining response and
  /// resolution timelines.
  priority String

  /// Current workflow state (new, open, in_progress, resolved, closed).
  status String

  /// Target resolution deadline based on service level agreements.
