import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test customer registration with duplicate email address to validate proper
 * error handling and uniqueness constraints. Ensures the system correctly
 * identifies existing email addresses and prevents duplicate account creation
 * while maintaining data integrity and providing clear error messages to
 * users.
 */
export async function test_api_customer_registration_duplicate_email(
  connection: api.IConnection,
) {
  // Generate unique test data for the first customer
  const email = typia.random<string & tags.Format<"email">>();
  const password = "TestPassword123";
  const firstName = RandomGenerator.name();
  const lastName = RandomGenerator.name();
  const phoneNumber = RandomGenerator.mobile();
  const ip = "192.168.1.1";
  const href = "https://example.com/register";
  const referrer = "https://example.com";

  // Create the first customer account
  const firstCustomer = await api.functional.auth.customer.join(connection, {
    body: {
      email,
      password,
      first_name: firstName,
      last_name: lastName,
      phone_number: phoneNumber,
      ip,
      href,
      referrer,
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(firstCustomer);

  // Verify the first customer was created successfully
  TestValidator.equals(
    "first customer email matches",
    firstCustomer.email,
    email,
  );
  TestValidator.equals(
    "first customer first name matches",
    firstCustomer.first_name,
    firstName,
  );
  TestValidator.equals(
    "first customer last name matches",
    firstCustomer.last_name,
    lastName,
  );

  // Attempt to create a second customer with the same email address
  await TestValidator.error(
    "duplicate email registration should fail",
    async () => {
      return await api.functional.auth.customer.join(connection, {
        body: {
          email,
          password: "DifferentPassword456",
          first_name: RandomGenerator.name(),
          last_name: RandomGenerator.name(),
          phone_number: RandomGenerator.mobile(),
          ip,
          href,
          referrer,
        } satisfies IShoppingMallCustomer.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test customer registration with invalid password formats to validate password
 * strength requirements and security policies. Ensures weak passwords are
 * rejected with appropriate error messages and that password complexity rules
 * are enforced during account creation.
 */
export async function test_api_customer_registration_invalid_password(
  connection: api.IConnection,
) {
  // Common valid customer data for testing
  const validFirstName = RandomGenerator.name();
  const validLastName = RandomGenerator.name();
  const validHref = "https://example.com/register";
  const validReferrer = "https://example.com";

  // Test 1: Password that is too short
  await TestValidator.error("password too short should fail", async () => {
    await api.functional.auth.customer.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "123", // Too short password
        first_name: validFirstName,
        last_name: validLastName,
        href: validHref,
        referrer: validReferrer,
      } satisfies IShoppingMallCustomer.ICreate,
    });
  });

  // Test 2: Common weak password
  await TestValidator.error("common weak password should fail", async () => {
    await api.functional.auth.customer.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "password", // Common weak password
        first_name: validFirstName,
        last_name: validLastName,
        href: validHref,
        referrer: validReferrer,
      } satisfies IShoppingMallCustomer.ICreate,
    });
  });

  // Test 3: Sequential numbers password
  await TestValidator.error(
    "sequential numbers password should fail",
    async () => {
      await api.functional.auth.customer.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: "12345678", // Sequential numbers
          first_name: validFirstName,
          last_name: validLastName,
          href: validHref,
          referrer: validReferrer,
        } satisfies IShoppingMallCustomer.ICreate,
      });
    },
  );

  // Test 4: All lowercase letters without complexity
  await TestValidator.error(
    "password without complexity should fail",
    async () => {
      await api.functional.auth.customer.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: "abcdefgh", // Only lowercase letters
          first_name: validFirstName,
          last_name: validLastName,
          href: validHref,
          referrer: validReferrer,
        } satisfies IShoppingMallCustomer.ICreate,
      });
    },
  );

  // Test 5: Empty string password
  await TestValidator.error("empty password should fail", async () => {
    await api.functional.auth.customer.join(connection, {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: "", // Empty password
        first_name: validFirstName,
        last_name: validLastName,
        href: validHref,
        referrer: validReferrer,
      } satisfies IShoppingMallCustomer.ICreate,
    });
  });

  // Test 6: Password with only spaces
  await TestValidator.error(
    "password with only spaces should fail",
    async () => {
      await api.functional.auth.customer.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: "        ", // Only spaces
          first_name: validFirstName,
          last_name: validLastName,
          href: validHref,
          referrer: validReferrer,
        } satisfies IShoppingMallCustomer.ICreate,
      });
    },
  );

  // Test 7: Password with common patterns
  await TestValidator.error(
    "password with common patterns should fail",
    async () => {
      await api.functional.auth.customer.join(connection, {
        body: {
          email: typia.random<string & tags.Format<"email">>(),
          password: "qwertyuiop", // Keyboard pattern
          first_name: validFirstName,
          last_name: validLastName,
          href: validHref,
          referrer: validReferrer,
        } satisfies IShoppingMallCustomer.ICreate,
      });
    },
  );

  // Final validation: Ensure valid password works
  const finalEmail = typia.random<string & tags.Format<"email">>();
  const validPassword = "SecurePassword123!";
  const validCustomer = await api.functional.auth.customer.join(connection, {
    body: {
      email: finalEmail,
      password: validPassword,
      first_name: validFirstName,
      last_name: validLastName,
      href: validHref,
      referrer: validReferrer,
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(validCustomer);
  TestValidator.equals(
    "valid registration returns correct email",
    validCustomer.email,
    finalEmail,
  );
  TestValidator.equals(
    "valid registration returns correct first name",
    validCustomer.first_name,
    validFirstName,
  );
  TestValidator.equals(
    "valid registration returns correct last name",
    validCustomer.last_name,
    validLastName,
  );
  TestValidator.predicate(
    "valid registration returns non-empty token",
    validCustomer.token.access.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test successful customer login workflow with valid credentials.
 *
 * This test validates the complete authentication flow by first creating a
 * customer account and then testing login with the same credentials. It ensures
 * that bcrypt password comparison works correctly, session records are created
 * with connection context, and proper authentication tokens are returned for
 * platform access.
 */
export async function test_api_customer_login_success(
  connection: api.IConnection,
) {
  // Step 1: Create customer account for login testing
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "TestPassword123!";

  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://example.com/auth/login",
      referrer: "https://example.com/",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Test successful login with valid credentials
  const loginResult = await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://example.com/dashboard",
      referrer: "https://example.com/auth/login",
    } satisfies IShoppingMallCustomer.ILogin,
  });
  typia.assert(loginResult);

  // Step 3: Validate login response structure
  TestValidator.equals("customer ID should match", loginResult.id, customer.id);
  TestValidator.equals("email should match", loginResult.email, customerEmail);
  TestValidator.equals(
    "first name should match",
    loginResult.first_name,
    customer.first_name,
  );
  TestValidator.equals(
    "last name should match",
    loginResult.last_name,
    customer.last_name,
  );
  TestValidator.equals(
    "phone number should match",
    loginResult.phone_number,
    customer.phone_number,
  );
  TestValidator.equals("status should be active", loginResult.status, "active");

  // Step 4: Validate token structure
  TestValidator.predicate(
    "access token should be present",
    loginResult.token.access.length > 0,
  );
  TestValidator.predicate(
    "refresh token should be present",
    loginResult.token.refresh.length > 0,
  );
  TestValidator.predicate(
    "access token expiration should be valid date",
    !isNaN(new Date(loginResult.token.expired_at).getTime()),
  );
  TestValidator.predicate(
    "refresh token expiration should be valid date",
    !isNaN(new Date(loginResult.token.refreshable_until).getTime()),
  );

  // Step 5: Validate token expiration logic
  const expiredAt = new Date(loginResult.token.expired_at);
  const refreshableUntil = new Date(loginResult.token.refreshable_until);
  TestValidator.predicate(
    "refresh token should expire after access token",
    refreshableUntil > expiredAt,
  );
}

