    inactiveProduct.id,
  );
  TestValidator.equals(
    "seller sees inactive status",
    sellerRetrievedProduct.status,
    "inactive",
  );

  // Step 7: Test product retrieval as admin
  await api.functional.auth.admin.login(connection, {
