import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test public retrieval of specific product variant details.
 *
 * This E2E test validates that product variants created through authenticated
 * seller workflows can be publicly accessed by customers without requiring
 * authentication. The test follows a comprehensive multi-actor workflow:
 *
 * 1. Admin authentication and category creation
 * 2. Seller authentication and product creation
 * 3. Product variant creation by the seller
 * 4. Public retrieval of variant details without authentication
 *
 * Key validations include variant-specific information retrieval, pricing
 * overrides, inventory levels, attribute configurations, and active status. The
 * test ensures proper relationship to parent product and validates that all
 * variant details are accessible through public API endpoints.
 */
export async function test_api_product_variant_public_retrieval(
  connection: api.IConnection,
) {
  // Step 1: Admin authentication and category creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "Admin123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ access: "full" }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Create product category
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        display_order: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
        >(),
        active: true,
        parent_id: undefined,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 2: Seller authentication and product creation
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "Seller123!";

  const sellerAuth = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.content({ paragraphs: 1 }),
      tax_id: undefined,
      ip: undefined,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(sellerAuth);

  // Create parent product
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(8),
        price: typia.random<number & tags.Minimum<1> & tags.Maximum<1000>>(),
        compare_price: undefined,
        cost_price: undefined,
        stock_quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<1000>
        >(),
        status: "active",
        condition: "new",
        weight: undefined,
        dimensions: undefined,
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: undefined,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: sellerAuth.id,
          business_name: sellerAuth.business_name,
          contact_person: sellerAuth.contact_person,
          email: sellerAuth.email,
          status: sellerAuth.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 3: Product variant creation
  const variant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productId: product.id,
        body: {
          shopping_mall_product_id: product.id,
          variant_name: RandomGenerator.paragraph({ sentences: 2 }),
          sku: `${product.sku}-V1`,
          price: typia.random<number & tags.Minimum<1> & tags.Maximum<1000>>(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<500>
          >(),
          attributes: JSON.stringify({
            size: RandomGenerator.pick(["Small", "Medium", "Large"] as const),
            color: RandomGenerator.pick([
              "Red",
              "Blue",
              "Green",
              "Black",
            ] as const),
            material: RandomGenerator.pick([
              "Cotton",
              "Polyester",
              "Wool",
            ] as const),
          }),
          active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(variant);

  // Step 4: Public retrieval without authentication
  const unauthConn: api.IConnection = { ...connection, headers: {} };

  const retrievedVariant =
    await api.functional.shoppingMall.products.variants.at(unauthConn, {
      productId: product.id,
      variantId: variant.id,
    });
  typia.assert(retrievedVariant);

  // Validate retrieved variant matches created variant
  TestValidator.equals("variant ID matches", retrievedVariant.id, variant.id);
  TestValidator.equals(
    "variant name matches",
    retrievedVariant.variant_name,
    variant.variant_name,
  );
  TestValidator.equals("SKU matches", retrievedVariant.sku, variant.sku);
  TestValidator.equals("price matches", retrievedVariant.price, variant.price);
  TestValidator.equals(
    "stock quantity matches",
    retrievedVariant.stock_quantity,
    variant.stock_quantity,
  );
  TestValidator.equals(
    "attributes match",
    retrievedVariant.attributes,
    variant.attributes,
  );
  TestValidator.equals(
    "active status matches",
    retrievedVariant.active,
    variant.active,
  );
  TestValidator.equals(
    "parent product ID matches",
    retrievedVariant.product?.id,
    product.id,
  );
  TestValidator.equals(
    "parent product name matches",
    retrievedVariant.product?.name,
    product.name,
  );
  TestValidator.predicate("variant is active", retrievedVariant.active);
  TestValidator.predicate(
    "variant has valid stock quantity",
    retrievedVariant.stock_quantity > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test the complete workflow of creating product variants for an existing
 * product. Seller first registers, creates a category (via admin), creates a
 * parent product, then adds variants with different configurations. Validates
 * that variants inherit proper product relationships, SKU uniqueness is
 * enforced within the product, and variant-specific pricing and inventory are
 * correctly managed.
 */
export async function test_api_product_variant_creation_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller registration and authentication
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "seller1234";

  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.paragraph({ sentences: 3 }),
      href: "https://shopping-mall.test/auth/seller/join",
      referrer: "https://shopping-mall.test/seller/registration",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // 2. Admin registration and category creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin1234";

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ canManageCategories: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        display_order: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<0>
        >(),
        active: true,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // 3. Switch back to seller and create parent product
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: "https://shopping-mall.test/seller/dashboard",
      referrer: "https://shopping-mall.test/auth/seller/login",
    } satisfies IShoppingMallSeller.ILogin,
  });

  const parentProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(8),
        price: typia.random<number & tags.Minimum<1> & tags.Maximum<10000>>(),
        stock_quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<100>
        >(),
        status: "active",
        condition: "new",
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: category.parent,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(parentProduct);

  // 4. Create multiple variants with different configurations
  const variantConfigs = ArrayUtil.repeat(3, (index) => ({
    variant_name: `Variant ${index + 1}`,
    sku: `VAR-${parentProduct.sku}-${index + 1}`,
    price: parentProduct.price + index * 10,
    stock_quantity: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<50>
    >(),
    attributes: JSON.stringify({
      size: ["S", "M", "L"][index % 3],
      color: ["Red", "Blue", "Green"][index % 3],
    }),
    active: true,
  }));

  const createdVariants: IShoppingMallProductVariant[] = [];

  for (const config of variantConfigs) {
    const variant =
      await api.functional.shoppingMall.seller.products.variants.create(
        connection,
        {
          productId: parentProduct.id,
          body: {
            shopping_mall_product_id: parentProduct.id,
            variant_name: config.variant_name,
            sku: config.sku,
            price: config.price,
            stock_quantity: config.stock_quantity,
            attributes: config.attributes,
            active: config.active,
          } satisfies IShoppingMallProductVariant.ICreate,
        },
      );
    typia.assert(variant);
    createdVariants.push(variant);
  }

  // 5. Validate variant relationships and properties
  TestValidator.equals(
    "all variants should reference the parent product",
    createdVariants.every((v) => v.product?.id === parentProduct.id),
    true,
  );

  TestValidator.equals(
    "variant names should be unique within the product",
    new Set(createdVariants.map((v) => v.variant_name)).size,
    createdVariants.length,
  );

  TestValidator.equals(
    "variant SKUs should be unique within the product",
    new Set(createdVariants.map((v) => v.sku)).size,
    createdVariants.length,
  );

  // 6. Test SKU uniqueness enforcement
  await TestValidator.error("duplicate SKU should fail", async () => {
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productId: parentProduct.id,
        body: {
          shopping_mall_product_id: parentProduct.id,
          variant_name: "Duplicate SKU Variant",
          sku: createdVariants[0].sku, // Use existing SKU
          price: parentProduct.price,
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<10>
          >(),
          active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  });

  // 7. Validate variant-specific pricing and inventory
  for (const [index, variant] of createdVariants.entries()) {
    TestValidator.predicate(
      `variant ${index + 1} should have correct pricing`,
      variant.price === variantConfigs[index].price ||
        variant.price === parentProduct.price,
    );

    TestValidator.equals(
      `variant ${index + 1} should have correct inventory`,
      variant.stock_quantity,
      variantConfigs[index].stock_quantity,
    );

    TestValidator.predicate(
      `variant ${index + 1} should have valid attributes`,
      variant.attributes.length > 0,
    );
  }

  // 8. Validate product-variant relationship integrity
  TestValidator.equals(
    "all variants should be active",
    createdVariants.every((v) => v.active),
    true,
  );

  TestValidator.predicate(
    "variants should have proper timestamps",
    createdVariants.every(
      (v) =>
        v.created_at &&
        v.updated_at &&
        new Date(v.created_at) <= new Date(v.updated_at),
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test comprehensive variant update workflow including price adjustments,
 * inventory changes, and attribute modifications. Seller creates full product
 * hierarchy (category → product → variant), then updates variant details while
 * ensuring SKU uniqueness is maintained and ownership validation prevents
 * unauthorized modifications.
 */
export async function test_api_product_variant_update_by_seller(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account and authenticate
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "AdminPassword123!",
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role: "super_admin",
        permissions: JSON.stringify({ can_create_categories: true }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create category as administrator
  const category: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        display_order: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<0>
        >(),
        active: true,
        parent_id: undefined,
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(category);

  // Step 3: Create seller account and authenticate
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "SellerPassword123!",
        business_name: RandomGenerator.paragraph({ sentences: 2 }),
        contact_person: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        business_address: RandomGenerator.content({ paragraphs: 1 }),
        tax_id: undefined,
        ip: undefined,
        href: "https://shoppingmall.example.com/seller/register",
        referrer: "https://shoppingmall.example.com/",
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // Step 4: Seller creates a product
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(10),
        price: typia.random<number & tags.Minimum<0> & tags.Maximum<10000>>(),
        compare_price: undefined,
        cost_price: undefined,
        stock_quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<1000>
        >(),
        status: "active",
        condition: "new",
        weight: undefined,
        dimensions: undefined,
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: undefined,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // Step 5: Seller creates initial variant
  const initialVariant: IShoppingMallProductVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productId: product.id,
        body: {
          shopping_mall_product_id: product.id,
          variant_name: RandomGenerator.paragraph({ sentences: 2 }),
          sku: RandomGenerator.alphaNumeric(8),
          price: typia.random<number & tags.Minimum<0> & tags.Maximum<5000>>(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<500>
          >(),
          attributes: JSON.stringify({
            color: RandomGenerator.pick([
              "red",
              "blue",
              "green",
              "black",
              "white",
            ] as const),
            size: RandomGenerator.pick(["S", "M", "L", "XL"] as const),
          }),
          active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(initialVariant);

  // Step 6: Seller updates variant details
  const updateData = {
    variant_name: RandomGenerator.paragraph({ sentences: 2 }),
    sku: RandomGenerator.alphaNumeric(8),
    price: typia.random<number & tags.Minimum<0> & tags.Maximum<5000>>(),
    stock_quantity: typia.random<
      number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<500>
    >(),
    attributes: JSON.stringify({
      color: RandomGenerator.pick([
        "red",
        "blue",
        "green",
        "black",
        "white",
      ] as const),
      size: RandomGenerator.pick(["S", "M", "L", "XL"] as const),
      material: RandomGenerator.pick(["cotton", "polyester", "wool"] as const),
    }),
    active: true,
  } satisfies IShoppingMallProductVariant.IUpdate;

  const updatedVariant: IShoppingMallProductVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productId: product.id,
        variantId: initialVariant.id,
        body: updateData,
      },
    );
  typia.assert(updatedVariant);

  // Step 7: Validate that updates were properly applied
  TestValidator.equals(
    "variant ID remains unchanged",
    updatedVariant.id,
    initialVariant.id,
  );
  TestValidator.equals(
    "variant name updated",
    updatedVariant.variant_name,
    updateData.variant_name,
  );
  TestValidator.equals("SKU updated", updatedVariant.sku, updateData.sku);
  TestValidator.equals("price updated", updatedVariant.price, updateData.price);
  TestValidator.equals(
    "stock quantity updated",
    updatedVariant.stock_quantity,
    updateData.stock_quantity,
  );
  TestValidator.equals(
    "attributes updated",
    updatedVariant.attributes,
    updateData.attributes,
  );
  TestValidator.equals(
    "active status remains true",
    updatedVariant.active,
    true,
  );

  // Step 8: Test SKU uniqueness constraint
  await TestValidator.error("duplicate SKU should fail", async () => {
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productId: product.id,
        body: {
          shopping_mall_product_id: product.id,
          variant_name: RandomGenerator.paragraph({ sentences: 2 }),
          sku: updatedVariant.sku, // Duplicate SKU
          price: typia.random<number & tags.Minimum<0> & tags.Maximum<5000>>(),
          stock_quantity: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<500>
          >(),
          attributes: JSON.stringify({
            color: "yellow",
            size: "XXL",
          }),
          active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  });

  // Step 9: Test ownership validation by creating another seller
  const otherSellerEmail: string = typia.random<
    string & tags.Format<"email">
  >();
  const otherSeller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: otherSellerEmail,
        password: "OtherSeller123!",
        business_name: RandomGenerator.paragraph({ sentences: 2 }),
        contact_person: RandomGenerator.name(),
        phone_number: RandomGenerator.mobile(),
        business_address: RandomGenerator.content({ paragraphs: 1 }),
        tax_id: undefined,
        ip: undefined,
        href: "https://shoppingmall.example.com/seller/register",
        referrer: "https://shoppingmall.example.com/",
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(otherSeller);

  // Switch to other seller
  await api.functional.auth.seller.login(connection, {
    body: {
      email: otherSellerEmail,
      password: "OtherSeller123!",
      href: "https://shoppingmall.example.com/seller/dashboard",
      referrer: "https://shoppingmall.example.com/seller/login",
      device: undefined,
      ip: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });

  // Step 10: Verify other seller cannot update the variant
  await TestValidator.error("other seller cannot update variant", async () => {
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productId: product.id,
        variantId: initialVariant.id,
        body: {
          variant_name: "Unauthorized Update",
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  });

  // Step 11: Switch back to original seller and verify can still update
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: "SellerPassword123!",
      href: "https://shoppingmall.example.com/seller/dashboard",
      referrer: "https://shoppingmall.example.com/seller/login",
      device: undefined,
      ip: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });

  const finalUpdate: IShoppingMallProductVariant =
    await api.functional.shoppingMall.seller.products.variants.update(
      connection,
      {
        productId: product.id,
        variantId: initialVariant.id,
        body: {
          variant_name: "Final Authorized Update",
        } satisfies IShoppingMallProductVariant.IUpdate,
      },
    );
  typia.assert(finalUpdate);
  TestValidator.equals(
    "authorized seller can update",
    finalUpdate.variant_name,
    "Final Authorized Update",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
