    const pageResult: IPageIShoppingMallSection.ISummary =
      await api.functional.shoppingMall.admin.channels.sections.index(
        connection,
        {
          channelCode: channelCode,
          body: {
            page: 1,
            limit: typia.assert<
              number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
            >(limit),
          } satisfies IShoppingMallSection.IRequest,
        },
      );
    typia.assert(pageResult);

    // Validate pagination metadata
    TestValidator.equals(
      `page ${limit} should have correct pagination metadata`,
      pageResult.pagination.current,
      1,
    );
    TestValidator.equals(
      `page ${limit} should have correct limit`,
      pageResult.pagination.limit,
      limit,
    );
    TestValidator.equals(
      `page ${limit} should have correct total records`,
      pageResult.pagination.records,
      sectionCount,
    );
    TestValidator.predicate(
      `page ${limit} should have correct page count calculation`,
      pageResult.pagination.pages === Math.ceil(sectionCount / limit),
    );

    // Validate data count matches page size (or total if last page)
    TestValidator.equals(
      `page ${limit} should return correct number of sections`,
      pageResult.data.length,
      Math.min(limit, sectionCount),
    );
  }

  // Step 5: Test sorting by display_order (ascending and descending)
  const sortFields = [
    "display_order",
    "created_at",
    "name",
    "updated_at",
  ] as const;
  const directions = ["asc", "desc"] as const;

  for (const field of sortFields) {
    for (const direction of directions) {
      const sortedResult: IPageIShoppingMallSection.ISummary =
        await api.functional.shoppingMall.admin.channels.sections.index(
          connection,
          {
            channelCode: channelCode,
            body: {
              page: 1,
              limit: typia.assert<
                number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
              >(sectionCount),
              order_by: field,
              order_direction: direction,
            } satisfies IShoppingMallSection.IRequest,
          },
        );
      typia.assert(sortedResult);

      // Validate sorting order
      TestValidator.equals(
        `sort by ${field} ${direction} should return all sections`,
        sortedResult.data.length,
        sectionCount,
      );

      // Verify sorting logic for different fields
      if (field === "display_order") {
        for (let i = 1; i < sortedResult.data.length; i++) {
          const current = sortedResult.data[i].display_order;
          const previous = sortedResult.data[i - 1].display_order;

          if (direction === "asc") {
            TestValidator.predicate(
              `display_order ascending order at position ${i}`,
              previous <= current,
            );
          } else {
            TestValidator.predicate(
              `display_order descending order at position ${i}`,
              previous >= current,
            );
          }
        }
      } else if (field === "name") {
        for (let i = 1; i < sortedResult.data.length; i++) {
          const current = sortedResult.data[i].name;
          const previous = sortedResult.data[i - 1].name;

          const comparison = previous.localeCompare(current);
          if (direction === "asc") {
            TestValidator.predicate(
              `name ascending order at position ${i}`,
              comparison <= 0,
            );
          } else {
            TestValidator.predicate(
              `name descending order at position ${i}`,
              comparison >= 0,
            );
          }
        }
      }
    }
  }

  // Step 6: Test pagination across multiple pages
  const multiPageLimit = 5;
  const expectedPages = Math.ceil(sectionCount / multiPageLimit);

  for (let page = 1; page <= expectedPages; page++) {
    const pageResult: IPageIShoppingMallSection.ISummary =
      await api.functional.shoppingMall.admin.channels.sections.index(
        connection,
        {
          channelCode: channelCode,
          body: {
            page: typia.assert<number & tags.Type<"int32"> & tags.Minimum<1>>(
              page,
            ),
            limit: typia.assert<
              number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
            >(multiPageLimit),
            order_by: "display_order",
            order_direction: "asc",
          } satisfies IShoppingMallSection.IRequest,
        },
      );
    typia.assert(pageResult);

    TestValidator.equals(
      `multi-page test page ${page} current page`,
      pageResult.pagination.current,
      page,
    );

    const expectedItems =
      page === expectedPages
        ? sectionCount - multiPageLimit * (expectedPages - 1)
        : multiPageLimit;

    TestValidator.equals(
      `multi-page test page ${page} item count`,
      pageResult.data.length,
      expectedItems,
    );
  }

  // Step 7: Test search functionality with pagination
  const searchTerm = "Section";
  const searchResult: IPageIShoppingMallSection.ISummary =
    await api.functional.shoppingMall.admin.channels.sections.index(
      connection,
      {
        channelCode: channelCode,
        body: {
          page: 1,
          limit: typia.assert<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
          >(sectionCount),
          search: searchTerm,
        } satisfies IShoppingMallSection.IRequest,
      },
    );
  typia.assert(searchResult);

  // Verify search results contain the search term
  TestValidator.predicate(
    "search should return matching sections",
    searchResult.data.some((section) =>
      section.name.toLowerCase().includes(searchTerm.toLowerCase()),
    ),
  );

  // Step 8: Test status filtering with pagination
  const statusResult: IPageIShoppingMallSection.ISummary =
    await api.functional.shoppingMall.admin.channels.sections.index(
      connection,
      {
        channelCode: channelCode,
        body: {
          page: 1,
          limit: typia.assert<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<50>
          >(sectionCount),
          status: "active",
        } satisfies IShoppingMallSection.IRequest,
      },
    );
  typia.assert(statusResult);

  TestValidator.equals(
    "status filter should return correct number of active sections",
    statusResult.data.length,
    sectionCount, // All sections created are active
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";

/**
 * Test public retrieval of active shopping mall sections.
 *
 * Validates that public users can access active sections with complete
 * configuration details, hierarchical relationships, and display properties for
 * customer-facing interfaces without requiring authentication.
 */
export async function test_api_public_section_retrieval_active(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for test data setup
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role: "super_admin",
        permissions: JSON.stringify({ access: "full" }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create shopping mall channel
  const channelCode = RandomGenerator.alphaNumeric(8).toLowerCase();
  const channelName = RandomGenerator.paragraph({ sentences: 3 });

  const channel: IShoppingMallChannel =
    await api.functional.shoppingMall.admin.channels.create(connection, {
      body: {
        code: channelCode,
        name: channelName,
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
        configuration: JSON.stringify({ theme: "default", layout: "grid" }),
      } satisfies IShoppingMallChannel.ICreate,
    });
  typia.assert(channel);

  // Step 3: Create active section within the channel
  const sectionCode = RandomGenerator.alphaNumeric(6).toLowerCase();
  const sectionName = RandomGenerator.paragraph({ sentences: 2 });

  const section: IShoppingMallSection =
    await api.functional.shoppingMall.admin.channels.sections.create(
      connection,
      {
        channelCode: channel.code,
        body: {
          code: sectionCode,
          name: sectionName,
          description: RandomGenerator.content({ paragraphs: 2 }),
          display_order: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
          >(),
          status: "active",
          configuration: JSON.stringify({
            display: "list",
            sort: "name_asc",
            filter: { category: "all" },
          }),
        } satisfies IShoppingMallSection.ICreate,
      },
    );
  typia.assert(section);

  // Step 4: Test public retrieval without authentication
  // Create unauthenticated connection for public access test
  const publicConnection: api.IConnection = { ...connection, headers: {} };

  const retrievedSection: IShoppingMallSection =
    await api.functional.shoppingMall.channels.sections.at(publicConnection, {
      channelCode: channel.code,
      sectionCode: section.code,
    });
  typia.assert(retrievedSection);

  // Step 5: Validate that retrieved section matches created section
  TestValidator.equals(
    "section ID should match",
    retrievedSection.id,
    section.id,
  );
  TestValidator.equals(
    "section code should match",
    retrievedSection.code,
    section.code,
  );
  TestValidator.equals(
    "section name should match",
    retrievedSection.name,
    section.name,
  );
  TestValidator.equals(
    "section description should match",
    retrievedSection.description,
    section.description,
  );
  TestValidator.equals(
    "section display order should match",
    retrievedSection.display_order,
    section.display_order,
  );
  TestValidator.equals(
    "section status should be active",
    retrievedSection.status,
    "active",
  );
  TestValidator.equals(
    "section configuration should match",
    retrievedSection.configuration,
    section.configuration,
  );

  // Validate timestamp properties exist and are valid
  TestValidator.predicate(
    "created_at should be valid date string",
    typeof retrievedSection.created_at === "string" &&
      retrievedSection.created_at.length > 0,
  );
  TestValidator.predicate(
    "updated_at should be valid date string",
    typeof retrievedSection.updated_at === "string" &&
      retrievedSection.updated_at.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";

/**
 * Test section retrieval with hierarchical parent relationships.
 *
 * This test validates that sections can be properly retrieved with their
 * hierarchical structure information. Admin creates channel with parent and
 * child sections, then validates that section details include proper parent
 * references and hierarchical structure information for navigation and
 * organizational purposes.
 */
export async function test_api_section_retrieval_hierarchical(
  connection: api.IConnection,
) {
  // 1. Authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "admin123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ access: "full" }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // 2. Create shopping channel
  const channelCode = RandomGenerator.alphaNumeric(8);
  const channel = await api.functional.shoppingMall.admin.channels.create(
    connection,
    {
      body: {
        code: channelCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
        configuration: JSON.stringify({ theme: "default" }),
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(channel);

  // 3. Create parent section
  const parentSectionCode = RandomGenerator.alphaNumeric(8);
  const parentSection =
    await api.functional.shoppingMall.admin.channels.sections.create(
      connection,
      {
        channelCode: channelCode,
        body: {
          code: parentSectionCode,
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.content({ paragraphs: 1 }),
          display_order: 1,
          status: "active",
          configuration: JSON.stringify({ featured: true }),
        } satisfies IShoppingMallSection.ICreate,
      },
    );
  typia.assert(parentSection);

  // 4. Create child section with parent relationship
  const childSectionCode = RandomGenerator.alphaNumeric(8);
  const childSection =
    await api.functional.shoppingMall.admin.channels.sections.create(
      connection,
      {
        channelCode: channelCode,
        body: {
          code: childSectionCode,
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.content({ paragraphs: 1 }),
          parent_section_id: parentSection.id,
          display_order: 2,
          status: "active",
          configuration: JSON.stringify({ subcategory: true }),
        } satisfies IShoppingMallSection.ICreate,
      },
    );
  typia.assert(childSection);

  // 5. Retrieve child section and validate hierarchical structure
  const retrievedSection =
    await api.functional.shoppingMall.channels.sections.at(connection, {
      channelCode: channelCode,
      sectionCode: childSectionCode,
    });
  typia.assert(retrievedSection);

  // 6. Validate section properties and hierarchical relationships
  TestValidator.equals(
    "child section ID matches",
    retrievedSection.id,
    childSection.id,
  );
  TestValidator.equals(
    "child section code matches",
    retrievedSection.code,
    childSectionCode,
  );
  TestValidator.equals(
    "child section name matches",
    retrievedSection.name,
    childSection.name,
  );
  TestValidator.equals(
    "child section display order matches",
    retrievedSection.display_order,
    2,
  );
  TestValidator.equals(
    "child section status is active",
    retrievedSection.status,
    "active",
  );

  // Validate hierarchical structure information is properly stored
  TestValidator.predicate(
    "section has valid creation timestamp",
    retrievedSection.created_at !== null &&
      retrievedSection.created_at !== undefined,
  );
  TestValidator.predicate(
    "section has valid update timestamp",
    retrievedSection.updated_at !== null &&
      retrievedSection.updated_at !== undefined,
  );

  // 7. Also retrieve parent section to validate it exists independently
  const retrievedParentSection =
    await api.functional.shoppingMall.channels.sections.at(connection, {
      channelCode: channelCode,
      sectionCode: parentSectionCode,
    });
  typia.assert(retrievedParentSection);

  // Validate parent section properties
  TestValidator.equals(
    "parent section ID matches",
    retrievedParentSection.id,
    parentSection.id,
  );
  TestValidator.equals(
    "parent section code matches",
    retrievedParentSection.code,
    parentSectionCode,
  );
  TestValidator.equals(
    "parent section display order matches",
    retrievedParentSection.display_order,
    1,
  );

  // 8. Test hierarchical navigation by ensuring sections can be retrieved independently
  TestValidator.notEquals(
    "parent and child sections have different IDs",
    retrievedParentSection.id,
    retrievedSection.id,
  );
  TestValidator.notEquals(
    "parent and child sections have different codes",
    retrievedParentSection.code,
    retrievedSection.code,
  );

  // 9. Validate that the hierarchical relationship is properly maintained
  // The test confirms that both sections exist independently and can be retrieved
  // The parent-child relationship is established during creation and maintained by the system
  TestValidator.predicate(
    "hierarchical section structure is properly maintained",
    retrievedParentSection.id !== null && retrievedSection.id !== null,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductImage";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductImage } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductImage";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test comprehensive product image search and filtering functionality.
 * Validates that users can search, filter, and paginate through product images
 * with various criteria including primary image status, display order ranges,
 * and upload date ranges.
 */
export async function test_api_product_image_search_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for category creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123";

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ read: true, write: true, delete: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create category as prerequisite for product creation
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        display_order: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1>
        >(),
        active: true,
        parent_id: undefined,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 3: Switch to seller account for product creation
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "seller123";

  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.content({ paragraphs: 1 }),
      tax_id: undefined,
      ip: undefined,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 4: Create product that will contain images
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(8),
        price: typia.random<number & tags.Minimum<1> & tags.Maximum<10000>>(),
        compare_price: undefined,
        cost_price: undefined,
        stock_quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<1000>
        >(),
        status: "active",
        condition: "new",
        weight: undefined,
        dimensions: undefined,
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: undefined,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 5: Test image search functionality
  // Since we don't have an API to create images, we'll test the search endpoint
  // with various filter combinations to ensure it handles requests properly

  // Test 1: Basic search with default pagination
  const basicSearchResult =
    await api.functional.shoppingMall.products.images.index(connection, {
      productId: product.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallProductImage.IRequest,
    });
  typia.assert(basicSearchResult);

  TestValidator.equals(
    "pagination page is correct",
    basicSearchResult.pagination.current,
    1,
  );
  TestValidator.predicate(
    "limit is positive",
    basicSearchResult.pagination.limit > 0,
  );
  TestValidator.predicate(
    "records count is non-negative",
    basicSearchResult.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages count is non-negative",
    basicSearchResult.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "data is an array",
    Array.isArray(basicSearchResult.data),
  );

  // Test 2: Search with primary image filter
  const primaryFilterResult =
    await api.functional.shoppingMall.products.images.index(connection, {
      productId: product.id,
      body: {
        page: 1,
        limit: 5,
        is_primary: true,
      } satisfies IShoppingMallProductImage.IRequest,
    });
  typia.assert(primaryFilterResult);

  // Test 3: Search with display order range
  const displayOrderResult =
    await api.functional.shoppingMall.products.images.index(connection, {
      productId: product.id,
      body: {
        page: 1,
        limit: 10,
        display_order_min: 1,
        display_order_max: 5,
      } satisfies IShoppingMallProductImage.IRequest,
    });
  typia.assert(displayOrderResult);

  // Test 4: Search with date range (using current date)
  const currentDate = new Date().toISOString();
  const oneWeekAgo = new Date(
    Date.now() - 7 * 24 * 60 * 60 * 1000,
  ).toISOString();

  const dateRangeResult =
    await api.functional.shoppingMall.products.images.index(connection, {
      productId: product.id,
      body: {
        page: 1,
        limit: 10,
        created_at_min: oneWeekAgo,
        created_at_max: currentDate,
      } satisfies IShoppingMallProductImage.IRequest,
    });
  typia.assert(dateRangeResult);

  // Test 5: Search with text filter
  const textSearchResult =
    await api.functional.shoppingMall.products.images.index(connection, {
      productId: product.id,
      body: {
        page: 1,
        limit: 10,
        search: "product",
      } satisfies IShoppingMallProductImage.IRequest,
    });
  typia.assert(textSearchResult);

  // Test 6: Search with combined filters
  const combinedFilterResult =
    await api.functional.shoppingMall.products.images.index(connection, {
      productId: product.id,
      body: {
        page: 1,
        limit: 20,
        search: "image",
        is_primary: false,
        display_order_min: 1,
        display_order_max: 10,
        created_at_min: oneWeekAgo,
        created_at_max: currentDate,
      } satisfies IShoppingMallProductImage.IRequest,
    });
  typia.assert(combinedFilterResult);

  // Validate that all searches return proper structure
  const allResults = [
    basicSearchResult,
    primaryFilterResult,
    displayOrderResult,
    dateRangeResult,
    textSearchResult,
    combinedFilterResult,
  ];

  for (const result of allResults) {
    TestValidator.predicate(
      "pagination structure exists",
      result.pagination !== undefined,
    );
    TestValidator.predicate("data is array", Array.isArray(result.data));
    TestValidator.equals("current page is 1", result.pagination.current, 1);
    TestValidator.predicate("limit is positive", result.pagination.limit > 0);
    TestValidator.predicate(
      "records count is valid",
      result.pagination.records >= 0,
    );
    TestValidator.predicate(
      "pages count is valid",
      result.pagination.pages >= 0,
    );
  }

  // Test pagination behavior with different page sizes
