    body: {
      email: sellerEmail,
      password: sellerPassword,
      ip: undefined,
      href: "https://example.com/seller/login",
      referrer: "https://example.com/seller",
      device: undefined,
    } satisfies IShoppingMallSeller.ILogin,
  });
  typia.assert(loginResult);

