          description: "Initial section description",
          display_order: 1,
          status: "active",
          configuration: JSON.stringify({ layout: "grid" }),
        } satisfies IShoppingMallSection.ICreate,
      },
    );
  typia.assert(initialSection);

  // Step 4: Update section properties with new values
  const updatedSection =
    await api.functional.shoppingMall.admin.channels.sections.update(
      connection,
      {
        channelCode: channelCode,
        sectionCode: sectionCode,
        body: {
          name: "Updated Section Name",
          description: "Updated section description with more details",
          display_order: 5,
          status: "inactive",
          configuration: JSON.stringify({ layout: "list", featured: true }),
        } satisfies IShoppingMallSection.IUpdate,
      },
    );
  typia.assert(updatedSection);

  // Step 5: Validate that all properties were updated correctly
  TestValidator.equals(
    "section ID remains unchanged",
    updatedSection.id,
    initialSection.id,
  );
  TestValidator.equals(
    "section code remains unchanged",
    updatedSection.code,
    initialSection.code,
  );
  TestValidator.equals(
    "channel relationship preserved",
    updatedSection.id,
    initialSection.id,
  );

  TestValidator.notEquals(
    "name should be updated",
    updatedSection.name,
    initialSection.name,
  );
  TestValidator.equals(
    "updated name matches expected",
    updatedSection.name,
    "Updated Section Name",
  );

  TestValidator.notEquals(
    "description should be updated",
    updatedSection.description,
    initialSection.description,
  );
  TestValidator.equals(
    "updated description matches expected",
    updatedSection.description,
    "Updated section description with more details",
  );

  TestValidator.notEquals(
    "display order should be updated",
    updatedSection.display_order,
    initialSection.display_order,
  );
  TestValidator.equals(
    "updated display order matches expected",
    updatedSection.display_order,
    5,
  );

  TestValidator.notEquals(
    "status should be updated",
    updatedSection.status,
    initialSection.status,
  );
  TestValidator.equals(
    "updated status matches expected",
    updatedSection.status,
    "inactive",
  );

  TestValidator.predicate(
    "updated timestamp should be later than creation",
    new Date(updatedSection.updated_at) > new Date(initialSection.updated_at),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";

/**
 * Test section status transitions and lifecycle management through update
 * operations. Validates that sections can be moved between active, inactive,
 * hidden, and archived states with appropriate business rule enforcement.
 * Ensures that status changes respect channel policies and maintain proper
 * visibility controls for customer-facing interfaces.
 */
export async function test_api_channel_section_status_transition(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword123!",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({
        channel_management: true,
        section_management: true,
        user_management: true,
      }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create a shopping channel for section lifecycle testing
  const channelCode = RandomGenerator.alphaNumeric(8);
  const channel = await api.functional.shoppingMall.admin.channels.create(
    connection,
    {
      body: {
        code: channelCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        status: "active",
        configuration: JSON.stringify({
          allow_section_creation: true,
          max_sections: 50,
          default_section_status: "active",
        }),
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(channel);

  // Step 3: Create a section with initial status
  const sectionCode = RandomGenerator.alphaNumeric(8);
  const initialSection =
    await api.functional.shoppingMall.admin.channels.sections.create(
      connection,
      {
        channelCode: channel.code,
        body: {
          code: sectionCode,
          name: RandomGenerator.paragraph({ sentences: 2 }),
          description: RandomGenerator.content({ paragraphs: 1 }),
          display_order: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<1000>
          >(),
          status: "active",
          configuration: JSON.stringify({
            allow_product_addition: true,
            max_products: 1000,
            visibility: "public",
          }),
        } satisfies IShoppingMallSection.ICreate,
      },
    );
  typia.assert(initialSection);
  TestValidator.equals(
    "section should be created with active status",
    initialSection.status,
    "active",
  );

  // Step 4: Test status transitions through update operations
  const statusTransitions = [
    "inactive",
    "hidden",
    "archived",
    "active",
  ] as const;

  // Initialize section variable for the transition loop
  let section = initialSection;

  for (const targetStatus of statusTransitions) {
    // Update section with new status
    const updatedSection =
      await api.functional.shoppingMall.admin.channels.sections.update(
        connection,
        {
          channelCode: channel.code,
          sectionCode: section.code,
          body: {
            status: targetStatus,
          } satisfies IShoppingMallSection.IUpdate,
        },
      );
    typia.assert(updatedSection);

    // Validate that status was properly updated
    TestValidator.equals(
      "section status should be updated",
      updatedSection.status,
      targetStatus,
    );
    TestValidator.equals(
      "section ID should remain the same",
      updatedSection.id,
      initialSection.id,
    );
    TestValidator.equals(
      "section code should remain the same",
      updatedSection.code,
      initialSection.code,
    );
    TestValidator.equals(
      "section name should remain the same",
      updatedSection.name,
      initialSection.name,
    );

    // Verify that other properties are preserved
    TestValidator.equals(
      "display order should be preserved",
      updatedSection.display_order,
      initialSection.display_order,
    );
    TestValidator.equals(
      "description should be preserved",
      updatedSection.description,
      initialSection.description,
    );
    TestValidator.equals(
      "configuration should be preserved",
      updatedSection.configuration,
      initialSection.configuration,
    );

    // Update the current section reference for next iteration
    section = updatedSection;
  }

  // Step 5: Test partial updates with multiple properties
  const finalUpdate =
    await api.functional.shoppingMall.admin.channels.sections.update(
      connection,
      {
        channelCode: channel.code,
        sectionCode: section.code,
        body: {
          name: RandomGenerator.paragraph({ sentences: 2 }),
          display_order: typia.random<
            number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<1000>
          >(),
          status: "inactive",
          description: RandomGenerator.content({ paragraphs: 1 }),
        } satisfies IShoppingMallSection.IUpdate,
      },
    );
  typia.assert(finalUpdate);

  // Validate final state
  TestValidator.equals(
    "final status should be inactive",
    finalUpdate.status,
    "inactive",
  );
  TestValidator.notEquals(
    "name should be updated",
    finalUpdate.name,
    initialSection.name,
  );
  TestValidator.notEquals(
    "display order should be updated",
    finalUpdate.display_order,
    initialSection.display_order,
  );
  TestValidator.notEquals(
    "description should be updated",
    finalUpdate.description,
    initialSection.description,
  );
  TestValidator.equals(
    "section ID should remain constant",
    finalUpdate.id,
    initialSection.id,
  );
  TestValidator.equals(
    "section code should remain constant",
    finalUpdate.code,
    initialSection.code,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";

/**
 * Test comprehensive configuration updates for shopping mall sections.
 *
 * This E2E test validates that section-specific settings, display options, and
 * behavioral configurations can be modified through update operations. Ensures
 * that configuration JSON is properly validated, stored, and applied to section
 * behavior within the channel context.
 *
 * The test follows a complete workflow:
 *
 * 1. Administrator authentication setup
 * 2. Channel creation for section hosting
 * 3. Initial section creation with basic configuration
 * 4. Comprehensive configuration updates
 * 5. Validation of persisted changes
 */
export async function test_api_channel_section_configuration_update(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword123!",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({
        channel_management: true,
        section_management: true,
        configuration_management: true,
      }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create a shopping channel to host sections
  const channelCode = RandomGenerator.alphaNumeric(8).toLowerCase();
  const channel = await api.functional.shoppingMall.admin.channels.create(
    connection,
    {
      body: {
        code: channelCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        status: "active",
        configuration: JSON.stringify({
          theme: "modern",
          layout: "grid",
          maxSections: 20,
        }),
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(channel);

  // Step 3: Create an initial section with basic configuration
  const sectionCode = RandomGenerator.alphaNumeric(6).toLowerCase();
  const initialSection =
    await api.functional.shoppingMall.admin.channels.sections.create(
      connection,
      {
        channelCode: channelCode,
        body: {
          code: sectionCode,
          name: "Initial Section",
          description: "Initial section description for testing",
          display_order: 1,
          status: "active",
          configuration: JSON.stringify({
            displayMode: "list",
            itemsPerPage: 10,
            sortBy: "name",
            filterEnabled: true,
          }),
        } satisfies IShoppingMallSection.ICreate,
      },
    );
  typia.assert(initialSection);

  // Step 4: Perform comprehensive configuration updates
  const updatedSection =
    await api.functional.shoppingMall.admin.channels.sections.update(
      connection,
      {
        channelCode: channelCode,
        sectionCode: sectionCode,
        body: {
          name: "Updated Section Name",
          description: "Updated section description with enhanced features",
          display_order: 2,
          status: "hidden",
          configuration: JSON.stringify({
            displayMode: "grid",
            itemsPerPage: 20,
            sortBy: "price",
            filterEnabled: false,
          }),
        } satisfies IShoppingMallSection.IUpdate,
      },
    );
  typia.assert(updatedSection);

  // Step 5: Validate that all updates are properly persisted
  TestValidator.equals(
    "section name should be updated",
    updatedSection.name,
    "Updated Section Name",
  );
  TestValidator.equals(
    "section description should be updated",
    updatedSection.description,
    "Updated section description with enhanced features",
  );
  TestValidator.equals(
    "display order should be updated",
    updatedSection.display_order,
    2,
  );
  TestValidator.equals(
    "status should be updated",
    updatedSection.status,
    "hidden",
  );

  // Validate configuration JSON parsing and structure
  const parsedConfig = JSON.parse(updatedSection.configuration ?? "{}");
  TestValidator.equals(
    "displayMode should be updated",
    parsedConfig.displayMode,
    "grid",
  );
  TestValidator.equals(
    "itemsPerPage should be updated",
    parsedConfig.itemsPerPage,
    20,
  );
  TestValidator.equals(
    "sortBy should be updated",
    parsedConfig.sortBy,
    "price",
  );
  TestValidator.predicate(
    "filterEnabled should be false",
    parsedConfig.filterEnabled === false,
  );

  // Step 6: Test timestamp updates
  TestValidator.notEquals(
    "updated_at should be different from created_at",
    updatedSection.updated_at,
    initialSection.created_at,
  );
  TestValidator.predicate(
    "updated_at should be after created_at",
    new Date(updatedSection.updated_at) > new Date(initialSection.created_at),
  );

  // Step 7: Test partial updates (only update specific fields)
  const partiallyUpdatedSection =
    await api.functional.shoppingMall.admin.channels.sections.update(
      connection,
      {
        channelCode: channelCode,
        sectionCode: sectionCode,
        body: {
          status: "active",
        } satisfies IShoppingMallSection.IUpdate,
      },
    );
  typia.assert(partiallyUpdatedSection);

  // Validate partial update preserved other fields
  TestValidator.equals(
    "name should remain unchanged after partial update",
    partiallyUpdatedSection.name,
    "Updated Section Name",
  );
  TestValidator.equals(
    "description should remain unchanged after partial update",
    partiallyUpdatedSection.description,
    "Updated section description with enhanced features",
  );
  TestValidator.equals(
    "display_order should remain unchanged after partial update",
    partiallyUpdatedSection.display_order,
    2,
  );
  TestValidator.equals(
    "status should be updated in partial update",
    partiallyUpdatedSection.status,
    "active",
  );

  // Step 8: Test configuration-only update
  const configOnlyUpdate =
    await api.functional.shoppingMall.admin.channels.sections.update(
      connection,
      {
        channelCode: channelCode,
        sectionCode: sectionCode,
        body: {
          configuration: JSON.stringify({
            displayMode: "carousel",
            itemsPerPage: 5,
            sortBy: "popularity",
            autoPlay: true,
            autoPlayInterval: 5000,
          }),
        } satisfies IShoppingMallSection.IUpdate,
      },
    );
  typia.assert(configOnlyUpdate);

  // Validate configuration-only update
  const finalConfig = JSON.parse(configOnlyUpdate.configuration ?? "{}");
  TestValidator.equals(
    "displayMode should be carousel",
    finalConfig.displayMode,
    "carousel",
  );
  TestValidator.equals("itemsPerPage should be 5", finalConfig.itemsPerPage, 5);
  TestValidator.equals(
    "sortBy should be popularity",
    finalConfig.sortBy,
    "popularity",
  );
  TestValidator.predicate(
    "autoPlay should be enabled",
    finalConfig.autoPlay === true,
  );
  TestValidator.equals(
    "autoPlayInterval should be 5000",
    finalConfig.autoPlayInterval,
    5000,
  );

  // Final validation: Ensure all business fields remain consistent
  TestValidator.equals(
    "section ID should remain constant throughout updates",
    configOnlyUpdate.id,
    initialSection.id,
  );
  TestValidator.equals(
    "section code should remain constant",
    configOnlyUpdate.code,
    sectionCode,
  );
  TestValidator.predicate(
    "final updated_at should be most recent",
    new Date(configOnlyUpdate.updated_at) >
      new Date(partiallyUpdatedSection.updated_at),
  );

  // Test error scenario: Invalid configuration JSON
  await TestValidator.error(
    "invalid JSON configuration should fail",
    async () => {
      await api.functional.shoppingMall.admin.channels.sections.update(
        connection,
        {
          channelCode: channelCode,
          sectionCode: sectionCode,
          body: {
            configuration: "invalid json format",
          } satisfies IShoppingMallSection.IUpdate,
        },
      );
    },
  );
}

