/**
 * Test product image deletion workflow where a seller creates a product with
 * multiple images and then deletes a specific image. Validates that image
 * deletion removes the image from the product gallery while maintaining proper
 * display order for remaining images.
 */
export async function test_api_product_image_deletion_by_seller(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for category creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "admin123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ manage_categories: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create product category
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        display_order: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1>
        >(),
        active: true,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 3: Create seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: "seller123",
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.paragraph({ sentences: 3 }),
      tax_id: "123-45-6789",
      href: "https://shoppingmall.example.com/seller/dashboard",
      referrer: "https://shoppingmall.example.com/join",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 4: Create product
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(8),
        price: typia.random<number & tags.Minimum<1> & tags.Maximum<10000>>(),
        compare_price: typia.random<
          number & tags.Minimum<10001> & tags.Maximum<20000>
        >(),
        stock_quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<1000>
        >(),
        status: "active",
        condition: "new",
        weight: typia.random<number & tags.Minimum<0.1> & tags.Maximum<50>>(),
        dimensions: "10x5x3",
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: category.parent,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 5: Create multiple product images
  const images = await ArrayUtil.asyncRepeat(3, async (index) => {
    const image =
      await api.functional.shoppingMall.seller.products.images.create(
        connection,
        {
          productId: product.id,
          body: {
            image_url: `https://example.com/images/product-${product.id}-${index}.jpg`,
            alt_text: `Product image ${index + 1} for ${product.name}`,
            is_primary: index === 0,
            display_order: index + 1,
          } satisfies IShoppingMallProductImage.ICreate,
        },
      );
    typia.assert(image);
    return image;
  });

  // Step 6: Delete the second image
  await api.functional.shoppingMall.seller.products.images.erase(connection, {
    productId: product.id,
    imageId: images[1].id,
  });

  // Step 7: Validate deletion by ensuring remaining images are intact
  TestValidator.equals(
    "first image should remain primary",
    images[0].is_primary,
    true,
  );
  TestValidator.equals(
    "third image display order should remain unchanged",
    images[2].display_order,
    3,
  );

  // Step 8: Test unauthorized deletion attempt by different seller
  const otherSellerEmail = typia.random<string & tags.Format<"email">>();
  const otherSeller = await api.functional.auth.seller.join(connection, {
    body: {
      email: otherSellerEmail,
      password: "seller456",
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.paragraph({ sentences: 3 }),
      href: "https://shoppingmall.example.com/seller/dashboard",
      referrer: "https://shoppingmall.example.com/join",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(otherSeller);

  // Switch authentication to the other seller
  await api.functional.auth.seller.login(connection, {
    body: {
      email: otherSellerEmail,
      password: "seller456",
      href: "https://shoppingmall.example.com/seller/dashboard",
      referrer: "https://shoppingmall.example.com/login",
    } satisfies IShoppingMallSeller.ILogin,
  });

  await TestValidator.error(
    "other seller cannot delete images they don't own",
    async () => {
      await api.functional.shoppingMall.seller.products.images.erase(
        connection,
        {
          productId: product.id,
          imageId: images[0].id,
        },
      );
    },
  );

  // Step 9: Switch back to original seller and validate hard delete
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: "seller123",
      href: "https://shoppingmall.example.com/seller/dashboard",
      referrer: "https://shoppingmall.example.com/login",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // Attempt to delete already deleted image (should fail)
  await TestValidator.error(
    "deleting non-existent image should fail",
    async () => {
      await api.functional.shoppingMall.seller.products.images.erase(
        connection,
        {
          productId: product.id,
          imageId: images[1].id, // This image was already deleted
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCart";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test comprehensive cart search functionality for administrators with various
 * filtering criteria. This test validates that administrators can search cart
 * sessions by status (active, abandoned, converted, expired), creation date
 * ranges, expiration timelines, shipping methods, and applied coupon codes. The
 * test also verifies pagination works correctly with page numbers and limits,
 * ensuring proper record counts and page calculations.
 */
export async function test_api_admin_cart_search_with_filters(
  connection: api.IConnection,
) {
  // Create administrator account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123";

  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role: "super_admin",
        permissions: JSON.stringify({ access: "full" }),
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Create customer accounts and authenticate them to get sessions
  const customerEmails = ArrayUtil.repeat(3, () =>
    typia.random<string & tags.Format<"email">>(),
  );

  const customerSessions: string[] = [];

  for (const email of customerEmails) {
    // Create customer account
    const customer: IShoppingMallCustomer.IAuthorized =
      await api.functional.auth.customer.join(connection, {
        body: {
          email,
          password: "customer123",
          first_name: RandomGenerator.name(1),
          last_name: RandomGenerator.name(1),
          href: "https://example.com/register",
          referrer: "https://example.com",
        } satisfies IShoppingMallCustomer.ICreate,
      });
    typia.assert(customer);

    // Authenticate customer to get session
    const authenticatedCustomer: IShoppingMallCustomer.IAuthorized =
      await api.functional.auth.customer.login(connection, {
        body: {
          email,
          password: "customer123",
          href: "https://example.com/login",
          referrer: "https://example.com",
        } satisfies IShoppingMallCustomer.ILogin,
      });
    typia.assert(authenticatedCustomer);

    customerSessions.push(authenticatedCustomer.id);
  }

  // Create test carts with various configurations
  const shippingMethods = ["standard", "express", "overnight"] as const;
  const couponCodes = ["SAVE10", "WELCOME20", "SUMMER25"] as const;

  const testCarts: IShoppingMallCart[] = [];

  for (let i = 0; i < 6; i++) {
    const sessionId = RandomGenerator.pick(customerSessions);
    const shippingMethod = RandomGenerator.pick(shippingMethods);
    const couponCode =
      i % 2 === 0 ? RandomGenerator.pick(couponCodes) : undefined;

    const cart: IShoppingMallCart =
      await api.functional.shoppingMall.customer.carts.create(connection, {
        body: {
          shopping_mall_customer_session_id: sessionId,
          shipping_method: shippingMethod,
          applied_coupon_code: couponCode,
        } satisfies IShoppingMallCart.ICreate,
      });
    typia.assert(cart);
    testCarts.push(cart);
  }

  // Test basic pagination
  const basicSearch: IPageIShoppingMallCart.ISummary =
    await api.functional.shoppingMall.admin.carts.index(connection, {
      body: {
        page: 1,
        limit: 5,
      } satisfies IShoppingMallCart.IRequest,
    });
  typia.assert(basicSearch);

  TestValidator.predicate(
    "pagination should return valid data",
    basicSearch.data.length >= 0,
  );
  TestValidator.predicate(
    "pagination should have valid record count",
    basicSearch.pagination.records >= 0,
  );

  // Test different status filters if carts exist
  if (basicSearch.data.length > 0) {
    const availableStatuses = ArrayUtil.repeat(
      basicSearch.data.length,
      (i) => basicSearch.data[i].status,
    ).filter((status, index, array) => array.indexOf(status) === index);

    for (const status of availableStatuses.slice(0, 2)) {
      const statusSearch: IPageIShoppingMallCart.ISummary =
        await api.functional.shoppingMall.admin.carts.index(connection, {
          body: {
            page: 1,
            limit: 10,
            status,
          } satisfies IShoppingMallCart.IRequest,
        });
      typia.assert(statusSearch);

      TestValidator.predicate(
        `status filtered carts should have correct status: ${status}`,
        statusSearch.data.every((cart) => cart.status === status),
      );
    }
  }

  // Test shipping method filtering
  const shippingSearch: IPageIShoppingMallCart.ISummary =
    await api.functional.shoppingMall.admin.carts.index(connection, {
      body: {
        page: 1,
        limit: 10,
        shipping_method: "standard",
      } satisfies IShoppingMallCart.IRequest,
    });
  typia.assert(shippingSearch);

  // Test coupon code filtering
  const couponSearch: IPageIShoppingMallCart.ISummary =
    await api.functional.shoppingMall.admin.carts.index(connection, {
      body: {
        page: 1,
        limit: 10,
        applied_coupon_code: "SAVE10",
      } satisfies IShoppingMallCart.IRequest,
    });
  typia.assert(couponSearch);

  // Test date range filtering with realistic dates
  const now = new Date();
  const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

  const dateSearch: IPageIShoppingMallCart.ISummary =
    await api.functional.shoppingMall.admin.carts.index(connection, {
      body: {
        page: 1,
        limit: 10,
        created_at_start: oneHourAgo.toISOString(),
        created_at_end: now.toISOString(),
      } satisfies IShoppingMallCart.IRequest,
    });
  typia.assert(dateSearch);

  // Test combined filters
