      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ can_create_shipments: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 4: Create multiple shipments with different statuses
  const shipmentStatuses = [
    "label_created",
    "picked_up",
    "in_transit",
    "delivered",
  ] as const;
  const createdShipments: IShoppingMallShipment[] = [];

  for (const status of shipmentStatuses) {
    const shipment =
      await api.functional.shoppingMall.admin.orders.shipments.create(
        connection,
        {
          orderId: order.id,
          body: {
            carrier: RandomGenerator.pick([
              "UPS",
              "FedEx",
              "USPS",
              "DHL",
            ] as const),
            tracking_number: RandomGenerator.alphaNumeric(12),
            shipping_method: RandomGenerator.pick([
              "standard",
              "express",
              "overnight",
            ] as const),
            shipping_cost: typia.random<
              number & tags.Minimum<5> & tags.Maximum<50>
            >(),
            status: status,
            estimated_delivery: new Date(
              Date.now() + 86400000 * 7,
            ).toISOString(),
            shipping_label_url: `https://shipping.com/labels/${RandomGenerator.alphaNumeric(10)}`,
            tracking_url: `https://tracking.com/${RandomGenerator.alphaNumeric(15)}`,
          } satisfies IShoppingMallShipment.ICreate,
        },
      );
    typia.assert(shipment);
    createdShipments.push(shipment);
  }

  // Step 5: Switch back to customer authentication
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://shoppingmall.com/tracking",
      referrer: "https://shoppingmall.com/orders",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Step 6: Test filtering by each delivery status
  for (const status of shipmentStatuses) {
    const filteredShipments =
      await api.functional.shoppingMall.customer.orders.shipments.index(
        connection,
        {
          orderId: order.id,
          body: {
            status: status,
            page: 1,
            limit: 10,
          } satisfies IShoppingMallShipment.IRequest,
        },
      );
    typia.assert(filteredShipments);

    // Validate that all returned shipments have the requested status
    TestValidator.predicate(
      `filtered shipments should have status ${status}`,
      filteredShipments.data.every((shipment) => shipment.status === status),
    );

    // Validate pagination structure
    TestValidator.predicate(
      `pagination should be valid for status ${status}`,
      filteredShipments.pagination.current === 1 &&
        filteredShipments.pagination.limit === 10 &&
        filteredShipments.pagination.records >= 0 &&
        filteredShipments.pagination.pages >= 0,
    );

    // Count should match expected number of shipments with this status
    const expectedCount = createdShipments.filter(
      (s) => s.status === status,
    ).length;
    TestValidator.equals(
      `shipment count should match for status ${status}`,
      filteredShipments.data.length,
      expectedCount,
    );
  }

  // Step 7: Test without status filter (should return all shipments)
  const allShipments =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(allShipments);

  TestValidator.equals(
    "unfiltered request should return all shipments",
    allShipments.data.length,
    createdShipments.length,
  );

  // Step 8: Test search functionality with carrier filter
  const testCarrier = createdShipments[0].carrier;
  const carrierFiltered =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          carrier: testCarrier,
          page: 1,
          limit: 10,
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(carrierFiltered);

  TestValidator.predicate(
    `carrier filtered shipments should match ${testCarrier}`,
    carrierFiltered.data.every((shipment) => shipment.carrier === testCarrier),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallShipment";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";

/**
 * Test shipment pagination functionality for orders with multiple shipments.
 *
 * This comprehensive E2E test validates that customers can efficiently browse
 * through multiple shipments using page-based navigation with proper result
 * limiting. The test follows a complete business workflow including customer
 * registration, order creation, administrator setup, multiple shipment
 * creation, and pagination testing with different page sizes and limits.
 */
export async function test_api_customer_shipment_pagination_for_large_orders(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customer123";

  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create an order for the customer
  const order = await api.functional.shoppingMall.customer.orders.create(
    connection,
    {
      body: {
        currency: "USD",
        shipping_address: `${RandomGenerator.name(1)} ${RandomGenerator.name(1)}, ${RandomGenerator.paragraph({ sentences: 2 })}`,
        billing_address: `${RandomGenerator.name(1)} ${RandomGenerator.name(1)}, ${RandomGenerator.paragraph({ sentences: 2 })}`,
        items: ArrayUtil.repeat(
          3,
          () =>
            ({
              shopping_mall_product_variant_id: typia.random<
                string & tags.Format<"uuid">
              >(),
              quantity: typia.random<
                number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
              >(),
            }) satisfies IShoppingMallOrderItem.ICreate,
        ),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);

  // Step 3: Create and authenticate administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123";

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ can_create_shipments: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 4: Create multiple shipments for the order
  const carriers = ["UPS", "FedEx", "DHL", "USPS"] as const;
  const shippingMethods = ["standard", "express", "overnight"] as const;
  const statuses = [
    "label_created",
    "picked_up",
    "in_transit",
    "out_for_delivery",
    "delivered",
  ] as const;

  const createdShipments: IShoppingMallShipment[] = [];

  for (let i = 0; i < 15; i++) {
    const shipment =
      await api.functional.shoppingMall.admin.orders.shipments.create(
        connection,
        {
          orderId: order.id,
          body: {
            carrier: RandomGenerator.pick(carriers),
            tracking_number: `TRK${typia.random<number & tags.Type<"uint32"> & tags.Minimum<1000000> & tags.Maximum<9999999>>()}`,
            shipping_method: RandomGenerator.pick(shippingMethods),
            shipping_cost: typia.random<
              number & tags.Minimum<5> & tags.Maximum<50>
            >(),
            status: RandomGenerator.pick(statuses),
            estimated_delivery: new Date(
              Date.now() +
                typia.random<
                  number &
                    tags.Type<"uint32"> &
                    tags.Minimum<86400000> &
                    tags.Maximum<604800000>
                >(),
            ).toISOString(),
            shipping_label_url: `https://example.com/labels/${typia.random<string & tags.Format<"uuid">>()}`,
            tracking_url: `https://tracking.example.com/${typia.random<string & tags.Format<"uuid">>()}`,
          } satisfies IShoppingMallShipment.ICreate,
        },
      );
    typia.assert(shipment);
    createdShipments.push(shipment);
  }

  // Step 5: Switch back to customer authentication
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://example.com/track",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Step 6: Test pagination with different page sizes

  // Test 1: Default pagination (first page with default limit)
  const firstPage =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          page: 1,
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(firstPage);

  TestValidator.equals(
    "first page should have data",
    firstPage.data.length > 0,
    true,
  );
  TestValidator.predicate(
    "pagination metadata should be valid",
    firstPage.pagination.current === 1 &&
      firstPage.pagination.limit > 0 &&
      firstPage.pagination.records >= createdShipments.length &&
      firstPage.pagination.pages >=
        Math.ceil(createdShipments.length / firstPage.pagination.limit),
  );

  // Test 2: Small page size (limit = 5)
  const smallPage =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          page: 1,
          limit: 5,
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(smallPage);

  TestValidator.equals(
    "small page should have exactly 5 items",
    smallPage.data.length,
    5,
  );
  TestValidator.predicate(
    "small page pagination should be correct",
    smallPage.pagination.limit === 5 &&
      smallPage.pagination.pages === Math.ceil(createdShipments.length / 5),
  );

  // Test 3: Large page size (limit = 20)
  const largePage =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          page: 1,
          limit: 20,
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(largePage);

  TestValidator.predicate(
    "large page should contain all or most shipments",
    largePage.data.length >= createdShipments.length ||
      largePage.data.length === largePage.pagination.limit,
  );

  // Test 4: Navigate to second page
  const secondPage =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          page: 2,
          limit: 5,
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(secondPage);

  TestValidator.equals(
    "second page should have data",
    secondPage.data.length > 0,
    true,
  );
  TestValidator.equals(
    "second page should be page 2",
    secondPage.pagination.current,
    2,
  );

  // Test 5: Verify shipment data integrity
  const allShipmentsFromPages: IShoppingMallShipment.ISummary[] = [];

  // Collect all shipments from all pages
  for (let pageNum = 1; pageNum <= smallPage.pagination.pages; pageNum++) {
    const pageResult =
      await api.functional.shoppingMall.customer.orders.shipments.index(
        connection,
        {
          orderId: order.id,
          body: {
            page: pageNum,
            limit: 5,
          } satisfies IShoppingMallShipment.IRequest,
        },
      );
    typia.assert(pageResult);
    allShipmentsFromPages.push(...pageResult.data);
  }

  // Verify we got all shipments
  TestValidator.equals(
    "should retrieve all created shipments",
    allShipmentsFromPages.length,
    Math.min(createdShipments.length, smallPage.pagination.records),
  );

  // Test 6: Filter by carrier
  const testCarrier = createdShipments[0]?.carrier;
  if (testCarrier) {
    const filteredPage =
      await api.functional.shoppingMall.customer.orders.shipments.index(
        connection,
        {
          orderId: order.id,
          body: {
            page: 1,
            limit: 10,
            carrier: testCarrier,
          } satisfies IShoppingMallShipment.IRequest,
        },
      );
    typia.assert(filteredPage);

    TestValidator.predicate(
      "filtered page should only contain selected carrier",
      filteredPage.data.every((shipment) => shipment.carrier === testCarrier),
    );
  }

  // Test 7: Sort by creation date
  const sortedPage =
    await api.functional.shoppingMall.customer.orders.shipments.index(
      connection,
      {
        orderId: order.id,
        body: {
          page: 1,
          limit: 10,
          order_by: "created_at",
          direction: "desc",
        } satisfies IShoppingMallShipment.IRequest,
      },
    );
  typia.assert(sortedPage);

  // Verify sorting (most recent first)
  if (sortedPage.data.length > 1) {
    const dates = sortedPage.data.map((shipment) =>
      new Date(shipment.created_at).getTime(),
    );
    TestValidator.predicate(
      "shipments should be sorted by creation date descending",
      dates.every((date, index, arr) => index === 0 || date <= arr[index - 1]),
    );
  }

  // Final validation: Ensure pagination metadata consistency
  TestValidator.predicate(
    "total records should be consistent across pagination calls",
    firstPage.pagination.records === smallPage.pagination.records &&
      smallPage.pagination.records === largePage.pagination.records,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCart } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCart";
import type { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test cart item quantity update workflow where a customer modifies the
 * quantity of a product in their shopping cart. The scenario validates that
 * quantity updates are properly reflected in the cart item, pricing
 * calculations remain consistent with the original unit price, and inventory
 * validation prevents overselling. Customer authentication is established
 * through join operation, followed by cart creation, product variant setup
 * through seller operations, cart item addition, and finally the quantity
 * update operation.
 */
export async function test_api_cart_item_update_quantity_by_customer(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "customer123",
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create and authenticate seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: "seller123",
      business_name: RandomGenerator.name(),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.paragraph({ sentences: 1 }),
      href: "https://example.com/seller/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 3: Create admin and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "admin123",
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      role: "super_admin",
      permissions: JSON.stringify({ all: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 4: Create product category
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        display_order: 1,
        active: true,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Switch to seller authentication for product creation
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: "seller123",
      href: "https://example.com/seller/dashboard",
      referrer: "https://example.com",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // Step 5: Create product
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(10),
        price: 1000,
        stock_quantity: 100,
        status: "active",
        condition: "new",
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: category.parent,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Step 6: Create product variant
  const productVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productId: product.id,
        body: {
          shopping_mall_product_id: product.id,
          variant_name: RandomGenerator.name(),
          sku: RandomGenerator.alphaNumeric(8),
          price: 1200,
          stock_quantity: 50,
          attributes: JSON.stringify({ size: "large", color: "blue" }),
          active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(productVariant);

  // Switch back to customer authentication
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "customer123",
      href: "https://example.com/shop",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Step 7: Create shopping cart
  const cart = await api.functional.shoppingMall.customer.carts.create(
    connection,
    {
      body: {
        shopping_mall_customer_session_id: typia.random<
          string & tags.Format<"uuid">
        >(),
      } satisfies IShoppingMallCart.ICreate,
    },
  );
  typia.assert(cart);

  // Step 8: Add item to cart with initial quantity
  const initialQuantity = 2;
  const cartItem =
    await api.functional.shoppingMall.customer.carts.items.create(connection, {
      cartId: cart.id,
      body: {
        cart_id: cart.id,
        product_variant_id: productVariant.id,
        quantity: initialQuantity,
        notes: "Initial purchase",
      } satisfies IShoppingMallCartItem.ICreate,
    });
  typia.assert(cartItem);

  // Validate initial cart item properties
  TestValidator.equals(
    "cart item should have correct initial quantity",
    cartItem.quantity,
    initialQuantity,
  );
  TestValidator.equals(
    "cart item should have correct unit price",
    cartItem.unit_price,
    productVariant.price ?? product.price,
  );
  TestValidator.equals(
    "cart item should reference correct cart",
    cartItem.shopping_mall_cart_id,
    cart.id,
  );
  TestValidator.equals(
    "cart item should reference correct product variant",
    cartItem.shopping_mall_product_variant_id,
    productVariant.id,
  );

  // Step 9: Update cart item quantity
  const updatedQuantity = 5;
  const updatedCartItem =
    await api.functional.shoppingMall.customer.carts.items.putByCartidAndItemid(
      connection,
      {
        cartId: cart.id,
        itemId: cartItem.id,
        body: {
          quantity: updatedQuantity,
          notes: "Increased quantity",
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(updatedCartItem);

  // Validate updated cart item properties
  TestValidator.equals(
    "cart item quantity should be updated",
    updatedCartItem.quantity,
    updatedQuantity,
  );
  TestValidator.equals(
    "cart item unit price should remain consistent",
    updatedCartItem.unit_price,
    cartItem.unit_price,
  );
  TestValidator.equals(
    "cart item ID should remain the same",
    updatedCartItem.id,
    cartItem.id,
  );
  TestValidator.equals(
    "cart reference should remain the same",
    updatedCartItem.shopping_mall_cart_id,
    cartItem.shopping_mall_cart_id,
  );
  TestValidator.equals(
    "product variant reference should remain the same",
    updatedCartItem.shopping_mall_product_variant_id,
    cartItem.shopping_mall_product_variant_id,
  );
  TestValidator.notEquals(
    "updated at timestamp should change",
    updatedCartItem.updated_at,
    cartItem.updated_at,
  );
  TestValidator.equals(
    "added at timestamp should remain the same",
    updatedCartItem.added_at,
    cartItem.added_at,
  );

  // Test error scenario: quantity exceeds available inventory
  await TestValidator.error(
    "should fail when quantity exceeds available inventory",
    async () => {
      await api.functional.shoppingMall.customer.carts.items.putByCartidAndItemid(
        connection,
        {
          cartId: cart.id,
          itemId: cartItem.id,
          body: {
            quantity: productVariant.stock_quantity + 10,
          } satisfies IShoppingMallCartItem.IUpdate,
        },
      );
    },
  );

  // Test error scenario: invalid cart item ID
  await TestValidator.error(
    "should fail when cart item ID is invalid",
    async () => {
      await api.functional.shoppingMall.customer.carts.items.putByCartidAndItemid(
        connection,
        {
          cartId: cart.id,
          itemId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            quantity: 3,
          } satisfies IShoppingMallCartItem.IUpdate,
        },
      );
    },
  );

  // Test partial update: update only notes without changing quantity
  const finalCartItem =
    await api.functional.shoppingMall.customer.carts.items.putByCartidAndItemid(
      connection,
      {
        cartId: cart.id,
        itemId: cartItem.id,
        body: {
          notes: "Final notes update",
        } satisfies IShoppingMallCartItem.IUpdate,
      },
    );
  typia.assert(finalCartItem);

  // Validate partial update
  TestValidator.equals(
    "quantity should remain unchanged during notes update",
    finalCartItem.quantity,
    updatedQuantity,
  );
  TestValidator.equals(
    "notes should be updated",
    finalCartItem.notes,
    "Final notes update",
  );
  TestValidator.equals(
    "unit price should remain consistent",
    finalCartItem.unit_price,
    cartItem.unit_price,
  );
}

