  const updatedShipment =
    await api.functional.shoppingMall.admin.orders.shipments.update(
      connection,
      {
        orderId: order.id,
        shipmentId: initialShipment.id,
        body: {
          carrier: "UPS",
          tracking_number: trackingNumber,
          shipping_method: "ground",
          shipping_cost: 15.99,
