import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipment";

/**
 * Comprehensive validation test for shipment deletion operations in the
 * shopping mall platform.
 *
 * This test validates the complete shipment deletion workflow including
 * multi-actor authentication, order creation, shipment creation, and various
 * deletion validation scenarios. The test ensures that deletion operations
 * properly validate order-shipment relationships, authorization boundaries, and
 * error handling for invalid deletion attempts.
 *
 * Key validation scenarios:
 *
 * 1. Successful deletion of valid shipments with proper authorization
 * 2. Error handling for non-existent shipment IDs
 * 3. Authorization checks preventing unauthorized deletion attempts
 * 4. Order-shipment relationship validation before deletion
 * 5. Data integrity maintenance throughout the deletion process
 */
export async function test_api_shipment_deletion_validation(
  connection: api.IConnection,
) {
  // Step 1: Create customer account and authenticate
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customer123";

  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://shoppingmall.example.com/register",
      referrer: "https://shoppingmall.example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create administrator account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123";

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ shipment_management: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 3: Customer creates an order
  const order = await api.functional.shoppingMall.customer.orders.create(
    connection,
    {
      body: {
        currency: "USD",
        shipping_address: `${RandomGenerator.name(1)} ${RandomGenerator.name(1)}, ${RandomGenerator.paragraph({ sentences: 1 })}, ${RandomGenerator.name(1)}, CA 90210`,
        billing_address: `${RandomGenerator.name(1)} ${RandomGenerator.name(1)}, ${RandomGenerator.paragraph({ sentences: 1 })}, ${RandomGenerator.name(1)}, CA 90210`,
        items: ArrayUtil.repeat(
          2,
          () =>
            ({
              shopping_mall_product_variant_id: typia.random<
                string & tags.Format<"uuid">
              >(),
              quantity: typia.random<
                number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
              >(),
            }) satisfies IShoppingMallOrderItem.ICreate,
        ),
      } satisfies IShoppingMallOrder.ICreate,
    },
  );
  typia.assert(order);

  // Step 4: Administrator creates a shipment for the order
  const shipment =
    await api.functional.shoppingMall.admin.orders.shipments.create(
      connection,
      {
        orderId: order.id,
        body: {
          carrier: RandomGenerator.pick(["UPS", "FedEx", "USPS"] as const),
          tracking_number: RandomGenerator.alphaNumeric(12),
          shipping_method: "standard",
          shipping_cost: typia.random<
            number & tags.Minimum<5> & tags.Maximum<50>
          >(),
          status: "label_created",
        } satisfies IShoppingMallShipment.ICreate,
      },
    );
  typia.assert(shipment);

  // Step 5: Validate successful shipment deletion with proper authorization
  await api.functional.shoppingMall.admin.orders.shipments.erase(connection, {
    orderId: order.id,
    shipmentId: shipment.id,
  });

  TestValidator.predicate(
    "first shipment should be successfully deleted",
    true,
  );

  // Step 6: Test error handling for non-existent shipment
  await TestValidator.error(
    "deleting non-existent shipment should fail",
    async () => {
      await api.functional.shoppingMall.admin.orders.shipments.erase(
        connection,
        {
          orderId: order.id,
          shipmentId: typia.random<string & tags.Format<"uuid">>(),
        },
      );
    },
  );

  // Step 7: Test authorization boundaries - customer cannot delete shipments
  // Switch back to customer authentication
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://shoppingmall.example.com/login",
      referrer: "https://shoppingmall.example.com",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Create another shipment for authorization testing
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://shoppingmall.example.com/admin/login",
      referrer: "https://shoppingmall.example.com/admin",
    } satisfies IShoppingMallAdministrator.ILogin,
  });

  const secondShipment =
    await api.functional.shoppingMall.admin.orders.shipments.create(
      connection,
      {
        orderId: order.id,
        body: {
          carrier: RandomGenerator.pick(["UPS", "FedEx", "USPS"] as const),
          tracking_number: RandomGenerator.alphaNumeric(12),
          shipping_method: "express",
          shipping_cost: typia.random<
            number & tags.Minimum<15> & tags.Maximum<100>
          >(),
          status: "label_created",
        } satisfies IShoppingMallShipment.ICreate,
      },
    );
  typia.assert(secondShipment);

  // Switch to customer and attempt unauthorized deletion
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "https://shoppingmall.example.com/login",
      referrer: "https://shoppingmall.example.com",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  await TestValidator.error(
    "customer cannot delete shipments without admin privileges",
    async () => {
      await api.functional.shoppingMall.admin.orders.shipments.erase(
        connection,
        {
          orderId: order.id,
          shipmentId: secondShipment.id,
        },
      );
    },
  );

  // Step 8: Clean up - admin deletes the remaining shipment
  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      href: "https://shoppingmall.example.com/admin/login",
      referrer: "https://shoppingmall.example.com/admin",
    } satisfies IShoppingMallAdministrator.ILogin,
  });

  await api.functional.shoppingMall.admin.orders.shipments.erase(connection, {
    orderId: order.id,
    shipmentId: secondShipment.id,
  });

  TestValidator.predicate(
    "second shipment should be successfully deleted",
    true,
  );

  // Final validation: Test deletion with mismatched order-shipment relationship
  await TestValidator.error(
    "deleting shipment with wrong order ID should fail",
    async () => {
      await api.functional.shoppingMall.admin.orders.shipments.erase(
        connection,
        {
          orderId: typia.random<string & tags.Format<"uuid">>(),
          shipmentId: secondShipment.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";

/**
 * Test the complete coupon lifecycle from creation to deletion by an
 * administrator. Validates that coupons can be properly deleted using soft
 * deletion mechanism while preserving historical data. The scenario covers
 * authentication setup, coupon creation with valid parameters, and subsequent
 * deletion with proper authorization checks.
 */
export async function test_api_coupon_deletion_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      role: "super_admin",
      permissions: JSON.stringify({ can_manage_coupons: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Step 2: Create a coupon to be deleted
  const couponCode = RandomGenerator.alphaNumeric(8).toUpperCase();
  const currentDate = new Date();
  const validFrom = new Date(currentDate.getTime() - 86400000).toISOString(); // Yesterday
  const validUntil = new Date(
    currentDate.getTime() + 86400000 * 30,
  ).toISOString(); // 30 days from now

  const coupon = await api.functional.shoppingMall.admin.coupons.create(
    connection,
    {
      body: {
        code: couponCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        discount_type: "percentage",
        discount_value: 15,
        minimum_order_amount: 50,
        maximum_discount: 100,
        usage_limit_per_customer: 5,
        total_usage_limit: 100,
        valid_from: validFrom,
        valid_until: validUntil,
        is_active: true,
        shopping_mall_channel_id: undefined,
      } satisfies IShoppingMallCoupon.ICreate,
    },
  );
  typia.assert(coupon);

  // Validate coupon creation
  TestValidator.equals(
    "created coupon code matches input",
    coupon.code,
    couponCode,
  );
  TestValidator.predicate("coupon should be active", coupon.is_active === true);

  // Step 3: Delete the coupon using soft deletion
  await api.functional.shoppingMall.admin.coupons.erase(connection, {
    couponCode: coupon.code,
  });

  // Step 4: Validate system continues to function post-deletion
  const newCouponCode = RandomGenerator.alphaNumeric(8).toUpperCase();
  const newCoupon = await api.functional.shoppingMall.admin.coupons.create(
    connection,
    {
      body: {
        code: newCouponCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        discount_type: "fixed_amount",
        discount_value: 25,
        minimum_order_amount: 75,
        maximum_discount: undefined,
        usage_limit_per_customer: 3,
        total_usage_limit: 50,
        valid_from: validFrom,
        valid_until: validUntil,
        is_active: true,
        shopping_mall_channel_id: undefined,
      } satisfies IShoppingMallCoupon.ICreate,
    },
  );
  typia.assert(newCoupon);

  // Final validation: Ensure system functionality is maintained
  TestValidator.equals(
    "new coupon code matches input",
    newCoupon.code,
    newCouponCode,
  );
  TestValidator.predicate(
    "new coupon should be active",
    newCoupon.is_active === true,
  );
  TestValidator.notEquals(
    "new coupon should have different code",
    newCoupon.code,
    coupon.code,
  );

  // Validate authorization context is maintained
  TestValidator.predicate(
    "administrator authentication should be maintained",
    adminAuth.administrator.role === "super_admin",
  );
}

