/**
 * Comprehensive E2E test for shopping mall promotion creation workflow.
 *
 * This test validates that administrators can create various types of marketing
 * promotions with proper scheduling, targeting, and discount structures. The
 * workflow includes administrator authentication, channel creation for targeted
 * promotions, and multiple promotion type validations.
 */
export async function test_api_admin_promotion_creation(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "AdminPassword123!",
        first_name: RandomGenerator.paragraph({ sentences: 2 }),
        last_name: RandomGenerator.paragraph({ sentences: 2 }),
        role: "super_admin",
        permissions: JSON.stringify({
          promotions: ["create", "read", "update", "delete"],
          channels: ["create", "read"],
        }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create a channel for targeted promotions
  const channel: IShoppingMallChannel =
    await api.functional.shoppingMall.admin.channels.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        status: "active",
        configuration: "targetAudience=premium_customers;discountLimit=20",
      } satisfies IShoppingMallChannel.ICreate,
    });
  typia.assert(channel);

  // Step 3: Create sale promotion
  const salePromotion: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: `Sale_Promotion_${RandomGenerator.alphaNumeric(6)}`,
        description: "Special sale promotion for loyal customers",
        promotion_type: "sale",
        start_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
        end_date: new Date(Date.now() + 604800000).toISOString(), // 7 days from now
        is_active: true,
        priority: 50,
        channel_id: channel.id,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(salePromotion);
  TestValidator.equals(
    "sale promotion name contains expected prefix",
    salePromotion.name.includes("Sale_Promotion"),
    true,
  );

  // Step 4: Create clearance promotion
  const clearancePromotion: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: `Clearance_Promotion_${RandomGenerator.alphaNumeric(6)}`,
        description: "Clearance promotion for inventory reduction",
        promotion_type: "clearance",
        start_date: new Date(Date.now() + 172800000).toISOString(), // 2 days from now
        end_date: new Date(Date.now() + 2592000000).toISOString(), // 30 days from now
        is_active: false, // Inactive initially
        priority: 75,
        channel_id: channel.id,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(clearancePromotion);
  TestValidator.equals(
    "clearance promotion name contains expected prefix",
    clearancePromotion.name.includes("Clearance_Promotion"),
    true,
  );

  // Step 5: Create seasonal promotion
  const seasonalPromotion: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: `Seasonal_Promotion_${RandomGenerator.alphaNumeric(6)}`,
        description: "Seasonal promotion for holiday shopping",
        promotion_type: "seasonal",
        start_date: new Date().toISOString(), // Starts immediately
        end_date: new Date(Date.now() + 2592000000).toISOString(), // 30 days from now
        is_active: true,
        priority: 25,
        channel_id: channel.id,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(seasonalPromotion);
  TestValidator.equals(
    "seasonal promotion name contains expected prefix",
    seasonalPromotion.name.includes("Seasonal_Promotion"),
    true,
  );

  // Step 6: Validate promotion scheduling constraints
  TestValidator.predicate(
    "sale promotion start date before end date",
    new Date(salePromotion.start_date) < new Date(salePromotion.end_date),
  );
  TestValidator.predicate(
    "clearance promotion start date before end date",
    new Date(clearancePromotion.start_date) <
      new Date(clearancePromotion.end_date),
  );
  TestValidator.predicate(
    "seasonal promotion start date before end date",
    new Date(seasonalPromotion.start_date) <
      new Date(seasonalPromotion.end_date),
  );

  // Step 7: Validate creator identity tracking
  TestValidator.equals(
    "seasonal promotion creator ID matches authenticated admin",
    seasonalPromotion.creator.id,
    admin.administrator.id,
  );
  TestValidator.equals(
    "seasonal promotion creator email matches authenticated admin",
    seasonalPromotion.creator.email,
    admin.administrator.email,
  );

  // Step 8: Validate channel association
  TestValidator.equals(
    "sale promotion channel association correct",
    salePromotion.channel?.id,
    channel.id,
  );
  TestValidator.equals(
    "clearance promotion channel association correct",
    clearancePromotion.channel?.id,
    channel.id,
  );
  TestValidator.equals(
    "seasonal promotion channel association correct",
    seasonalPromotion.channel?.id,
    channel.id,
  );

  // Step 9: Validate promotion uniqueness
  TestValidator.notEquals(
    "sale and clearance promotion names are unique",
    salePromotion.name,
    clearancePromotion.name,
  );
  TestValidator.notEquals(
    "sale and seasonal promotion names are unique",
    salePromotion.name,
    seasonalPromotion.name,
  );
  TestValidator.notEquals(
    "clearance and seasonal promotion names are unique",
    clearancePromotion.name,
    seasonalPromotion.name,
  );

  // Step 10: Validate promotion properties
  TestValidator.equals(
    "sale promotion is active",
    salePromotion.is_active,
    true,
  );
  TestValidator.equals(
    "clearance promotion is inactive",
    clearancePromotion.is_active,
    false,
  );
  TestValidator.equals(
    "seasonal promotion is active",
    seasonalPromotion.is_active,
    true,
  );
  TestValidator.predicate(
    "sale promotion priority is valid",
    salePromotion.priority >= 1 && salePromotion.priority <= 100,
  );
  TestValidator.predicate(
    "clearance promotion priority is valid",
    clearancePromotion.priority >= 1 && clearancePromotion.priority <= 100,
  );
  TestValidator.predicate(
    "seasonal promotion priority is valid",
    seasonalPromotion.priority >= 1 && seasonalPromotion.priority <= 100,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallPromotion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPromotion";

/**
 * Comprehensive promotion update workflow validation for shopping mall
 * administrators.
 *
 * This test validates the complete promotion update functionality including
 * field modifications, scheduling changes, status updates, and priority
 * adjustments. It follows a realistic business workflow: administrator
 * registration → authentication → promotion creation → various update scenarios
 * → validation of updated data.
 *
 * The test covers both partial updates (single field changes) and complete
 * updates (multiple field modifications) to ensure the update operation handles
 * all field combinations correctly. Each update is validated by retrieving the
 * promotion and comparing against expected changes.
 */
export async function test_api_promotion_update_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "Admin123!",
        first_name: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        last_name: RandomGenerator.paragraph({
          sentences: 1,
          wordMin: 3,
          wordMax: 7,
        }),
        role: "support_admin",
        permissions: JSON.stringify({ read: true, write: true, delete: false }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create initial promotion
  const initialPromotion: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: RandomGenerator.paragraph({
          sentences: 2,
          wordMin: 3,
          wordMax: 8,
        }),
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 3,
          sentenceMax: 6,
        }),
        promotion_type: "sale",
        start_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
        end_date: new Date(Date.now() + 172800000).toISOString(), // Day after tomorrow
        is_active: true,
        priority: 50,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(initialPromotion);

  // Step 3: Test partial update - single field modification
  const updatedName = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 3,
    wordMax: 8,
  });
  const partialUpdate: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: initialPromotion.name,
      body: {
        name: updatedName,
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(partialUpdate);
  TestValidator.equals(
    "name should be updated",
    partialUpdate.name,
    updatedName,
  );
  TestValidator.equals(
    "description should remain unchanged",
    partialUpdate.description,
    initialPromotion.description,
  );

  // Step 4: Test complete update - multiple field modifications
  const completeUpdateData = {
    name: RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 4,
      sentenceMax: 8,
    }),
    promotion_type: "clearance",
    start_date: new Date(Date.now() + 259200000).toISOString(), // 3 days from now
    end_date: new Date(Date.now() + 345600000).toISOString(), // 4 days from now
    is_active: false,
    priority: 75,
  } satisfies IShoppingMallPromotion.IUpdate;

  const completeUpdate: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: updatedName,
      body: completeUpdateData,
    });
  typia.assert(completeUpdate);

  // Validate complete update results
  TestValidator.equals(
    "name should match complete update",
    completeUpdate.name,
    completeUpdateData.name,
  );
  TestValidator.equals(
    "description should match complete update",
    completeUpdate.description,
    completeUpdateData.description,
  );
  TestValidator.equals(
    "promotion type should match complete update",
    completeUpdate.promotion_type,
    completeUpdateData.promotion_type,
  );
  TestValidator.equals(
    "start date should match complete update",
    completeUpdate.start_date,
    completeUpdateData.start_date,
  );
  TestValidator.equals(
    "end date should match complete update",
    completeUpdate.end_date,
    completeUpdateData.end_date,
  );
  TestValidator.equals(
    "active status should match complete update",
    completeUpdate.is_active,
    completeUpdateData.is_active,
  );
  TestValidator.equals(
    "priority should match complete update",
    completeUpdate.priority,
    completeUpdateData.priority,
  );

  // Step 5: Test scheduling validation - ensure start date is before end date
  const schedulingUpdate: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: completeUpdate.name,
      body: {
        start_date: new Date(Date.now() + 86400000).toISOString(),
        end_date: new Date(Date.now() + 172800000).toISOString(),
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(schedulingUpdate);

  // Safe date comparison using string comparison
  const startDate = typia.assert(schedulingUpdate.start_date!);
  const endDate = typia.assert(schedulingUpdate.end_date!);
  TestValidator.predicate(
    "start date should be before end date",
    startDate < endDate,
  );

  // Step 6: Test status toggle
  const statusToggle: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: schedulingUpdate.name,
      body: {
        is_active: true,
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(statusToggle);
  TestValidator.equals(
    "active status should be toggled to true",
    statusToggle.is_active,
    true,
  );

  // Step 7: Test priority adjustment
  const priorityUpdate: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: statusToggle.name,
      body: {
        priority: 25,
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(priorityUpdate);
  TestValidator.equals(
    "priority should be updated",
    priorityUpdate.priority,
    25,
  );

  // Final comprehensive validation of all updates
  TestValidator.equals(
    "final name should match last update",
    priorityUpdate.name,
    completeUpdateData.name,
  );
  TestValidator.equals(
    "final description should match",
    priorityUpdate.description,
    completeUpdateData.description,
  );
  TestValidator.equals(
    "final promotion type should match",
    priorityUpdate.promotion_type,
    completeUpdateData.promotion_type,
  );
  TestValidator.equals(
    "final active status should be true",
    priorityUpdate.is_active,
    true,
  );
  TestValidator.equals(
    "final priority should be 25",
    priorityUpdate.priority,
    25,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallPromotion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPromotion";

/**
 * Validate promotion update scheduling constraints and business rules.
 *
 * This test creates an initial promotion with valid scheduling, then attempts
 * various invalid updates to verify the system properly enforces scheduling
 * constraints including date ordering, past date prevention, and conflict
 * detection. The test ensures business logic validation works correctly without
 * testing type errors.
 */
export async function test_api_promotion_update_scheduling_validation(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      role: "support_admin",
      permissions: JSON.stringify({ can_manage_promotions: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Step 2: Create initial promotion with valid scheduling
  const now = new Date();
  const startDate = new Date(now.getTime() + 86400000).toISOString(); // Tomorrow
  const endDate = new Date(now.getTime() + 259200000).toISOString(); // 3 days later

  const initialPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: `TestPromotion_${RandomGenerator.alphaNumeric(8)}`,
        description: "Initial test promotion for scheduling validation",
        promotion_type: "sale",
        start_date: startDate,
        end_date: endDate,
        is_active: true,
        priority: 50,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(initialPromotion);

  // Step 3: Test invalid scheduling updates

  // Test 3.1: End date before start date
  await TestValidator.error(
    "should reject end date before start date",
    async () => {
      await api.functional.shoppingMall.admin.promotions.update(connection, {
        promotionName: initialPromotion.name,
        body: {
          start_date: new Date(now.getTime() + 172800000).toISOString(), // 2 days later
          end_date: new Date(now.getTime() + 86400000).toISOString(), // 1 day later (before start)
        } satisfies IShoppingMallPromotion.IUpdate,
      });
    },
  );

  // Test 3.2: Update to past start date
  await TestValidator.error("should reject past start date", async () => {
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: initialPromotion.name,
      body: {
        start_date: new Date(now.getTime() - 86400000).toISOString(), // Yesterday
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  });

  // Test 3.3: Update to past end date
  await TestValidator.error("should reject past end date", async () => {
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: initialPromotion.name,
      body: {
        end_date: new Date(now.getTime() - 86400000).toISOString(), // Yesterday
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  });

  // Test 3.4: Same start and end date (edge case)
  await TestValidator.error(
    "should reject same start and end date",
    async () => {
      const sameDate = new Date(now.getTime() + 86400000).toISOString();
      await api.functional.shoppingMall.admin.promotions.update(connection, {
        promotionName: initialPromotion.name,
        body: {
          start_date: sameDate,
          end_date: sameDate,
        } satisfies IShoppingMallPromotion.IUpdate,
      });
    },
  );

  // Test 3.5: Very short promotion period (1 hour instead of 1 minute for realism)
  await TestValidator.error(
    "should reject very short promotion period",
    async () => {
      const shortStart = new Date(now.getTime() + 3600000).toISOString(); // 1 hour later
      const shortEnd = new Date(now.getTime() + 7200000).toISOString(); // 2 hours later
      await api.functional.shoppingMall.admin.promotions.update(connection, {
        promotionName: initialPromotion.name,
        body: {
          start_date: shortStart,
          end_date: shortEnd,
        } satisfies IShoppingMallPromotion.IUpdate,
      });
    },
  );

  // Test 3.6: Promotion name uniqueness constraint
  const secondPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: `SecondPromotion_${RandomGenerator.alphaNumeric(8)}`,
        description: "Second test promotion",
        promotion_type: "loyalty",
        start_date: new Date(now.getTime() + 345600000).toISOString(), // 4 days later
        end_date: new Date(now.getTime() + 518400000).toISOString(), // 6 days later
        is_active: true,
        priority: 30,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(secondPromotion);

  await TestValidator.error(
    "should reject duplicate promotion name",
    async () => {
      await api.functional.shoppingMall.admin.promotions.update(connection, {
        promotionName: secondPromotion.name,
        body: {
          name: initialPromotion.name, // Try to use first promotion's name
        } satisfies IShoppingMallPromotion.IUpdate,
      });
    },
  );

  // Step 4: Test valid scheduling updates

  // Test 4.1: Valid date extension
  const extendedPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: initialPromotion.name,
      body: {
        end_date: new Date(now.getTime() + 604800000).toISOString(), // Extend to 7 days later
        description: "Extended promotion with valid scheduling",
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(extendedPromotion);
  TestValidator.equals(
    "end date should be updated",
    extendedPromotion.end_date,
    new Date(now.getTime() + 604800000).toISOString(),
  );

  // Test 4.2: Valid priority update
  const priorityUpdatedPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: initialPromotion.name,
      body: {
        priority: 75,
        is_active: false,
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(priorityUpdatedPromotion);
  TestValidator.equals(
    "priority should be updated",
    priorityUpdatedPromotion.priority,
    75,
  );
  TestValidator.predicate(
    "promotion should be inactive",
    priorityUpdatedPromotion.is_active === false,
  );

  // Step 5: Verify promotion remains accessible after updates
  const finalPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: `FinalPromotion_${RandomGenerator.alphaNumeric(8)}`,
        description: "Final test promotion",
        promotion_type: "seasonal",
        start_date: new Date(now.getTime() + 172800000).toISOString(), // 2 days later
        end_date: new Date(now.getTime() + 259200000).toISOString(), // 3 days later
        is_active: true,
        priority: 25,
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(finalPromotion);

  // Verify all promotions have unique names
  TestValidator.notEquals(
    "promotion names should be unique",
    initialPromotion.name,
    finalPromotion.name,
  );
  TestValidator.notEquals(
    "second promotion name should be unique",
    secondPromotion.name,
    finalPromotion.name,
  );
  TestValidator.notEquals(
    "first and second promotion names should be unique",
    initialPromotion.name,
    secondPromotion.name,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallPromotion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPromotion";

/**
 * Test promotion name uniqueness validation during updates.
 *
 * This E2E test validates that the shopping mall platform properly enforces
 * promotion name uniqueness when updating existing promotions. It creates
 * multiple promotions with different names, then attempts to update one
 * promotion's name to match an existing promotion name to verify the system
 * prevents duplicate names.
 */
export async function test_api_promotion_update_name_uniqueness(
  connection: api.IConnection,
) {
  // Create first administrator account
  const admin1Email = typia.random<string & tags.Format<"email">>();
  const admin1: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: admin1Email,
        password: "admin123",
        first_name: RandomGenerator.name(),
        last_name: RandomGenerator.name(),
        role: "super_admin",
        permissions: JSON.stringify({ can_manage_promotions: true }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin1);

  // Create first promotion with unique name
  const promotion1Name = RandomGenerator.paragraph({ sentences: 3 });
  const promotion1: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: promotion1Name,
        description: RandomGenerator.content({ paragraphs: 2 }),
        promotion_type: "sale",
        start_date: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
        end_date: new Date(Date.now() + 172800000).toISOString(), // Day after tomorrow
        is_active: true,
        priority: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
        >(),
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(promotion1);

  // Create second promotion with different unique name
  const promotion2Name = RandomGenerator.paragraph({ sentences: 3 });
  const promotion2: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: promotion2Name,
        description: RandomGenerator.content({ paragraphs: 2 }),
        promotion_type: "clearance",
        start_date: new Date(Date.now() + 86400000).toISOString(),
        end_date: new Date(Date.now() + 172800000).toISOString(),
        is_active: true,
        priority: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
        >(),
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(promotion2);

  // Verify promotions have different names
  TestValidator.notEquals(
    "promotion names should be different",
    promotion1.name,
    promotion2.name,
  );

  // Attempt to update promotion2 with promotion1's name (should fail due to uniqueness constraint)
  await TestValidator.error(
    "should reject duplicate promotion name during update",
    async () => {
      await api.functional.shoppingMall.admin.promotions.update(connection, {
        promotionName: promotion2.name,
        body: {
          name: promotion1Name, // Attempt to use existing name - should fail
        } satisfies IShoppingMallPromotion.IUpdate,
      });
    },
  );

  // Successful update with unique name
  const uniqueNewName = RandomGenerator.paragraph({ sentences: 3 });
  const updatedPromotion2: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: promotion2.name,
      body: {
        name: uniqueNewName,
        description: "Successfully updated with unique name",
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(updatedPromotion2);
  TestValidator.equals(
    "promotion should be updated with unique name",
    updatedPromotion2.name,
    uniqueNewName,
  );

  // Verify the original promotion1 remains unchanged and accessible
  const promotion1Update: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.update(connection, {
      promotionName: promotion1.name,
      body: {
        description: "Updated description for promotion1",
      } satisfies IShoppingMallPromotion.IUpdate,
    });
  typia.assert(promotion1Update);
  TestValidator.equals(
    "promotion1 name should remain unchanged",
    promotion1Update.name,
    promotion1.name,
  );

  // Final validation that both promotions exist with their correct names
  TestValidator.equals(
    "promotion1 should maintain original name",
    promotion1Update.name,
    promotion1Name,
  );
  TestValidator.equals(
    "promotion2 should have updated unique name",
    updatedPromotion2.name,
    uniqueNewName,
  );
  TestValidator.notEquals(
    "promotions should have different names",
    promotion1Update.name,
    updatedPromotion2.name,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallPromotion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPromotion";

/**
 * Test complete promotion deletion workflow including prerequisite creation and
 * validation. Creates a new promotion as an admin, then deletes it using the
 * promotion name identifier. Verifies that the deletion operation succeeds and
 * returns appropriate status. Tests deletion of promotions in different states
 * including active promotions, inactive promotions, and promotions with future
 * scheduling. Validates that deletion operations complete successfully without
 * errors, demonstrating proper promotion lifecycle management.
 */
export async function test_api_promotion_deletion_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for authentication context
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";
  const adminRoles = [
    "super_admin",
    "support_admin",
    "security_admin",
  ] as const;

  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role: RandomGenerator.pick(adminRoles),
        permissions: JSON.stringify({ can_manage_promotions: true }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create active promotion to be deleted
  const promotionName = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 8,
  });
  const startDate = RandomGenerator.date(new Date(), 86400000).toISOString(); // Within 1 day
  const endDate = RandomGenerator.date(
    new Date(startDate),
    86400000,
  ).toISOString(); // After start date

  const promotion: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: promotionName,
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 5,
          sentenceMax: 10,
        }),
        promotion_type: "sale",
        start_date: startDate,
        end_date: endDate,
        is_active: true,
        priority: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
        >(),
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(promotion);

  // Verify promotion was created correctly
  TestValidator.equals(
    "promotion name matches input",
    promotion.name,
    promotionName,
  );
  TestValidator.equals("promotion is active", promotion.is_active, true);
  TestValidator.predicate(
    "promotion has valid priority range",
    promotion.priority >= 1 && promotion.priority <= 100,
  );

  // Step 3: Delete the active promotion using its unique name identifier
  await api.functional.shoppingMall.admin.promotions.erase(connection, {
    promotionName: promotion.name,
  });

  // Step 4: Create and delete inactive promotion
  const inactivePromotionName = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 3,
    wordMax: 8,
  });
  const inactiveStartDate = RandomGenerator.date(
    new Date(),
    259200000,
  ).toISOString(); // Within 3 days
  const inactiveEndDate = RandomGenerator.date(
    new Date(inactiveStartDate),
    86400000,
  ).toISOString();

  const inactivePromotion: IShoppingMallPromotion =
    await api.functional.shoppingMall.admin.promotions.create(connection, {
      body: {
        name: inactivePromotionName,
        description: RandomGenerator.content({
          paragraphs: 1,
          sentenceMin: 3,
          sentenceMax: 6,
        }),
        promotion_type: "clearance",
        start_date: inactiveStartDate,
        end_date: inactiveEndDate,
        is_active: false,
        priority: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<100>
        >(),
      } satisfies IShoppingMallPromotion.ICreate,
    });
  typia.assert(inactivePromotion);

  // Delete inactive promotion
  await api.functional.shoppingMall.admin.promotions.erase(connection, {
    promotionName: inactivePromotion.name,
  });

  // Step 5: Create and delete future-scheduled promotion
  const futurePromotionName = RandomGenerator.paragraph({
    sentences: 3,
