        maximum_discount: typia.random<
          number &
            tags.Type<"uint32"> &
            tags.Minimum<5000> &
            tags.Maximum<20000>
        >(),
        usage_limit_per_customer: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
        total_usage_limit: typia.random<
