import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";

/**
 * Test retrieval of inactive coupon to verify status-based access control.
 * Admin creates inactive coupon, then attempts to retrieve it by code.
 * Validates that inactive coupons can still be retrieved for administrative
 * purposes but proper status indication is maintained.
 */
export async function test_api_coupon_retrieval_inactive_coupon(
  connection: api.IConnection,
) {
  // 1. Authenticate as administrator
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "adminPassword123",
        first_name: RandomGenerator.paragraph({ sentences: 2 }),
        last_name: RandomGenerator.paragraph({ sentences: 1 }),
        role: "support_admin",
        permissions: JSON.stringify({ can_manage_coupons: true }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // 2. Create a channel for coupon creation context
  const channel: IShoppingMallChannel =
    await api.functional.shoppingMall.admin.channels.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8).toUpperCase(),
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
        configuration: JSON.stringify({ allow_coupons: true }),
      } satisfies IShoppingMallChannel.ICreate,
    });
  typia.assert(channel);

  // 3. Create an inactive coupon
  const couponCode: string = RandomGenerator.alphaNumeric(10).toUpperCase();
  const coupon: IShoppingMallCoupon =
    await api.functional.shoppingMall.admin.coupons.create(connection, {
      body: {
        code: couponCode,
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        discount_type: "percentage",
        discount_value: 15,
        minimum_order_amount: 50,
        maximum_discount: 25,
        usage_limit_per_customer: 1,
        total_usage_limit: 100,
        valid_from: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
        valid_until: new Date(Date.now() + 2592000000).toISOString(), // 30 days from now
        is_active: false, // Inactive coupon
        shopping_mall_channel_id: channel.id,
      } satisfies IShoppingMallCoupon.ICreate,
    });
  typia.assert(coupon);

  // 4. Retrieve the inactive coupon by code
  const retrievedCoupon: IShoppingMallCoupon =
    await api.functional.shoppingMall.coupons.at(connection, {
      couponCode: coupon.code,
    });
  typia.assert(retrievedCoupon);

  // 5. Validate that the coupon maintains its inactive status
  TestValidator.equals(
    "inactive coupon status is preserved",
    retrievedCoupon.is_active,
    false,
  );

  // 6. Validate coupon data integrity
  TestValidator.equals(
    "retrieved coupon code matches created coupon",
    retrievedCoupon.code,
    coupon.code,
  );
  TestValidator.equals(
    "retrieved coupon name matches created coupon",
    retrievedCoupon.name,
    coupon.name,
  );
  TestValidator.equals(
    "retrieved coupon discount type matches created coupon",
    retrievedCoupon.discount_type,
    coupon.discount_type,
  );
  TestValidator.equals(
    "retrieved coupon discount value matches created coupon",
    retrievedCoupon.discount_value,
    coupon.discount_value,
  );
  TestValidator.equals(
    "retrieved coupon minimum order amount matches created coupon",
    retrievedCoupon.minimum_order_amount,
    coupon.minimum_order_amount,
  );
  TestValidator.equals(
    "retrieved coupon maximum discount matches created coupon",
    retrievedCoupon.maximum_discount,
    coupon.maximum_discount,
  );
  TestValidator.equals(
    "retrieved coupon usage limit per customer matches created coupon",
    retrievedCoupon.usage_limit_per_customer,
    coupon.usage_limit_per_customer,
  );
  TestValidator.equals(
    "retrieved coupon total usage limit matches created coupon",
    retrievedCoupon.total_usage_limit,
    coupon.total_usage_limit,
  );

  // 7. Validate that used_count is initialized to 0
  TestValidator.equals(
    "new coupon has zero usage count",
    retrievedCoupon.used_count,
    0,
  );

  // 8. Validate timestamps are properly set
  TestValidator.predicate(
    "coupon has valid creation timestamp",
    retrievedCoupon.created_at !== null &&
      retrievedCoupon.created_at !== undefined,
  );
  TestValidator.predicate(
    "coupon has valid update timestamp",
    retrievedCoupon.updated_at !== null &&
      retrievedCoupon.updated_at !== undefined,
  );

  // 9. Validate channel relationship
  TestValidator.equals(
    "coupon channel ID matches created channel",
    retrievedCoupon.shopping_mall_channel_id,
    channel.id,
  );

  // 10. Validate creator relationship
  TestValidator.equals(
    "coupon creator ID matches admin ID",
    retrievedCoupon.shopping_mall_administrator_id,
    admin.administrator.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";

/**
 * Test retrieval of expired coupon to verify date validation functionality.
 *
 * This test validates that expired coupons can be retrieved for reporting
 * purposes while maintaining proper expiration status indication. The workflow
 * involves:
 *
 * 1. Creating and authenticating an administrator account
 * 2. Creating a shopping mall channel for coupon association
 * 3. Creating an expired coupon with past expiration date
 * 4. Retrieving the expired coupon by code to verify accessibility
 * 5. Validating that the coupon properties are preserved including expiration
 *    status
 */
export async function test_api_coupon_retrieval_expired_coupon(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate administrator account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ can_manage_coupons: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Step 2: Create shopping mall channel for coupon association
  const channel = await api.functional.shoppingMall.admin.channels.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8).toUpperCase(),
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
        configuration: JSON.stringify({ allow_coupons: true }),
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(channel);

  // Step 3: Create expired coupon with past expiration date
  const couponCode = RandomGenerator.alphaNumeric(10).toUpperCase();
  const pastDate = new Date(Date.now() - 86400000).toISOString(); // 1 day ago
  const olderPastDate = new Date(Date.now() - 172800000).toISOString(); // 2 days ago

  const expiredCoupon = await api.functional.shoppingMall.admin.coupons.create(
    connection,
    {
      body: {
        code: couponCode,
        name: "Expired Test Coupon - Date Validation Test",
        description:
          "This coupon has expired for testing date validation functionality",
        discount_type: "percentage",
        discount_value: 15,
        minimum_order_amount: 5000,
        maximum_discount: 10000,
        usage_limit_per_customer: 1,
        total_usage_limit: 100,
        valid_from: olderPastDate, // Set to older past date
        valid_until: pastDate, // Set to more recent past date
        is_active: true,
        shopping_mall_channel_id: channel.id,
      } satisfies IShoppingMallCoupon.ICreate,
    },
  );
  typia.assert(expiredCoupon);

  // Step 4: Retrieve the expired coupon by code
  const retrievedCoupon = await api.functional.shoppingMall.coupons.at(
    connection,
    {
      couponCode: couponCode,
    },
  );
  typia.assert(retrievedCoupon);

  // Step 5: Validate coupon properties including expiration status
  TestValidator.equals(
    "coupon ID matches",
    retrievedCoupon.id,
    expiredCoupon.id,
  );
  TestValidator.equals("coupon code matches", retrievedCoupon.code, couponCode);
  TestValidator.equals(
    "coupon name matches",
    retrievedCoupon.name,
    "Expired Test Coupon - Date Validation Test",
  );
  TestValidator.equals(
    "discount type matches",
    retrievedCoupon.discount_type,
    "percentage",
  );
  TestValidator.equals(
    "discount value matches",
    retrievedCoupon.discount_value,
    15,
  );
  TestValidator.equals(
    "minimum order amount matches",
    retrievedCoupon.minimum_order_amount,
    5000,
  );
  TestValidator.equals(
    "maximum discount matches",
    retrievedCoupon.maximum_discount,
    10000,
  );
  TestValidator.equals(
    "usage limit per customer matches",
    retrievedCoupon.usage_limit_per_customer,
    1,
  );
  TestValidator.equals(
    "total usage limit matches",
    retrievedCoupon.total_usage_limit,
    100,
  );
  TestValidator.equals(
    "channel ID matches",
    retrievedCoupon.shopping_mall_channel_id,
    channel.id,
  );
  TestValidator.predicate(
    "coupon is active",
    retrievedCoupon.is_active === true,
  );
  TestValidator.predicate(
    "coupon valid_from is in past",
    new Date(retrievedCoupon.valid_from) < new Date(),
  );
  TestValidator.predicate(
    "coupon valid_until is in past",
    new Date(retrievedCoupon.valid_until) < new Date(),
  );
  TestValidator.predicate(
    "coupon has expired",
    new Date(retrievedCoupon.valid_until) < new Date(),
  );
  TestValidator.predicate(
    "used count is zero",
    retrievedCoupon.used_count === 0,
  );

  // Validate that expired coupon can be retrieved (main test objective)
  TestValidator.equals(
    "expired coupon retrieval successful",
    retrievedCoupon.code,
    couponCode,
  );
  TestValidator.predicate(
    "expired coupon maintains all properties",
    retrievedCoupon.id === expiredCoupon.id &&
      retrievedCoupon.code === expiredCoupon.code &&
      retrievedCoupon.name === expiredCoupon.name,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates customer-initiated price correction for order items.
 *
 * This test simulates a real-world scenario where a customer discovers a
 * pricing error or promotional discount after placing an order and requests a
 * price correction. The test validates that the price correction API properly
 * updates the unit price and recalculates the total price while maintaining
 * historical accuracy of the original purchase.
 *
 * The test follows a comprehensive multi-actor workflow:
 *
 * 1. Administrator creates product category for classification
 * 2. Seller registers product and creates product variant
 * 3. Customer creates order and adds product variant as order item
 * 4. Customer requests price correction with updated pricing
 * 5. System validates price correction and recalculates totals
 *
 * Key validations include:
 *
 * - Price correction API successfully processes the request
 * - Unit price is updated to the corrected value
 * - Total price is recalculated based on quantity and new unit price
 * - Original order item data remains accessible for audit purposes
 * - Business rules for price corrections are properly enforced
 */
export async function test_api_order_item_price_correction_by_customer(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for category management
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "Admin123!",
        first_name: "Admin",
        last_name: "User",
        role: "super_admin",
        permissions: JSON.stringify({ all: true }),
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create product category
  const category: IShoppingMallCategory =
    await api.functional.shoppingMall.admin.categories.create(connection, {
      body: {
        name: "Electronics",
        description: "Electronic devices and accessories",
        display_order: 1,
        active: true,
      } satisfies IShoppingMallCategory.ICreate,
    });
  typia.assert(category);

  // Step 3: Create seller account for product management
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "Seller123!",
        business_name: "Tech Store Inc.",
        contact_person: "John Seller",
        phone_number: "+1-555-0123",
        business_address: "123 Tech Street, Tech City",
        href: "https://example.com/seller-registration",
        referrer: "https://example.com/",
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // Step 4: Create product with proper summary types
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        name: "Wireless Headphones",
        description: "High-quality wireless headphones with noise cancellation",
        sku: "WH-2024-001",
        price: 199.99,
        compare_price: 249.99,
        cost_price: 120.0,
        stock_quantity: 50,
        status: "active",
        condition: "new",
        weight: 0.3,
        dimensions: "20x15x8cm",
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ??
            ("00000000-0000-0000-0000-000000000000" satisfies string &
              tags.Format<"uuid"> as string & tags.Format<"uuid">),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: category.parent,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // Step 5: Create product variant
  const productVariant: IShoppingMallProductVariant =
    await api.functional.shoppingMall.seller.products.variants.create(
      connection,
      {
        productId: product.id,
        body: {
          shopping_mall_product_id: product.id,
          variant_name: "Wireless Headphones - Black",
          sku: "WH-2024-001-BLK",
          price: 199.99,
          stock_quantity: 25,
          attributes: JSON.stringify({
            color: "black",
            connectivity: "wireless",
          }),
          active: true,
        } satisfies IShoppingMallProductVariant.ICreate,
      },
    );
  typia.assert(productVariant);

  // Step 6: Create customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "Customer123!",
        first_name: "John",
        last_name: "Customer",
        phone_number: "+1-555-0456",
        href: "https://example.com/customer-registration",
        referrer: "https://example.com/",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // Step 7: Create order
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: {
        currency: "USD",
        shipping_address: "123 Customer Street, Customer City",
        billing_address: "123 Customer Street, Customer City",
        items: [], // Empty initially, will add items separately
      } satisfies IShoppingMallOrder.ICreate,
    });
  typia.assert(order);

  // Step 8: Add order item with original price
  const originalOrderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.customer.orders.items.create(connection, {
      orderId: order.id,
      body: {
        shopping_mall_product_variant_id: productVariant.id,
        quantity: 2,
      } satisfies IShoppingMallOrderItem.ICreate,
    });
  typia.assert(originalOrderItem);

  // Validate original pricing
  TestValidator.equals(
    "original unit price matches product variant price",
    originalOrderItem.unit_price,
    199.99,
  );
  TestValidator.equals(
    "original total price calculates correctly",
    originalOrderItem.total_price,
    199.99 * 2, // quantity * unit_price
  );

  // Step 9: Customer requests price correction (promotional discount)
  const correctedUnitPrice = 179.99; // $20 discount per unit
  const correctedOrderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.customer.orders.items.update(connection, {
      orderId: order.id,
      itemId: originalOrderItem.id,
      body: {
        unit_price: correctedUnitPrice,
        total_price: correctedUnitPrice * 2, // quantity remains 2
      } satisfies IShoppingMallOrderItem.IUpdate,
    });
  typia.assert(correctedOrderItem);

  // Step 10: Validate price correction results
  TestValidator.equals(
    "corrected unit price matches requested correction",
    correctedOrderItem.unit_price,
    correctedUnitPrice,
  );
  TestValidator.equals(
    "corrected total price recalculates correctly",
    correctedOrderItem.total_price,
    correctedUnitPrice * 2,
  );
  TestValidator.notEquals(
    "unit price changed after correction",
    correctedOrderItem.unit_price,
    originalOrderItem.unit_price,
  );
  TestValidator.notEquals(
    "total price changed after correction",
    correctedOrderItem.total_price,
    originalOrderItem.total_price,
  );

  // Step 11: Validate historical data preservation
  TestValidator.equals(
    "order item ID remains unchanged",
    correctedOrderItem.id,
    originalOrderItem.id,
  );
  TestValidator.equals(
    "product variant reference preserved",
    correctedOrderItem.shopping_mall_product_variant_id,
    originalOrderItem.shopping_mall_product_variant_id,
  );
  TestValidator.equals(
    "seller reference preserved",
    correctedOrderItem.shopping_mall_seller_id,
    originalOrderItem.shopping_mall_seller_id,
  );
  TestValidator.equals(
    "order reference preserved",
    correctedOrderItem.shopping_mall_order_id,
    originalOrderItem.shopping_mall_order_id,
  );
  TestValidator.equals(
    "quantity remains unchanged",
    correctedOrderItem.quantity,
    originalOrderItem.quantity,
  );
  TestValidator.equals(
    "product name preserved",
    correctedOrderItem.product_name,
    originalOrderItem.product_name,
  );

  // Step 12: Validate business logic
  TestValidator.predicate(
    "corrected price is lower than original price",
    correctedOrderItem.unit_price < originalOrderItem.unit_price,
  );
  TestValidator.predicate(
    "corrected total reflects quantity correctly",
    Math.abs(
      correctedOrderItem.total_price -
        correctedOrderItem.unit_price * correctedOrderItem.quantity,
    ) < 0.01,
  );

  // Additional validation: Ensure price correction is reasonable
  TestValidator.predicate(
    "price correction represents meaningful discount",
    originalOrderItem.unit_price - correctedOrderItem.unit_price > 0.01,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallCustomerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomerSession";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductVariant } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductVariant";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Test scenario where customer updates product information in an order item,
 * such as correcting product name or attributes after customer service
 * interaction. Validates that product information updates maintain historical
 * context while allowing corrections.
 */
export async function test_api_order_item_product_info_update_by_customer(
  connection: api.IConnection,
) {
  // Step 1: Create customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "customer123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://shoppingmall.example.com/register",
      referrer: "https://shoppingmall.example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create admin account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "admin123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ all: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 3: Create seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: "seller123",
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.paragraph({ sentences: 3 }),
      tax_id: "TAX-123456789",
      href: "https://shoppingmall.example.com/seller/register",
      referrer: "https://shoppingmall.example.com",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Switch to admin to create category
