import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";

/**
 * Test updating coupon usage limits including per-customer limits and overall
 * platform limits. Validates that usage limit changes are properly enforced and
 * that existing usage counts are respected. Tests that reducing usage limits
 * doesn't invalidate coupons that have already exceeded the new limits but
 * prevents new applications appropriately.
 */
export async function test_api_coupon_usage_limit_update(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ coupon_management: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Step 2: Create initial coupon with usage limits
  const couponCode = RandomGenerator.alphaNumeric(8).toUpperCase();
  const initialCoupon = await api.functional.shoppingMall.admin.coupons.create(
    connection,
    {
      body: {
        code: couponCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        discount_type: "percentage",
        discount_value: typia.random<
          number & tags.Type<"uint32"> & tags.Minimum<5> & tags.Maximum<50>
        >(),
        usage_limit_per_customer: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<10>
        >(),
        total_usage_limit: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<20> & tags.Maximum<50>
        >(),
        valid_from: new Date(Date.now() + 86400000).toISOString(), // Tomorrow
        valid_until: new Date(Date.now() + 86400000 * 30).toISOString(), // 30 days from now
        is_active: true,
      } satisfies IShoppingMallCoupon.ICreate,
    },
  );
  typia.assert(initialCoupon);

  // Step 3: Define updated usage limits
  const newPerCustomerLimit = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<3>
  >();
  const newTotalLimit = typia.random<
    number & tags.Type<"int32"> & tags.Minimum<5> & tags.Maximum<10>
  >();

  // Step 4: Update coupon with reduced usage limits
  const updatedCoupon = await api.functional.shoppingMall.admin.coupons.update(
    connection,
    {
      couponCode: couponCode,
      body: {
        usage_limit_per_customer: newPerCustomerLimit,
        total_usage_limit: newTotalLimit,
      } satisfies IShoppingMallCoupon.IUpdate,
    },
  );
  typia.assert(updatedCoupon);

  // Step 5: Validate that usage limits were updated correctly
  TestValidator.equals(
    "per-customer usage limit should be reduced",
    updatedCoupon.usage_limit_per_customer,
    newPerCustomerLimit,
  );

  TestValidator.equals(
    "total usage limit should be reduced",
    updatedCoupon.total_usage_limit,
    newTotalLimit,
  );

  // Step 6: Validate that limits were actually changed from original values
  TestValidator.notEquals(
    "per-customer limit should differ from original",
    updatedCoupon.usage_limit_per_customer,
    initialCoupon.usage_limit_per_customer,
  );

  TestValidator.notEquals(
    "total limit should differ from original",
    updatedCoupon.total_usage_limit,
    initialCoupon.total_usage_limit,
  );

  // Step 7: Validate that other coupon properties remain unchanged
  TestValidator.equals(
    "coupon code should remain the same",
    updatedCoupon.code,
    initialCoupon.code,
  );

  TestValidator.equals(
    "discount type should remain unchanged",
    updatedCoupon.discount_type,
    initialCoupon.discount_type,
  );

  TestValidator.equals(
    "discount value should remain unchanged",
    updatedCoupon.discount_value,
    initialCoupon.discount_value,
  );

  // Step 8: Validate that usage count remains intact
  TestValidator.equals(
    "used count should remain zero after update",
    updatedCoupon.used_count,
    0,
  );

  // Step 9: Validate that coupon remains active
  TestValidator.predicate(
    "coupon should remain active after update",
    updatedCoupon.is_active === true,
  );

  // Step 10: Test error condition - updating non-existent coupon
  await TestValidator.error(
    "updating non-existent coupon should fail",
    async () => {
      await api.functional.shoppingMall.admin.coupons.update(connection, {
        couponCode: "NONEXISTENT123",
        body: {
          usage_limit_per_customer: 5,
        } satisfies IShoppingMallCoupon.IUpdate,
      });
    },
  );

  // Step 11: Test error condition - invalid usage limits
  await TestValidator.error(
    "setting negative usage limit should fail",
    async () => {
      await api.functional.shoppingMall.admin.coupons.update(connection, {
        couponCode: couponCode,
        body: {
          usage_limit_per_customer: -1,
        } satisfies IShoppingMallCoupon.IUpdate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";

/**
 * Test updating coupon activation status to temporarily deactivate or
 * reactivate coupons. Validates that inactive coupons cannot be applied to
 * orders even if within validity period, and that reactivated coupons become
 * available for use again. Tests that status changes don't affect coupon usage
 * tracking or historical data.
 */
export async function test_api_coupon_activation_status_update(
  connection: api.IConnection,
) {
  // Step 1: Create and authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ all: true }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Step 2: Create a test coupon with active status
  const couponCode = RandomGenerator.alphaNumeric(8).toUpperCase();
  const futureDate = new Date(Date.now() + 86400000 * 30); // 30 days from now
  const pastDate = new Date(Date.now() - 86400000 * 7); // 7 days ago

  const createdCoupon = await api.functional.shoppingMall.admin.coupons.create(
    connection,
    {
      body: {
        code: couponCode,
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        discount_type: "percentage",
        discount_value: 15,
        minimum_order_amount: 5000,
        maximum_discount: 10000,
        usage_limit_per_customer: 1,
        total_usage_limit: 100,
        valid_from: pastDate.toISOString(),
        valid_until: futureDate.toISOString(),
        is_active: true,
        shopping_mall_channel_id: undefined,
      } satisfies IShoppingMallCoupon.ICreate,
    },
  );
  typia.assert(createdCoupon);
  TestValidator.equals(
    "coupon initially active",
    createdCoupon.is_active,
    true,
  );

  // Step 3: Test deactivation - update coupon status to inactive
  const deactivatedCoupon =
    await api.functional.shoppingMall.admin.coupons.update(connection, {
      couponCode: couponCode,
      body: {
        is_active: false,
      } satisfies IShoppingMallCoupon.IUpdate,
    });
  typia.assert(deactivatedCoupon);
  TestValidator.equals(
    "coupon deactivated",
    deactivatedCoupon.is_active,
    false,
  );
  TestValidator.equals(
    "coupon code unchanged",
    deactivatedCoupon.code,
    couponCode,
  );
  TestValidator.equals(
    "discount value unchanged",
    deactivatedCoupon.discount_value,
    15,
  );
  TestValidator.notEquals(
    "updated_at timestamp changed",
    deactivatedCoupon.updated_at,
    createdCoupon.updated_at,
  );

  // Step 4: Test reactivation - update coupon status back to active
  const reactivatedCoupon =
    await api.functional.shoppingMall.admin.coupons.update(connection, {
      couponCode: couponCode,
      body: {
        is_active: true,
      } satisfies IShoppingMallCoupon.IUpdate,
    });
  typia.assert(reactivatedCoupon);
  TestValidator.equals("coupon reactivated", reactivatedCoupon.is_active, true);
  TestValidator.equals(
    "coupon code remains",
    reactivatedCoupon.code,
    couponCode,
  );
  TestValidator.equals(
    "usage count unchanged",
    reactivatedCoupon.used_count,
    0,
  );
  TestValidator.notEquals(
    "updated_at timestamp updated again",
    reactivatedCoupon.updated_at,
    deactivatedCoupon.updated_at,
  );

  // Step 5: Test multiple status changes in sequence
  const finalDeactivation =
    await api.functional.shoppingMall.admin.coupons.update(connection, {
      couponCode: couponCode,
      body: {
        is_active: false,
      } satisfies IShoppingMallCoupon.IUpdate,
    });
  typia.assert(finalDeactivation);
  TestValidator.equals(
    "final deactivation successful",
    finalDeactivation.is_active,
    false,
  );

  // Step 6: Verify that other coupon properties remain unchanged through all updates
  TestValidator.equals(
    "name unchanged through updates",
    finalDeactivation.name,
    createdCoupon.name,
  );
  TestValidator.equals(
    "description unchanged",
    finalDeactivation.description,
    createdCoupon.description,
  );
  TestValidator.equals(
    "discount type unchanged",
    finalDeactivation.discount_type,
    createdCoupon.discount_type,
  );
  TestValidator.equals(
    "valid from unchanged",
    finalDeactivation.valid_from,
    createdCoupon.valid_from,
  );
  TestValidator.equals(
    "valid until unchanged",
    finalDeactivation.valid_until,
    createdCoupon.valid_until,
  );
  TestValidator.equals(
    "usage limits unchanged",
    finalDeactivation.usage_limit_per_customer,
    createdCoupon.usage_limit_per_customer,
  );
  TestValidator.equals(
    "total usage limit unchanged",
    finalDeactivation.total_usage_limit,
    createdCoupon.total_usage_limit,
  );

  // Step 7: Test that status changes don't affect creation timestamp
  TestValidator.equals(
    "created_at timestamp remains constant",
    finalDeactivation.created_at,
    createdCoupon.created_at,
  );

  // Step 8: Test sequential status changes to ensure proper state management
  const finalReactivation =
    await api.functional.shoppingMall.admin.coupons.update(connection, {
      couponCode: couponCode,
      body: {
        is_active: true,
      } satisfies IShoppingMallCoupon.IUpdate,
    });
  typia.assert(finalReactivation);
  TestValidator.equals(
    "final reactivation successful",
    finalReactivation.is_active,
    true,
  );

  // Verify all core properties remain intact after multiple status changes
  TestValidator.equals(
    "all properties intact after multiple updates",
    {
      code: finalReactivation.code,
      name: finalReactivation.name,
      discount_type: finalReactivation.discount_type,
      discount_value: finalReactivation.discount_value,
      valid_from: finalReactivation.valid_from,
      valid_until: finalReactivation.valid_until,
      used_count: finalReactivation.used_count,
    },
    {
      code: createdCoupon.code,
      name: createdCoupon.name,
      discount_type: createdCoupon.discount_type,
      discount_value: createdCoupon.discount_value,
      valid_from: createdCoupon.valid_from,
      valid_until: createdCoupon.valid_until,
      used_count: createdCoupon.used_count,
    },
  );

  console.log("Coupon activation status update test completed successfully");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCoupon";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";

/**
 * Comprehensive coupon search functionality validation for administrators.
 *
 * This test creates multiple test coupons with controlled configurations to
 * ensure predictable search results. It tests various filter combinations,
 * pagination, sorting, and search functionality to verify the coupon search API
 * works correctly.
 */
export async function test_api_coupon_search_by_admin(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "admin123",
        first_name: RandomGenerator.name(1),
        last_name: RandomGenerator.name(1),
        role: "super_admin",
        permissions: JSON.stringify({ access: "full" }),
        status: "active",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // Step 2: Create controlled test coupons with known distributions
  const coupons: IShoppingMallCoupon[] = [];

  // Create coupons with controlled properties for predictable testing
  const couponConfigs = [
    // Active percentage coupons
    { discountType: "percentage" as const, isActive: true, count: 3 },
    // Active fixed amount coupons
    { discountType: "fixed_amount" as const, isActive: true, count: 3 },
    // Active free shipping coupons
    { discountType: "free_shipping" as const, isActive: true, count: 2 },
    // Inactive percentage coupons
    { discountType: "percentage" as const, isActive: false, count: 2 },
    // Inactive fixed amount coupons
    { discountType: "fixed_amount" as const, isActive: false, count: 2 },
    // Inactive free shipping coupons
    { discountType: "free_shipping" as const, isActive: false, count: 1 },
  ];

  let couponIndex = 0;
  for (const config of couponConfigs) {
    for (let i = 0; i < config.count; i++) {
      const baseValue =
        config.discountType === "percentage"
          ? typia.random<
              number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<50>
            >()
          : config.discountType === "fixed_amount"
            ? typia.random<
                number &
                  tags.Type<"int32"> &
                  tags.Minimum<1000> &
                  tags.Maximum<5000>
              >()
            : typia.random<
                number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<1>
              >();

      const couponData = {
        code: `TEST${String(couponIndex + 1).padStart(2, "0")}${RandomGenerator.alphaNumeric(4).toUpperCase()}`,
        name: `${config.discountType} coupon ${couponIndex + 1}`,
        description: `Test ${config.discountType} coupon ${config.isActive ? "active" : "inactive"}`,
        discount_type: config.discountType,
        discount_value: baseValue,
        minimum_order_amount:
          couponIndex % 3 === 0
            ? typia.random<
                number &
                  tags.Type<"int32"> &
                  tags.Minimum<5000> &
                  tags.Maximum<10000>
              >()
            : undefined,
        maximum_discount:
          config.discountType === "percentage"
            ? typia.random<
                number &
                  tags.Type<"int32"> &
                  tags.Minimum<1000> &
                  tags.Maximum<3000>
              >()
            : undefined,
        usage_limit_per_customer:
          couponIndex % 4 === 0
            ? typia.random<
                number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
              >()
            : undefined,
        total_usage_limit:
          couponIndex % 5 === 0
            ? typia.random<
                number &
                  tags.Type<"int32"> &
                  tags.Minimum<10> &
                  tags.Maximum<50>
              >()
            : undefined,
        valid_from: new Date(Date.now() - 86400000 * couponIndex).toISOString(),
        valid_until: new Date(
          Date.now() + 86400000 * (couponIndex + 30),
        ).toISOString(),
        is_active: config.isActive,
        shopping_mall_channel_id: undefined,
      } satisfies IShoppingMallCoupon.ICreate;

      const coupon: IShoppingMallCoupon =
        await api.functional.shoppingMall.admin.coupons.create(connection, {
          body: couponData,
        });
      typia.assert(coupon);
      coupons.push(coupon);
      couponIndex++;
    }
  }

  // Step 3: Test basic search functionality with known counts
  const activeCouponsCount = coupons.filter((c) => c.is_active).length;
  const percentageCouponsCount = coupons.filter(
    (c) => c.discount_type === "percentage",
  ).length;
  const fixedAmountCouponsCount = coupons.filter(
    (c) => c.discount_type === "fixed_amount",
  ).length;
  const freeShippingCouponsCount = coupons.filter(
    (c) => c.discount_type === "free_shipping",
  ).length;

  // Test search by discount type - percentage
  const percentageSearch: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        discount_type: "percentage",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(percentageSearch);
  TestValidator.equals(
    "percentage coupons count matches",
    percentageSearch.data.length,
    Math.min(percentageCouponsCount, 10),
  );

  // Validate all returned coupons are percentage type
  for (const coupon of percentageSearch.data) {
    TestValidator.equals(
      "percentage search returns only percentage coupons",
      coupon.discount_type,
      "percentage",
    );
  }

  // Test search by discount type - fixed_amount
  const fixedAmountSearch: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        discount_type: "fixed_amount",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(fixedAmountSearch);
  TestValidator.equals(
    "fixed amount coupons count matches",
    fixedAmountSearch.data.length,
    Math.min(fixedAmountCouponsCount, 10),
  );

  // Test search by active status
  const activeSearch: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        is_active: true,
        page: 1,
        limit: 20,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(activeSearch);
  TestValidator.equals(
    "active coupons count matches",
    activeSearch.data.length,
    Math.min(activeCouponsCount, 20),
  );

  // Validate all returned coupons are active
  for (const coupon of activeSearch.data) {
    TestValidator.predicate(
      "active search returns only active coupons",
      coupon.is_active,
    );
  }

  // Test pagination functionality
  const pageSize = 5;
  const totalPages = Math.ceil(coupons.length / pageSize);

  const page1Search: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        page: 1,
        limit: pageSize,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(page1Search);
  TestValidator.equals(
    "page 1 has correct item count",
    page1Search.data.length,
    Math.min(pageSize, coupons.length),
  );

  // Only test page 2 if there are enough coupons
  if (totalPages >= 2) {
    const page2Search: IPageIShoppingMallCoupon.ISummary =
      await api.functional.shoppingMall.admin.coupons.index(connection, {
        body: {
          page: 2,
          limit: pageSize,
        } satisfies IShoppingMallCoupon.IRequest,
      });
    typia.assert(page2Search);
    TestValidator.predicate("page 2 has items", page2Search.data.length > 0);
  }

  // Verify pagination metadata
  TestValidator.predicate(
    "pagination metadata is valid",
    page1Search.pagination.current === 1 &&
      page1Search.pagination.limit === pageSize &&
      page1Search.pagination.records === coupons.length &&
      page1Search.pagination.pages === totalPages,
  );

  // Test sorting functionality
  const sortedByCreatedAt: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        order_by: "created_at",
        order_direction: "desc",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(sortedByCreatedAt);
  TestValidator.predicate(
    "sorted search returns results",
    sortedByCreatedAt.data.length > 0,
  );

  // Test complex filter combinations
  const activePercentageCoupons = coupons.filter(
    (c) => c.is_active && c.discount_type === "percentage",
  ).length;

  const complexSearch: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        discount_type: "percentage",
        is_active: true,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(complexSearch);
  TestValidator.equals(
    "complex search returns correct count",
    complexSearch.data.length,
    Math.min(activePercentageCoupons, 10),
  );

  // Validate complex search results match ALL criteria
  for (const coupon of complexSearch.data) {
    TestValidator.equals(
      "complex search coupon is percentage type",
      coupon.discount_type,
      "percentage",
    );
    TestValidator.predicate(
      "complex search coupon is active",
      coupon.is_active,
    );
  }

  // Test date range filtering - coupons valid in the future
  const futureDate = new Date(Date.now() + 86400000); // Tomorrow
  const futureCoupons = coupons.filter(
    (c) => new Date(c.valid_until) > futureDate,
  ).length;

  const dateRangeSearch: IPageIShoppingMallCoupon.ISummary =
    await api.functional.shoppingMall.admin.coupons.index(connection, {
      body: {
        valid_until_min: futureDate.toISOString(),
        page: 1,
        limit: 10,
      } satisfies IShoppingMallCoupon.IRequest,
    });
  typia.assert(dateRangeSearch);
  TestValidator.equals(
    "future coupons search returns correct count",
    dateRangeSearch.data.length,
    Math.min(futureCoupons, 10),
  );

  // Test search by coupon code (exact match)
  if (coupons.length > 0) {
    const testCoupon = coupons[0];
    const codeSearch: IPageIShoppingMallCoupon.ISummary =
      await api.functional.shoppingMall.admin.coupons.index(connection, {
        body: {
          search: testCoupon.code,
          page: 1,
          limit: 10,
        } satisfies IShoppingMallCoupon.IRequest,
      });
    typia.assert(codeSearch);
    TestValidator.predicate(
      "exact code search returns matching coupon",
      codeSearch.data.some((c) => c.code === testCoupon.code),
    );
  }

  // Test search by coupon name (partial match)
  if (coupons.length > 0) {
    const testCoupon = coupons.find((c) => c.name.includes("percentage"));
    if (testCoupon) {
      const nameSearch: IPageIShoppingMallCoupon.ISummary =
        await api.functional.shoppingMall.admin.coupons.index(connection, {
          body: {
            search: "percentage",
            page: 1,
            limit: 10,
          } satisfies IShoppingMallCoupon.IRequest,
        });
      typia.assert(nameSearch);
      TestValidator.predicate(
        "name search returns matching coupons",
        nameSearch.data.some((c) =>
