  typia.assert(customer);

  // Step 2: Customer submits initial inquiry
  const initialInquiry =
    await api.functional.shoppingMall.customer.inquiries.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
