import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInquiry";
import type { IShoppingMallSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSupportTicket";

/**
 * Test SLA deadline calculation based on different priority levels during
 * support ticket creation. Validates that critical priority tickets receive
 * immediate deadlines, high priority gets expedited timelines, medium priority
 * follows standard SLAs, and low priority has flexible deadlines. The test
 * verifies automatic deadline calculation, priority-based timeline assignment,
 * and proper SLA compliance tracking initialization.
 */
export async function test_api_support_ticket_creation_priority_sla_calculation(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword123!",
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      role: "support_admin",
      permissions: JSON.stringify({
        support_tickets: ["create", "read", "update"],
        inquiries: ["read"],
      }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Define priority levels to test
  const priorities = ["critical", "high", "medium", "low"] as const;
  const categories = [
    "technical_issue",
    "billing_problem",
    "account_security",
    "product_question",
  ] as const;

  // Track tickets by priority
  const tickets: Record<string, IShoppingMallSupportTicket> = {};

  // Step 2: Create tickets with different priority levels
  for (const priority of priorities) {
    const ticketData = {
      title: `Support Ticket - ${priority} priority - ${RandomGenerator.paragraph({ sentences: 2 })}`,
      description: RandomGenerator.content({
        paragraphs: 2,
        sentenceMin: 5,
        sentenceMax: 10,
      }),
      category: RandomGenerator.pick(categories),
      priority: priority,
    } satisfies IShoppingMallSupportTicket.ICreate;

    const ticket =
      await api.functional.shoppingMall.admin.supportTickets.create(
        connection,
        { body: ticketData },
      );
    typia.assert(ticket);
    tickets[priority] = ticket;

    // Validate basic ticket properties
    TestValidator.equals(
      `ticket ${priority} priority matches creation data`,
      ticket.priority,
      priority,
    );
    TestValidator.equals(
      `ticket ${priority} title matches creation data`,
      ticket.title,
      ticketData.title,
    );
    TestValidator.equals(
      `ticket ${priority} description matches creation data`,
      ticket.description,
      ticketData.description,
    );
    TestValidator.equals(
      `ticket ${priority} category matches creation data`,
      ticket.category,
      ticketData.category,
    );
    TestValidator.predicate(
      `ticket ${priority} has valid ticket number format`,
      ticket.ticket_number.length > 0,
    );
    TestValidator.equals(
      `ticket ${priority} has correct initial status`,
      ticket.status,
      "new",
    );
    TestValidator.predicate(
      `ticket ${priority} has valid creation timestamp`,
      ticket.created_at.length > 0 &&
        !isNaN(new Date(ticket.created_at).getTime()),
    );
  }

  // Step 3: Validate SLA deadline calculations based on priority
  const currentTime = new Date();
  const ticketsWithDeadlines = Object.values(tickets).filter(
    (ticket) =>
      ticket.sla_deadline !== undefined && ticket.sla_deadline !== null,
  );

  TestValidator.predicate(
    "at least some tickets have SLA deadlines calculated",
    ticketsWithDeadlines.length > 0,
  );

  // Validate that SLA deadlines are properly formatted and in the future
  for (const ticket of ticketsWithDeadlines) {
    const slaDeadline = typia.assert(ticket.sla_deadline!);
    const deadlineDate = new Date(slaDeadline);
    const creationDate = new Date(ticket.created_at);

    TestValidator.predicate(
      `ticket ${ticket.priority} SLA deadline is valid ISO format`,
      !isNaN(deadlineDate.getTime()),
    );

    TestValidator.predicate(
      `ticket ${ticket.priority} SLA deadline is after creation time`,
      deadlineDate.getTime() > creationDate.getTime(),
    );

    TestValidator.predicate(
      `ticket ${ticket.priority} SLA deadline is in the future`,
      deadlineDate.getTime() > currentTime.getTime(),
    );
  }

  // Step 4: Validate SLA deadline ordering by priority (if multiple tickets have deadlines)
  if (ticketsWithDeadlines.length > 1) {
    const prioritizedDeadlines = ticketsWithDeadlines
      .map((ticket) => ({
        priority: ticket.priority,
        deadline: new Date(typia.assert(ticket.sla_deadline!)),
      }))
      .sort((a, b) => a.deadline.getTime() - b.deadline.getTime());

    // Check that higher priority tickets generally have earlier deadlines
    const priorityWeights = { critical: 0, high: 1, medium: 2, low: 3 };

    TestValidator.predicate(
      "SLA deadlines generally follow priority importance",
      prioritizedDeadlines.every((item, index, array) => {
        if (index === 0) return true;
        const currentPriorityWeight =
          priorityWeights[item.priority as keyof typeof priorityWeights];
        const previousPriorityWeight =
          priorityWeights[
            array[index - 1].priority as keyof typeof priorityWeights
          ];
        return currentPriorityWeight >= previousPriorityWeight;
      }),
    );
  }

  // Step 5: Validate comprehensive ticket properties
  for (const priority of priorities) {
    const ticket = tickets[priority];

    TestValidator.predicate(
      `ticket ${priority} has valid UUID format ID`,
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        ticket.id,
      ),
    );

    TestValidator.predicate(
      `ticket ${priority} creation timestamp is before update timestamp`,
      new Date(ticket.created_at).getTime() <=
        new Date(ticket.updated_at).getTime(),
    );

    TestValidator.predicate(
      `ticket ${priority} has no resolution notes initially`,
      ticket.resolution_notes === undefined || ticket.resolution_notes === null,
    );

    TestValidator.predicate(
      `ticket ${priority} has no assigned administrator initially`,
      ticket.assigned_administrator === undefined ||
        ticket.assigned_administrator === null,
    );
  }

  // Step 6: Test business logic validation
  TestValidator.predicate(
    "all tickets have unique IDs",
    new Set(Object.values(tickets).map((t) => t.id)).size === priorities.length,
  );

  TestValidator.predicate(
    "all tickets have unique ticket numbers",
    new Set(Object.values(tickets).map((t) => t.ticket_number)).size ===
      priorities.length,
  );

  // Final validation that all API responses are properly structured
  for (const ticket of Object.values(tickets)) {
    typia.assert(ticket);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInquiry";
import type { IShoppingMallSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSupportTicket";

/**
 * Test complete support ticket lifecycle through status transitions from
 * creation to resolution and closure. Validates that administrators can update
 * ticket status through proper workflow progression: new → open → in_progress →
 * resolved → closed. The test verifies status transition validation, resolution
 * note documentation, closure verification, and proper timestamp recording for
 * each status change. Business logic includes workflow enforcement, status
 * transition rules, and audit trail maintenance throughout the ticket
 * lifecycle.
 */
export async function test_api_support_ticket_full_lifecycle_update(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ canManageTickets: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Generate realistic ticket data with random categories and priorities
  const categories = [
    "technical_issue",
    "billing_problem",
    "account_security",
    "product_question",
    "general_feedback",
  ] as const;
  const priorities = ["low", "medium", "high", "critical"] as const;

  const selectedCategory = RandomGenerator.pick(categories);
  const selectedPriority = RandomGenerator.pick(priorities);

  // Step 2: Create initial support ticket with status 'new'
  const ticketData = {
    title: RandomGenerator.paragraph({ sentences: 3, wordMin: 4, wordMax: 8 }),
    description: RandomGenerator.content({
      paragraphs: 2,
      sentenceMin: 5,
      sentenceMax: 10,
    }),
    category: selectedCategory,
    priority: selectedPriority,
  } satisfies IShoppingMallSupportTicket.ICreate;

  const createdTicket =
    await api.functional.shoppingMall.admin.supportTickets.create(connection, {
      body: ticketData,
    });
  typia.assert(createdTicket);

  TestValidator.equals(
    "initial ticket status should be new",
    createdTicket.status,
    "new",
  );
  TestValidator.equals(
    "ticket title matches creation data",
    createdTicket.title,
    ticketData.title,
  );
  TestValidator.equals(
    "ticket category matches creation data",
    createdTicket.category,
    selectedCategory,
  );
  TestValidator.equals(
    "ticket priority matches creation data",
    createdTicket.priority,
    selectedPriority,
  );

  // Step 3: Update ticket status from 'new' to 'open' with SLA deadline
  const tomorrow = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
  const openTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: createdTicket.id,
      body: {
        status: "open",
        sla_deadline: tomorrow,
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(openTicket);
  TestValidator.equals(
    "ticket status should be open",
    openTicket.status,
    "open",
  );
  TestValidator.equals(
    "SLA deadline should be set",
    openTicket.sla_deadline,
    tomorrow,
  );

  // Step 4: Update ticket status from 'open' to 'in_progress' with updated details
  const inProgressTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: createdTicket.id,
      body: {
        status: "in_progress",
        title: "[In Progress] " + createdTicket.title,
        description:
          createdTicket.description +
          "\n\nIssue is currently being investigated by our technical team.",
        priority: "high", // Escalate priority during investigation
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(inProgressTicket);
  TestValidator.equals(
    "ticket status should be in_progress",
    inProgressTicket.status,
    "in_progress",
  );
  TestValidator.predicate(
    "title should indicate in progress status",
    inProgressTicket.title.startsWith("[In Progress] "),
  );
  TestValidator.equals(
    "priority should be escalated",
    inProgressTicket.priority,
    "high",
  );

  // Step 5: Update ticket status from 'in_progress' to 'resolved' with comprehensive resolution notes
  const resolutionTime = new Date().toISOString();
  const resolvedTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: createdTicket.id,
      body: {
        status: "resolved",
        resolution_notes: `Issue resolved successfully.\n\nRoot Cause: Software configuration mismatch\nSolution Applied: Updated configuration settings and verified functionality\nCustomer Communication: Customer confirmed resolution via email on ${new Date().toLocaleDateString()}\nFollow-up Required: None`,
        resolved_at: resolutionTime,
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(resolvedTicket);
  TestValidator.equals(
    "ticket status should be resolved",
    resolvedTicket.status,
    "resolved",
  );
  TestValidator.predicate(
    "resolution notes should be comprehensive",
    resolvedTicket.resolution_notes !== undefined &&
      resolvedTicket.resolution_notes.length > 50,
  );
  TestValidator.equals(
    "resolved_at timestamp should match update",
    resolvedTicket.resolved_at,
    resolutionTime,
  );

  // Step 6: Update ticket status from 'resolved' to 'closed'
  const closedTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: createdTicket.id,
      body: {
        status: "closed",
        closed_at: new Date().toISOString(),
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(closedTicket);
  TestValidator.equals(
    "ticket status should be closed",
    closedTicket.status,
    "closed",
  );
  TestValidator.predicate(
    "closed_at timestamp should be set",
    closedTicket.closed_at !== undefined,
  );

  // Step 7: Validate final ticket state and audit trail
  TestValidator.equals(
    "ticket ID should remain consistent throughout lifecycle",
    closedTicket.id,
    createdTicket.id,
  );
  TestValidator.equals(
    "ticket number should remain consistent",
    closedTicket.ticket_number,
    createdTicket.ticket_number,
  );
  TestValidator.predicate(
    "updated_at should be more recent than created_at",
    new Date(closedTicket.updated_at) > new Date(createdTicket.created_at),
  );
  TestValidator.predicate(
    "ticket should have proper audit trail with all status transitions recorded",
    closedTicket.status === "closed" &&
      closedTicket.resolved_at !== undefined &&
      closedTicket.closed_at !== undefined,
  );

  // Step 8: Test invalid status transition (should fail)
  await TestValidator.error(
    "should reject invalid status transition from closed back to open",
    async () => {
      await api.functional.shoppingMall.admin.supportTickets.update(
        connection,
        {
          ticketId: closedTicket.id,
          body: {
            status: "open", // Invalid: cannot reopen closed ticket
          } satisfies IShoppingMallSupportTicket.IUpdate,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInquiry";
import type { IShoppingMallSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSupportTicket";

/**
 * Test support ticket priority escalation during active resolution processes.
 *
 * Validates that administrators can escalate ticket priority from lower to
 * higher levels (low → medium → high → critical) and that SLA deadlines are
 * recalculated accordingly. The test verifies priority transition validation,
 * deadline recalculation, escalation notification triggers, and proper audit
 * trail for priority changes.
 */
export async function test_api_support_ticket_priority_escalation_update(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPassword123!";

  const adminAuth = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({
        support_tickets: ["create", "read", "update", "delete"],
        priority_escalation: ["execute"],
      }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(adminAuth);

  // Step 2: Create initial support ticket with low priority
  const initialTicket =
    await api.functional.shoppingMall.admin.supportTickets.create(connection, {
      body: {
        title: RandomGenerator.paragraph({
          sentences: 5,
          wordMin: 3,
          wordMax: 8,
        }),
        description: RandomGenerator.content({
          paragraphs: 2,
          sentenceMin: 10,
          sentenceMax: 20,
        }),
        category: "technical_issue",
        priority: "low",
      } satisfies IShoppingMallSupportTicket.ICreate,
    });
  typia.assert(initialTicket);
  TestValidator.equals(
    "initial ticket priority should be low",
    initialTicket.priority,
    "low",
  );

  // Step 3: Escalate priority from low to medium
  const mediumPriorityTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        priority: "medium",
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(mediumPriorityTicket);
  TestValidator.equals(
    "priority should escalate to medium",
    mediumPriorityTicket.priority,
    "medium",
  );
  TestValidator.notEquals(
    "ticket should be updated",
    mediumPriorityTicket.updated_at,
    initialTicket.updated_at,
  );

  // Step 4: Escalate priority from medium to high
  const highPriorityTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        priority: "high",
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(highPriorityTicket);
  TestValidator.equals(
    "priority should escalate to high",
    highPriorityTicket.priority,
    "high",
  );
  TestValidator.notEquals(
    "ticket should be updated again",
    highPriorityTicket.updated_at,
    mediumPriorityTicket.updated_at,
  );

  // Step 5: Escalate priority from high to critical
  const criticalPriorityTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        priority: "critical",
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(criticalPriorityTicket);
  TestValidator.equals(
    "priority should escalate to critical",
    criticalPriorityTicket.priority,
    "critical",
  );
  TestValidator.notEquals(
    "ticket should have final update",
    criticalPriorityTicket.updated_at,
    highPriorityTicket.updated_at,
  );

  // Step 6: Verify SLA deadline recalculation
  TestValidator.predicate(
    "SLA deadline should be set for critical priority",
    criticalPriorityTicket.sla_deadline !== undefined &&
      criticalPriorityTicket.sla_deadline !== null,
  );

  // Step 7: Final validation of priority escalation sequence
  const finalTicket =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        status: "in_progress",
        resolution_notes: "Priority escalation test completed successfully",
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(finalTicket);
  TestValidator.equals(
    "final ticket should maintain critical priority",
    finalTicket.priority,
    "critical",
  );
  TestValidator.equals(
    "ticket status should be in progress",
    finalTicket.status,
    "in_progress",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInquiry";
import type { IShoppingMallSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSupportTicket";

/**
 * Test partial updates to support ticket fields without requiring complete
 * record replacement. Validates that administrators can modify specific ticket
 * attributes independently, such as updating only the description, changing
 * only the category, or adjusting only the priority. The test verifies
 * field-level update validation, partial update functionality, audit trail for
 * individual field changes, and proper isolation of modified fields from
 * unchanged ones.
 */
export async function test_api_support_ticket_partial_field_update(
  connection: api.IConnection,
) {
  // Step 1: Authenticate as administrator
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword123!",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({
        support_tickets: ["read", "write", "update"],
        inquiries: ["read"],
      }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create initial support ticket
  const initialTicket =
    await api.functional.shoppingMall.admin.supportTickets.create(connection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        category: "technical_issue",
        priority: "medium",
      } satisfies IShoppingMallSupportTicket.ICreate,
    });
  typia.assert(initialTicket);

  // Step 3: Test partial update - title only
  const updatedTitle = RandomGenerator.paragraph({ sentences: 4 });
  const titleOnlyUpdate =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        title: updatedTitle,
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(titleOnlyUpdate);

  // Validate title was updated, other fields remain unchanged
  TestValidator.equals(
    "title should be updated",
    titleOnlyUpdate.title,
    updatedTitle,
  );
  TestValidator.equals(
    "description should remain unchanged",
    titleOnlyUpdate.description,
    initialTicket.description,
  );
  TestValidator.equals(
    "category should remain unchanged",
    titleOnlyUpdate.category,
    initialTicket.category,
  );
  TestValidator.equals(
    "priority should remain unchanged",
    titleOnlyUpdate.priority,
    initialTicket.priority,
  );

  // Step 4: Test partial update - description only
  const updatedDescription = RandomGenerator.content({ paragraphs: 3 });
  const descriptionOnlyUpdate =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        description: updatedDescription,
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(descriptionOnlyUpdate);

  // Validate description was updated, other fields remain unchanged
  TestValidator.equals(
    "title should remain unchanged from previous update",
    descriptionOnlyUpdate.title,
    updatedTitle,
  );
  TestValidator.equals(
    "description should be updated",
    descriptionOnlyUpdate.description,
    updatedDescription,
  );
  TestValidator.equals(
    "category should remain unchanged",
    descriptionOnlyUpdate.category,
    initialTicket.category,
  );
  TestValidator.equals(
    "priority should remain unchanged",
    descriptionOnlyUpdate.priority,
    initialTicket.priority,
  );

  // Step 5: Test partial update - category only
  const updatedCategory = "billing_problem";
  const categoryOnlyUpdate =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        category: updatedCategory,
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(categoryOnlyUpdate);

  // Validate category was updated, other fields remain unchanged
  TestValidator.equals(
    "title should remain unchanged",
    categoryOnlyUpdate.title,
    updatedTitle,
  );
  TestValidator.equals(
    "description should remain unchanged",
    categoryOnlyUpdate.description,
    updatedDescription,
  );
  TestValidator.equals(
    "category should be updated",
    categoryOnlyUpdate.category,
    updatedCategory,
  );
  TestValidator.equals(
    "priority should remain unchanged",
    categoryOnlyUpdate.priority,
    initialTicket.priority,
  );

  // Step 6: Test partial update - priority only
  const updatedPriority = "high";
  const priorityOnlyUpdate =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
      ticketId: initialTicket.id,
      body: {
        priority: updatedPriority,
      } satisfies IShoppingMallSupportTicket.IUpdate,
    });
  typia.assert(priorityOnlyUpdate);

  // Validate priority was updated, other fields remain unchanged
  TestValidator.equals(
    "title should remain unchanged",
    priorityOnlyUpdate.title,
    updatedTitle,
  );
  TestValidator.equals(
    "description should remain unchanged",
    priorityOnlyUpdate.description,
    updatedDescription,
  );
  TestValidator.equals(
    "category should remain unchanged",
    priorityOnlyUpdate.category,
    updatedCategory,
  );
  TestValidator.equals(
    "priority should be updated",
    priorityOnlyUpdate.priority,
    updatedPriority,
  );

  // Step 7: Test audit trail by checking updated_at timestamp changes
  TestValidator.predicate(
    "updated_at should be newer after modifications",
    new Date(priorityOnlyUpdate.updated_at) >
      new Date(initialTicket.updated_at),
  );

  // Step 8: Test empty update (should succeed but change nothing)
  const emptyUpdate =
    await api.functional.shoppingMall.admin.supportTickets.update(connection, {
