/**
 * Test article search filtering by actor type (customer, seller, administrator)
 * to validate content attribution and ownership-based access controls.
 *
 * This test validates the comprehensive article search functionality with actor
 * type filtering capabilities, ensuring proper content visibility based on
 * creator roles and publication status. The test covers multiple filtering
 * scenarios including basic actor type filtering, combined filtering with
 * status and engagement metrics, and proper pagination handling.
 */
export async function test_api_article_search_by_actor_type(
  connection: api.IConnection,
) {
  // Test 1: Basic actor type filtering with valid actor types
  const actorTypes = ["customer", "seller", "administrator"] as const;

  for (const actorType of actorTypes) {
    const searchResult1 = await api.functional.shoppingMall.articles.index(
      connection,
      {
        body: {
          page: 1,
          limit: 10,
          actor_type: actorType,
        } satisfies IShoppingMallArticle.IRequest,
      },
    );
    typia.assert(searchResult1);

    TestValidator.equals(
      `search result should have pagination data for actor type ${actorType}`,
      searchResult1.pagination.current,
      1,
    );
    TestValidator.predicate(
      `search result should have valid limit for actor type ${actorType}`,
      searchResult1.pagination.limit > 0,
    );

    // Validate article summary structure when data exists
    if (searchResult1.data.length > 0) {
      const firstArticle = searchResult1.data[0];
      TestValidator.predicate(
        `article should have valid ID structure for actor type ${actorType}`,
        typeof firstArticle.id === "string" && firstArticle.id.length > 0,
      );
      TestValidator.predicate(
        `article should have title for actor type ${actorType}`,
        typeof firstArticle.title === "string",
      );
    }
  }

  // Test 2: Combined filtering with actor type and publication status
  const statusValues = [
    "draft",
    "pending_review",
    "published",
    "archived",
  ] as const;

  for (const status of statusValues) {
    const searchResult2 = await api.functional.shoppingMall.articles.index(
      connection,
      {
        body: {
          page: 1,
          limit: 5,
          actor_type: "customer",
          status: status,
        } satisfies IShoppingMallArticle.IRequest,
      },
    );
    typia.assert(searchResult2);

    TestValidator.equals(
      `combined filter should return valid pagination for status ${status}`,
      searchResult2.pagination.current,
      1,
    );
  }

  // Test 3: Engagement metrics filtering with actor type
  const searchResult3 = await api.functional.shoppingMall.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        actor_type: "seller",
        view_count_min: 0,
        view_count_max: 1000,
        like_count_min: 0,
        like_count_max: 100,
      } satisfies IShoppingMallArticle.IRequest,
    },
  );
  typia.assert(searchResult3);

  TestValidator.predicate(
    "engagement filtering should return valid pagination",
    searchResult3.pagination.pages >= 0,
  );

  // Test 4: Pagination and sorting with actor type filtering
  const searchResult4 = await api.functional.shoppingMall.articles.index(
    connection,
    {
      body: {
        page: 2,
        limit: 5,
        actor_type: "administrator",
        sort_by: "created_at",
        order: "desc",
      } satisfies IShoppingMallArticle.IRequest,
    },
  );
  typia.assert(searchResult4);

  TestValidator.equals(
    "pagination should return correct page number",
    searchResult4.pagination.current,
    2,
  );

  // Test 5: Full-text search combined with actor type filtering
  const searchResult5 = await api.functional.shoppingMall.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        actor_type: "customer",
        search: "test",
        featured: true,
        allow_comments: true,
      } satisfies IShoppingMallArticle.IRequest,
    },
  );
  typia.assert(searchResult5);

  TestValidator.predicate(
    "full-text search with actor type should return valid structure",
    Array.isArray(searchResult5.data),
  );

  // Test 6: Complex filtering with multiple criteria
  const searchResult7 = await api.functional.shoppingMall.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 20,
        actor_type: "seller",
        status: "published",
        featured: true,
        allow_comments: true,
        view_count_min: 10,
        like_count_min: 5,
        sort_by: "view_count",
        order: "desc",
      } satisfies IShoppingMallArticle.IRequest,
    },
  );
  typia.assert(searchResult7);

  TestValidator.equals(
    "complex filtering should maintain pagination integrity",
    searchResult7.pagination.limit,
    20,
  );

  // Test 7: Empty filtering scenario with specific criteria
  const searchResult8 = await api.functional.shoppingMall.articles.index(
    connection,
    {
      body: {
        page: 1,
        limit: 10,
        actor_type: "customer",
        status: "published",
        view_count_min: 1000000, // Very high threshold likely to return empty
      } satisfies IShoppingMallArticle.IRequest,
    },
  );
  typia.assert(searchResult8);

  TestValidator.predicate(
    "empty result scenario should still have valid pagination",
    searchResult8.pagination.records >= 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallWishlist";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlist";
import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

/**
 * Test comprehensive wishlist search functionality for authenticated customers.
 *
 * This test validates that customers can search their wishlists with various
 * filters including name matching, status filtering (active/archived/shared),
 * priority ranges, and public/private visibility. It also tests pagination with
 * different page sizes and ordering options.
 *
 * The test creates multiple wishlists with different settings to ensure search
 * returns correct results based on filters and that private wishlists from
 * other customers are not visible.
 */
export async function test_api_wishlist_search_by_customer(
  connection: api.IConnection,
) {
  // Step 1: Create customer account and authenticate
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "test1234",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://shoppingmall.test/register",
      referrer: "https://shoppingmall.test",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create multiple wishlists with different settings
  const wishlists: IShoppingMallWishlist[] = [];

  // Create wishlist with high priority and active status
  const highPriorityWishlist =
    await api.functional.shoppingMall.customer.wishlists.create(connection, {
      body: {
        name: "High Priority Electronics",
        description: "High priority electronics wishlist",
        is_public: true,
        priority: 10,
        status: "active",
      } satisfies IShoppingMallWishlist.ICreate,
    });
  typia.assert(highPriorityWishlist);
  wishlists.push(highPriorityWishlist);

  // Create wishlist with medium priority and archived status
  const archivedWishlist =
    await api.functional.shoppingMall.customer.wishlists.create(connection, {
      body: {
        name: "Archived Books Collection",
        description: "Old book collection",
        is_public: false,
        priority: 5,
        status: "archived",
      } satisfies IShoppingMallWishlist.ICreate,
    });
  typia.assert(archivedWishlist);
  wishlists.push(archivedWishlist);

  // Create wishlist with low priority and shared status
  const sharedWishlist =
    await api.functional.shoppingMall.customer.wishlists.create(connection, {
      body: {
        name: "Shared Gift Ideas",
        description: "Gift ideas to share with family",
        is_public: true,
        priority: 3,
        status: "shared",
      } satisfies IShoppingMallWishlist.ICreate,
    });
  typia.assert(sharedWishlist);
  wishlists.push(sharedWishlist);

  // Create another wishlist with different name pattern
  const anotherWishlist =
    await api.functional.shoppingMall.customer.wishlists.create(connection, {
      body: {
        name: "Home Decor Items",
        description: "Items for home decoration",
        is_public: false,
        priority: 7,
        status: "active",
      } satisfies IShoppingMallWishlist.ICreate,
    });
  typia.assert(anotherWishlist);
  wishlists.push(anotherWishlist);

  // Step 3: Test basic search without filters
  const allWishlistsResult =
    await api.functional.shoppingMall.customer.wishlists.index(connection, {
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallWishlist.IRequest,
    });
  typia.assert(allWishlistsResult);
  TestValidator.equals(
    "should return all created wishlists",
    allWishlistsResult.data.length,
    wishlists.length,
  );

  // Step 4: Test search by name matching
  const searchResult =
    await api.functional.shoppingMall.customer.wishlists.index(connection, {
      body: {
        search: "Electronics",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallWishlist.IRequest,
    });
  typia.assert(searchResult);
  TestValidator.predicate(
    "search should find wishlist with matching name",
    searchResult.data.some((w) => w.name.includes("Electronics")),
  );

  // Step 5: Test status filtering
  const activeWishlistsResult =
    await api.functional.shoppingMall.customer.wishlists.index(connection, {
      body: {
        status: "active",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallWishlist.IRequest,
    });
  typia.assert(activeWishlistsResult);
  TestValidator.predicate(
    "should only return active wishlists",
    activeWishlistsResult.data.every((w) => w.status === "active"),
  );

  // Step 6: Test priority range filtering
  const priorityRangeResult =
    await api.functional.shoppingMall.customer.wishlists.index(connection, {
      body: {
        priority_min: 5,
        priority_max: 8,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallWishlist.IRequest,
    });
  typia.assert(priorityRangeResult);
  TestValidator.predicate(
    "should return wishlists within priority range",
    priorityRangeResult.data.every((w) => w.priority >= 5 && w.priority <= 8),
  );

  // Step 7: Test public/private filtering
  const publicWishlistsResult =
    await api.functional.shoppingMall.customer.wishlists.index(connection, {
      body: {
        is_public: true,
        page: 1,
        limit: 10,
