          tags.MaxLength<255>,
        page: 1,
        limit: 10,
      } satisfies IShoppingMallWishlist.IRequest,
    });
  typia.assert(searchResult1);
  TestValidator.predicate(
    "search by name returns matching wishlists",
    searchResult1.data.length > 0,
