  // 4. Test 2: Filter by active status
  const searchResult2 =
    await api.functional.shoppingMall.customer.wishlists.index(connection, {
      body: {
        status: "active",
        page: 1,
        limit: 10,
      } satisfies IShoppingMallWishlist.IRequest,
    });
