/**
 * Test comment search filtering by different moderation statuses
 *
 * This E2E test validates the shopping mall article comment search
 * functionality with comprehensive status-based filtering. It creates comments
 * and tests that the search API correctly handles various moderation status
 * parameters.
 *
 * The test focuses on validating the search functionality with proper status
 * filtering capabilities and pagination behavior.
 */
export async function test_api_article_comments_search_by_status_filter(
  connection: api.IConnection,
) {
  // Step 1: Create admin account for channel and article creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123";

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "super_admin",
      permissions: JSON.stringify({ can_manage_content: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create shopping mall channel
  const channel = await api.functional.shoppingMall.admin.channels.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(channel);

  // Step 3: Create article to host comments
  const article = await api.functional.shoppingMall.admin.articles.create(
    connection,
    {
      body: {
        actor_type: "administrator",
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({ paragraphs: 3 }),
        channel_id: channel.id,
        allow_comments: true,
      } satisfies IShoppingMallArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 4: Create customer account for comment creation
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customer123";

  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 5: Create multiple comments for testing
  const commentCount = 4;
  const createdComments: IShoppingMallArticleComment[] = [];

  for (let i = 0; i < commentCount; i++) {
    const comment =
      await api.functional.shoppingMall.customer.articles.comments.create(
        connection,
        {
          articleId: article.id,
          body: {
            content: RandomGenerator.content({ paragraphs: 1 }),
            actor_type: "customer",
          } satisfies IShoppingMallArticleComment.ICreate,
        },
      );
    typia.assert(comment);
    createdComments.push(comment);
  }

  // Step 6: Test search functionality with different status filters
  // Test 6.1: Search all comments (no status filter)
  const allComments = await api.functional.shoppingMall.articles.comments.index(
    connection,
    {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
      } satisfies IShoppingMallArticleComment.IRequest,
    },
  );
  typia.assert(allComments);
  TestValidator.equals(
    "all comments should be returned",
    allComments.data.length,
    commentCount,
  );

  // Test 6.2: Search with specific status filter (approved)
  const approvedComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        status: "approved",
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(approvedComments);

  // Verify all returned comments have the filtered status
  for (const comment of approvedComments.data) {
    TestValidator.equals(
      "comment should have approved status",
      comment.status,
      "approved",
    );
  }

  // Test 6.3: Search with pending status filter
  const pendingComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        status: "pending",
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(pendingComments);

  // Test 6.4: Search with rejected status filter
  const rejectedComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        status: "rejected",
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(rejectedComments);

  // Test 6.5: Search with flagged status filter
  const flaggedComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        status: "flagged",
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(flaggedComments);

  // Step 7: Test pagination functionality
  const paginatedComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 2,
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(paginatedComments);
  TestValidator.equals(
    "pagination should limit results",
    paginatedComments.data.length,
    2,
  );
  TestValidator.predicate(
    "pagination metadata should be present",
    paginatedComments.pagination.pages > 0,
  );

  // Step 8: Test search with content filtering
  const searchTerm = createdComments[0]?.content.substring(0, 10);
  if (searchTerm) {
    const searchedComments =
      await api.functional.shoppingMall.articles.comments.index(connection, {
        articleId: article.id,
        body: {
          page: 1,
          limit: 10,
          search: searchTerm,
        } satisfies IShoppingMallArticleComment.IRequest,
      });
    typia.assert(searchedComments);
    TestValidator.predicate(
      "search should return matching comments",
      searchedComments.data.length > 0,
    );
  }

  // Step 9: Test actor type filtering
  const customerComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        actor_type: "customer",
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(customerComments);

  for (const comment of customerComments.data) {
    TestValidator.equals(
      "comment should have customer actor type",
      comment.actor_type,
      "customer",
    );
  }

  // Step 10: Test sorting functionality
  const sortedComments =
    await api.functional.shoppingMall.articles.comments.index(connection, {
      articleId: article.id,
      body: {
        page: 1,
        limit: 10,
        sort_by: "created_at",
        order: "desc",
      } satisfies IShoppingMallArticleComment.IRequest,
    });
  typia.assert(sortedComments);
  TestValidator.predicate(
    "sorted comments should be returned",
    sortedComments.data.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticle";
import type { IShoppingMallArticleComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleComment";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";

/**
 * Test retrieving a specific comment by its unique identifier.
 *
 * This E2E test validates the comment retrieval functionality by creating an
 * article with multiple comments, then retrieving individual comments by their
 * IDs to verify accurate comment retrieval. The test validates that the system
 * returns complete comment information including content, engagement metrics,
 * moderation status, and proper actor attribution.
 */
export async function test_api_article_comment_retrieval_by_id(
  connection: api.IConnection,
) {
  // 1. Create administrator account
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdministrator.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "admin123",
        first_name: "Admin",
        last_name: "User",
        role: "super_admin",
        permissions: "{}",
      } satisfies IShoppingMallAdministrator.ICreate,
    });
  typia.assert(admin);

  // 2. Create shopping mall channel
  const channel: IShoppingMallChannel =
    await api.functional.shoppingMall.admin.channels.create(connection, {
      body: {
        code: "test-channel",
        name: "Test Channel",
        description: "Test channel for article comments",
        status: "active",
      } satisfies IShoppingMallChannel.ICreate,
    });
  typia.assert(channel);

  // 3. Create article
  const article: IShoppingMallArticle =
    await api.functional.shoppingMall.admin.articles.create(connection, {
      body: {
        actor_type: "administrator",
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        featured: false,
        allow_comments: true,
        channel_id: channel.id,
      } satisfies IShoppingMallArticle.ICreate,
    });
  typia.assert(article);

  // 4. Create customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "customer123",
        first_name: "Test",
        last_name: "Customer",
        phone_number: RandomGenerator.mobile(),
        href: "https://example.com",
        referrer: "https://example.com",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 5. Switch to customer authentication
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "customer123",
      href: "https://example.com",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 6. Create multiple comments
  const comments: IShoppingMallArticleComment[] = [];

  for (let i = 0; i < 3; i++) {
    const comment: IShoppingMallArticleComment =
      await api.functional.shoppingMall.customer.articles.comments.create(
        connection,
        {
          articleId: article.id,
          body: {
            content: RandomGenerator.paragraph({ sentences: 2 }),
            actor_type: "customer",
          } satisfies IShoppingMallArticleComment.ICreate,
        },
      );
    typia.assert(comment);
    comments.push(comment);
  }

  // 7. Retrieve and validate each comment
  for (const createdComment of comments) {
    const retrievedComment: IShoppingMallArticleComment =
      await api.functional.shoppingMall.articles.comments.at(connection, {
        articleId: article.id,
        commentId: createdComment.id,
      });
    typia.assert(retrievedComment);

    // Validate comment data integrity
    TestValidator.equals(
      "comment ID matches",
      retrievedComment.id,
      createdComment.id,
    );
    TestValidator.equals(
      "comment content matches",
      retrievedComment.content,
      createdComment.content,
    );
    TestValidator.equals(
      "comment status matches",
      retrievedComment.status,
      createdComment.status,
    );
    TestValidator.equals(
      "comment actor type matches",
      retrievedComment.actor_type,
      createdComment.actor_type,
    );
    TestValidator.equals(
      "comment like count matches",
      retrievedComment.like_count,
      createdComment.like_count,
    );
    TestValidator.equals(
      "comment report count matches",
      retrievedComment.report_count,
      createdComment.report_count,
    );
    TestValidator.equals(
      "comment depth matches",
      retrievedComment.depth,
      createdComment.depth,
    );
    TestValidator.equals(
      "article ID matches",
      retrievedComment.shopping_mall_article_id,
      article.id,
    );

    // Validate comment-article relationship
    TestValidator.predicate(
      "comment has article reference",
      retrievedComment.article !== undefined,
    );
    if (retrievedComment.article) {
      TestValidator.equals(
        "article ID in comment reference matches",
        retrievedComment.article.id,
        article.id,
      );
      TestValidator.equals(
        "article title in comment reference matches",
        retrievedComment.article.title,
        article.title,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticle";
import type { IShoppingMallArticleComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallArticleComment";
import type { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import type { IShoppingMallConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallConfiguration";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";

/**
 * Test retrieving comments within threaded discussion hierarchies
 *
 * This test validates the comment retrieval functionality by creating a complex
 * threaded discussion structure with parent comments and nested replies at
 * different depth levels. It ensures that individual comment retrieval
 * correctly preserves hierarchical relationships, depth tracking, and all
 * comment properties.
 */
export async function test_api_article_comment_retrieval_with_threaded_discussions(
  connection: api.IConnection,
) {
  // Step 1: Create admin account and authenticate
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin123456";

  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      first_name: "Admin",
      last_name: "User",
      role: "super_admin",
      permissions: JSON.stringify({ access_level: "full" }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Create shopping mall channel
  const channel = await api.functional.shoppingMall.admin.channels.create(
    connection,
    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        status: "active",
        configuration: JSON.stringify({ allow_comments: true }),
      } satisfies IShoppingMallChannel.ICreate,
    },
  );
  typia.assert(channel);

  // Step 3: Create article
  const article = await api.functional.shoppingMall.admin.articles.create(
    connection,
    {
      body: {
        actor_type: "administrator",
        title: RandomGenerator.paragraph({ sentences: 3 }),
        subtitle: RandomGenerator.paragraph({ sentences: 1 }),
        content: RandomGenerator.content({ paragraphs: 3 }),
        summary: RandomGenerator.paragraph({ sentences: 2 }),
        featured: true,
        allow_comments: true,
        channel_id: channel.id,
      } satisfies IShoppingMallArticle.ICreate,
    },
  );
  typia.assert(article);

  // Step 4: Create customer account and authenticate
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "customer123456";

  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      first_name: "Customer",
      last_name: "User",
      phone_number: RandomGenerator.mobile(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 5: Create threaded comment hierarchy
  // Create parent comment (depth 0)
  const parentComment =
    await api.functional.shoppingMall.customer.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.content({ paragraphs: 1 }),
          actor_type: "customer",
        } satisfies IShoppingMallArticleComment.ICreate,
      },
    );
  typia.assert(parentComment);

  // Create first-level reply (depth 1)
  const firstLevelReply =
    await api.functional.shoppingMall.customer.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.content({ paragraphs: 1 }),
          parent: {
            id: parentComment.id,
            content: parentComment.content,
            status: parentComment.status,
            like_count: parentComment.like_count,
            report_count: parentComment.report_count,
            depth: parentComment.depth,
            actor_type: parentComment.actor_type,
          } satisfies IShoppingMallArticleComment.ISummary,
          actor_type: "customer",
        } satisfies IShoppingMallArticleComment.ICreate,
      },
    );
  typia.assert(firstLevelReply);

  // Create second-level reply (depth 2)
  const secondLevelReply =
    await api.functional.shoppingMall.customer.articles.comments.create(
      connection,
      {
        articleId: article.id,
        body: {
          content: RandomGenerator.content({ paragraphs: 1 }),
          parent: {
            id: firstLevelReply.id,
            content: firstLevelReply.content,
            status: firstLevelReply.status,
            like_count: firstLevelReply.like_count,
            report_count: firstLevelReply.report_count,
            depth: firstLevelReply.depth,
            actor_type: firstLevelReply.actor_type,
          } satisfies IShoppingMallArticleComment.ISummary,
          actor_type: "customer",
        } satisfies IShoppingMallArticleComment.ICreate,
      },
    );
  typia.assert(secondLevelReply);

  // Step 6: Test retrieval of individual comments
  // Retrieve parent comment
  const retrievedParent =
    await api.functional.shoppingMall.articles.comments.at(connection, {
      articleId: article.id,
      commentId: parentComment.id,
    });
  typia.assert(retrievedParent);

  TestValidator.equals(
    "parent comment ID should match created comment",
    retrievedParent.id,
    parentComment.id,
  );
  TestValidator.equals(
    "parent comment content should match original",
    retrievedParent.content,
    parentComment.content,
  );
  TestValidator.equals(
    "parent comment depth should be 0",
    retrievedParent.depth,
    0,
  );
  TestValidator.equals(
