  );
  TestValidator.equals(
    "first-level reply should have zero reports initially",
    retrievedFirstLevel.report_count,
    0,
  );
  TestValidator.equals(
    "second-level reply should have zero reports initially",
    retrievedSecondLevel.report_count,
