import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

/**
 * Test wishlist priority reorganization scenario. Customer creates multiple
 * wishlists with different priority levels, then updates their priorities to
 * reorganize the display order. Validates that priority changes are correctly
 * applied, wishlist sorting reflects new priorities, and multiple wishlist
 * management works properly with priority-based organization.
 */
export async function test_api_customer_wishlist_update_priority_reorganization(
  connection: api.IConnection,
) {
  // Step 1: Customer authentication and account creation
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "password123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://example.com/register",
      referrer: "https://example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create first wishlist with initial priority
  const wishlist1 = await api.functional.shoppingMall.customer.wishlists.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        is_public: false,
        priority: 5,
        status: "active",
      } satisfies IShoppingMallWishlist.ICreate,
    },
  );
  typia.assert(wishlist1);

  // Step 3: Create second wishlist with different priority
  const wishlist2 = await api.functional.shoppingMall.customer.wishlists.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        is_public: true,
        priority: 3,
        status: "active",
      } satisfies IShoppingMallWishlist.ICreate,
    },
  );
  typia.assert(wishlist2);

  // Step 4: Create third wishlist with another priority
  const wishlist3 = await api.functional.shoppingMall.customer.wishlists.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        is_public: false,
        priority: 8,
        status: "active",
      } satisfies IShoppingMallWishlist.ICreate,
    },
  );
  typia.assert(wishlist3);

  // Step 5: Update priorities to reorganize the display order
  // Update wishlist1 to highest priority
  const updatedWishlist1 =
    await api.functional.shoppingMall.customer.wishlists.update(connection, {
      wishlistId: wishlist1.id,
      body: {
        priority: 10,
      } satisfies IShoppingMallWishlist.IUpdate,
    });
  typia.assert(updatedWishlist1);

  // Update wishlist2 to medium priority
  const updatedWishlist2 =
    await api.functional.shoppingMall.customer.wishlists.update(connection, {
      wishlistId: wishlist2.id,
      body: {
        priority: 6,
      } satisfies IShoppingMallWishlist.IUpdate,
    });
  typia.assert(updatedWishlist2);

  // Update wishlist3 to lowest priority
  const updatedWishlist3 =
    await api.functional.shoppingMall.customer.wishlists.update(connection, {
      wishlistId: wishlist3.id,
      body: {
        priority: 2,
      } satisfies IShoppingMallWishlist.IUpdate,
    });
  typia.assert(updatedWishlist3);

  // Step 6: Validate that wishlist priorities are correctly updated
  TestValidator.equals(
    "wishlist1 priority updated to highest",
    updatedWishlist1.priority,
    10,
  );
  TestValidator.equals(
    "wishlist2 priority updated to medium",
    updatedWishlist2.priority,
    6,
  );
  TestValidator.equals(
    "wishlist3 priority updated to lowest",
    updatedWishlist3.priority,
    2,
  );

  // Step 7: Verify individual wishlist properties remain intact after priority changes
  TestValidator.equals(
    "wishlist1 name unchanged",
    updatedWishlist1.name,
    wishlist1.name,
  );
  TestValidator.equals(
    "wishlist1 description unchanged",
    updatedWishlist1.description,
    wishlist1.description,
  );
  TestValidator.equals(
    "wishlist1 visibility unchanged",
    updatedWishlist1.is_public,
    wishlist1.is_public,
  );

  TestValidator.equals(
    "wishlist2 name unchanged",
    updatedWishlist2.name,
    wishlist2.name,
  );
  TestValidator.equals(
    "wishlist2 description unchanged",
    updatedWishlist2.description,
    wishlist2.description,
  );
  TestValidator.equals(
    "wishlist2 visibility unchanged",
    updatedWishlist2.is_public,
    wishlist2.is_public,
  );

  TestValidator.equals(
    "wishlist3 name unchanged",
    updatedWishlist3.name,
    wishlist3.name,
  );
  TestValidator.equals(
    "wishlist3 description unchanged",
    updatedWishlist3.description,
    wishlist3.description,
  );
  TestValidator.equals(
    "wishlist3 visibility unchanged",
    updatedWishlist3.is_public,
    wishlist3.is_public,
  );

  // Step 8: Validate priority-based ordering logic
  TestValidator.predicate(
    "wishlist1 has highest priority",
    updatedWishlist1.priority > updatedWishlist2.priority,
  );
  TestValidator.predicate(
    "wishlist2 has medium priority",
    updatedWishlist2.priority > updatedWishlist3.priority,
  );
  TestValidator.predicate(
    "wishlist3 has lowest priority",
    updatedWishlist3.priority < updatedWishlist2.priority,
  );

  // Step 9: Verify customer ownership remains consistent
  TestValidator.equals(
    "wishlist1 customer ID matches",
    updatedWishlist1.customer.id,
    customer.id,
  );
  TestValidator.equals(
    "wishlist2 customer ID matches",
    updatedWishlist2.customer.id,
    customer.id,
  );
  TestValidator.equals(
    "wishlist3 customer ID matches",
    updatedWishlist3.customer.id,
    customer.id,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallUserPreference } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallUserPreference";

/**
 * Test customer preference deletion workflow where a customer creates a
 * preference setting and then removes it. The scenario validates that
 * preferences can be properly deleted using soft deletion (setting deleted_at
 * timestamp) while maintaining data integrity.
 */
export async function test_api_customer_user_preference_deletion(
  connection: api.IConnection,
) {
  // Step 1: Create customer account for authentication context
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "securePassword123";

  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      href: "https://shoppingmall.example.com/register",
      referrer: "https://shoppingmall.example.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create preference setting to be deleted
  const preferenceData = {
    preference_type: "notification",
    preference_key: "email_frequency",
    preference_value: "daily",
    category: "communication",
  } satisfies IShoppingMallUserPreference.ICreate;

  const createdPreference =
    await api.functional.shoppingMall.customer.userPreferences.post(
      connection,
      {
        body: preferenceData,
      },
    );
  typia.assert(createdPreference);

  // Validate preference creation
  TestValidator.equals(
    "preference type matches",
    createdPreference.preference_type,
    preferenceData.preference_type,
  );
  TestValidator.equals(
    "preference key matches",
    createdPreference.preference_key,
    preferenceData.preference_key,
  );
  TestValidator.equals(
    "preference value matches",
    createdPreference.preference_value,
    preferenceData.preference_value,
  );
  TestValidator.equals(
    "category matches",
    createdPreference.category,
    preferenceData.category,
  );
  TestValidator.equals(
    "customer ID matches",
    createdPreference.customer.id,
    customer.id,
  );
  TestValidator.predicate(
    "preference is active",
    createdPreference.is_active === true,
  );
  TestValidator.predicate(
    "deleted_at is null initially",
    createdPreference.deleted_at === null ||
      createdPreference.deleted_at === undefined,
  );

  // Step 3: Delete the preference using soft deletion
  await api.functional.shoppingMall.customer.userPreferences.erase(connection, {
    preferenceId: createdPreference.id,
  });

  // Step 4: Validate successful deletion workflow
  // Since the erase operation performs soft deletion and returns void,
  // and there's no API to retrieve deleted preferences, we validate that:
  // 1. The deletion operation completed without errors
  // 2. The preference creation and deletion workflow follows the business logic
  // 3. Customer ownership is maintained throughout the process

  TestValidator.predicate(
    "preference deletion workflow completed successfully",
    true,
  );

  // Note: The soft deletion validation (checking deleted_at timestamp) cannot be performed
  // because there's no API endpoint provided to retrieve preference records after deletion.
  // The test demonstrates the complete workflow from creation to deletion as specified
  // in the business scenario.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IDateRange } from "@ORGANIZATION/PROJECT-api/lib/structures/IDateRange";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallSaleStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSaleStatistics";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCategorySalesSummary } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategorySalesSummary";
import type { IShoppingMallDailySalesData } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallDailySalesData";
import type { IShoppingMallSaleFilters } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleFilters";
import type { IShoppingMallSaleStatistics } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleStatistics";
import type { IShoppingMallSaleStatus } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSaleStatus";
import type { IShoppingMallSalesGroupingDimension } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSalesGroupingDimension";
import type { IShoppingMallSalesMetric } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSalesMetric";
import type { IShoppingMallSalesTrend } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSalesTrend";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Comprehensive E2E test for sales statistics retrieval functionality.
 *
 * Validates that administrators can access aggregated sales data with various
 * filtering options including date ranges, grouping dimensions, and performance
 * metrics. Ensures proper authorization checks and data accuracy for business
 * intelligence reporting.
 */
export async function test_api_admin_sales_statistics_retrieval(
  connection: api.IConnection,
) {
  // Step 1: Create administrator account for authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "AdminPassword123!",
      first_name: RandomGenerator.name(),
      last_name: RandomGenerator.name(),
      role: "super_admin",
      permissions: JSON.stringify({
        sales_statistics: true,
        view_all_sellers: true,
        financial_reports: true,
      }),
      status: "active",
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 2: Test sales statistics with basic date range
  const oneMonthAgo = new Date(
    Date.now() - 30 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const today = new Date().toISOString();

  const basicStats =
    await api.functional.shoppingMall.admin.statistics.sales.index(connection, {
      body: {
        date_range: {
          start: oneMonthAgo,
          end: today,
        } satisfies IDateRange,
        group_by: ["day", "seller"] as IShoppingMallSalesGroupingDimension[],
        metrics: [
          "total_sales",
          "average_sale",
          "commission_earned",
        ] as IShoppingMallSalesMetric[],
        pagination: {
          current: 1,
          limit: 50,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies IShoppingMallSaleStatistics.IRequest,
    });
  typia.assert(basicStats);

  // Validate pagination structure
  TestValidator.predicate(
    "pagination has valid current page",
    basicStats.pagination.current >= 0,
  );
  TestValidator.predicate(
    "pagination has valid limit",
    basicStats.pagination.limit >= 0,
  );

  // Step 3: Test with specific filters
  const filteredStats =
    await api.functional.shoppingMall.admin.statistics.sales.index(connection, {
      body: {
        date_range: {
          start: oneMonthAgo,
        } satisfies IDateRange,
        group_by: [
          "category",
          "status",
        ] as IShoppingMallSalesGroupingDimension[],
        filters: {
          sale_status: ["completed", "pending"] as IShoppingMallSaleStatus[],
          min_amount: 100,
          max_amount: 10000,
        } satisfies IShoppingMallSaleFilters,
        metrics: [
          "sale_count",
          "net_amount",
          "item_count",
        ] as IShoppingMallSalesMetric[],
      } satisfies IShoppingMallSaleStatistics.IRequest,
    });
  typia.assert(filteredStats);

  // Step 4: Test with comprehensive grouping
  const comprehensiveStats =
    await api.functional.shoppingMall.admin.statistics.sales.index(connection, {
      body: {
        date_range: {
          end: today,
        } satisfies IDateRange,
        group_by: [
          "month",
          "customer",
          "product",
        ] as IShoppingMallSalesGroupingDimension[],
        metrics: [
          "total_sales",
          "average_sale",
          "commission_earned",
          "item_count",
          "net_amount",
          "sale_count",
        ] as IShoppingMallSalesMetric[],
        pagination: {
          current: 1,
          limit: 100,
          records: 0,
          pages: 0,
        } satisfies IPage.IPagination,
      } satisfies IShoppingMallSaleStatistics.IRequest,
    });
  typia.assert(comprehensiveStats);

  // Validate data structure for each statistics entry
  if (comprehensiveStats.data.length > 0) {
    const sampleStat = comprehensiveStats.data[0];
    TestValidator.predicate(
      "total sales is non-negative number",
      sampleStat.total_sales >= 0,
    );
    TestValidator.predicate(
      "total revenue is non-negative number",
      sampleStat.total_revenue >= 0,
    );
    TestValidator.predicate(
      "average order value is non-negative number",
      sampleStat.average_order_value >= 0,
    );
    TestValidator.predicate(
      "commission earned is non-negative number",
      sampleStat.commission_earned >= 0,
    );
    TestValidator.predicate(
      "net payout is non-negative number",
      sampleStat.net_payout >= 0,
    );

    // Validate seller information structure
    TestValidator.predicate(
      "seller business name is valid string",
      sampleStat.seller.business_name.length > 0,
    );
    TestValidator.predicate(
      "seller contact person is valid string",
      sampleStat.seller.contact_person.length > 0,
    );
    TestValidator.predicate(
      "seller email contains @ symbol",
      sampleStat.seller.email.includes("@"),
    );
    TestValidator.predicate(
      "seller status is valid string",
      sampleStat.seller.status.length > 0,
    );

    // Validate business logic relationships
    if (sampleStat.total_sales > 0) {
      TestValidator.predicate(
        "average order value is reasonable",
        sampleStat.average_order_value <= sampleStat.total_revenue,
      );
      TestValidator.predicate(
        "commission is reasonable percentage of revenue",
        sampleStat.commission_earned <= sampleStat.total_revenue,
      );
      TestValidator.predicate(
        "net payout equals revenue minus commission",
        Math.abs(
          sampleStat.net_payout -
            (sampleStat.total_revenue - sampleStat.commission_earned),
        ) < 0.01,
      );
    }
  }

  // Step 5: Test business logic error - empty metrics array
  await TestValidator.error("should reject empty metrics array", async () => {
    await api.functional.shoppingMall.admin.statistics.sales.index(connection, {
      body: {
        date_range: {
          start: oneMonthAgo,
          end: today,
        } satisfies IDateRange,
        group_by: ["day"] as IShoppingMallSalesGroupingDimension[],
        metrics: [] as IShoppingMallSalesMetric[],
      } satisfies IShoppingMallSaleStatistics.IRequest,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import type { IShoppingMallCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCategory";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReview";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";

/**
 * Validates the complete review lifecycle for customer-authored reviews.
 *
 * This test implements a comprehensive workflow that creates all necessary
 * prerequisites: customer account authentication, admin category creation,
 * seller product listing, and initial review submission. The core scenario
 * validates that customers can successfully update their own reviews with
 * modified content and ratings while maintaining data integrity.
 *
 * Key test steps:
 *
 * 1. Create customer account and authenticate
 * 2. Create admin account and authenticate for category creation
 * 3. Create seller account and authenticate for product listing
 * 4. Create product category via admin
 * 5. Create product via seller
 * 6. Create initial review via customer
 * 7. Update the review with new content and rating
 * 8. Validate that updated review reflects changes while preserving
 *    system-generated fields
 */
export async function test_api_customer_review_update_by_author(
  connection: api.IConnection,
) {
  // Step 1: Create customer account and authenticate
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "customer123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      phone_number: RandomGenerator.mobile(),
      href: "https://shoppingmall.com/register",
      referrer: "https://shoppingmall.com",
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // Step 2: Create admin account and authenticate for category creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "admin123",
      first_name: RandomGenerator.name(1),
      last_name: RandomGenerator.name(1),
      role: "support_admin",
      permissions: JSON.stringify({ manage_categories: true }),
    } satisfies IShoppingMallAdministrator.ICreate,
  });
  typia.assert(admin);

  // Step 3: Create seller account and authenticate for product listing
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: "seller123",
      business_name: RandomGenerator.paragraph({ sentences: 2 }),
      contact_person: RandomGenerator.name(),
      phone_number: RandomGenerator.mobile(),
      business_address: RandomGenerator.paragraph({ sentences: 3 }),
      href: "https://shoppingmall.com/seller/register",
      referrer: "https://shoppingmall.com",
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // Step 4: Create product category via admin
  const category = await api.functional.shoppingMall.admin.categories.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 1 }),
        display_order: typia.random<number & tags.Type<"int32">>(),
        active: true,
      } satisfies IShoppingMallCategory.ICreate,
    },
  );
  typia.assert(category);

  // Step 5: Create product via seller
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 3 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        sku: RandomGenerator.alphaNumeric(10),
        price: typia.random<number & tags.Minimum<1> & tags.Maximum<1000>>(),
        stock_quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<10> & tags.Maximum<100>
        >(),
        status: "active",
        condition: "new",
        category: {
          id: category.id,
          name: category.name,
          description: category.description,
          display_order: category.display_order,
          active: category.active,
          parent_id:
            category.parent?.id ?? typia.random<string & tags.Format<"uuid">>(),
          created_at: category.created_at,
          updated_at: category.updated_at,
          parent: category.parent,
        } satisfies IShoppingMallCategory.ISummary,
        seller: {
          id: seller.id,
          business_name: seller.business_name,
          contact_person: seller.contact_person,
          email: seller.email,
          status: seller.status,
        } satisfies IShoppingMallSeller.ISummary,
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // Switch back to customer authentication
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "customer123",
      href: "https://shoppingmall.com/login",
      referrer: "https://shoppingmall.com",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // Step 6: Create initial review via customer
  const initialReview =
    await api.functional.shoppingMall.customer.reviews.create(connection, {
      body: {
        actor_type: "customer",
        title: RandomGenerator.paragraph({ sentences: 2 }),
        content: RandomGenerator.content({ paragraphs: 1 }),
        overall_rating: typia.random<
          number & tags.Minimum<1> & tags.Maximum<5>
        >(),
        shopping_mall_product_id: product.id,
        shopping_mall_seller_id: seller.id,
        verified_purchase: true,
      } satisfies IShoppingMallReview.ICreate,
    });
  typia.assert(initialReview);

  // Step 7: Update the review with new content and rating
  const updatedReview =
    await api.functional.shoppingMall.customer.reviews.update(connection, {
      reviewId: initialReview.id,
      body: {
        title: RandomGenerator.paragraph({ sentences: 3 }),
        content: RandomGenerator.content({ paragraphs: 2 }),
        overall_rating: typia.random<
          number & tags.Minimum<1> & tags.Maximum<5>
        >(),
      } satisfies IShoppingMallReview.IUpdate,
    });
  typia.assert(updatedReview);

  // Step 8: Validate that updated review reflects changes while preserving system-generated fields
  TestValidator.equals(
    "review ID remains unchanged",
    updatedReview.id,
    initialReview.id,
  );
  TestValidator.equals(
    "actor_type remains unchanged",
    updatedReview.actor_type,
    initialReview.actor_type,
  );
  TestValidator.equals(
    "verified_purchase remains unchanged",
    updatedReview.verified_purchase,
    initialReview.verified_purchase,
  );
  TestValidator.equals(
    "product reference remains unchanged",
    updatedReview.shopping_mall_product_id,
    initialReview.shopping_mall_product_id,
  );
  TestValidator.equals(
    "seller reference remains unchanged",
