        priority: 7,
        status: "active",
      } satisfies IShoppingMallWishlist.ICreate,
    });
  typia.assert(uniqueWishlist);
  TestValidator.equals(
    "unique wishlist name matches",
    uniqueWishlist.name,
    uniqueWishlistName,
  );
  TestValidator.notEquals(
    "unique wishlist ID differs from initial",
    uniqueWishlist.id,
    initialWishlist.id,
  );
}

