  const searchRequest = {
    query: "electronics smartphone laptop",
    entityTypes: ["products", "categories", "articles"] as const,
    pagination: {
      page: 1,
      limit: 20,
      sortBy: "relevance",
      sortOrder: "desc" as const,
    } satisfies IPagination,
