            compare_price: typia.random<
              number &
                tags.Type<"uint32"> &
                tags.Minimum<50000> &
                tags.Maximum<100000>
            >(),
            cost_price: typia.random<
              number &
                tags.Type<"uint32"> &
                tags.Minimum<500> &
                tags.Maximum<25000>
            >(),
            stock_quantity: typia.random<
              number & tags.Type<"int32"> & tags.Minimum<0> & tags.Maximum<1000>
            >(),
            status: i % 2 === 0 ? "active" : "draft",
            condition: "new",
            weight: typia.random<
              number & tags.Minimum<0.1> & tags.Maximum<50>
