              name: "Electronics",
              description: "Electronic products",
              display_order: 1,
              active: true,
              parent_id: typia.random<string & tags.Format<"uuid">>(),
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString(),
              parent: undefined,
