import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallPromotion } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPromotion";
import { IShoppingMallChannel } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannel";
import { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingMallAdminChannelsChannelCodePromotionsPromotionName(props: {
  admin: AdminPayload;
  channelCode: string;
  promotionName: string;
}): Promise<IShoppingMallPromotion> {
  // First, find the channel by code to get its ID
  const channel = await MyGlobal.prisma.shopping_mall_channels.findFirst({
    where: {
      code: props.channelCode,
      deleted_at: null,
    },
  });

  if (!channel) {
    throw new HttpException("Channel not found", 404);
  }

  // Find the promotion within the specified channel
  const promotion = await MyGlobal.prisma.shopping_mall_promotions.findFirst({
    where: {
      name: props.promotionName,
      shopping_mall_channel_id: channel.id,
      deleted_at: null,
    },
    include: {
      channel: true,
      creator: true,
    },
  });

  if (!promotion) {
    throw new HttpException(
      "Promotion not found in the specified channel",
      404,
    );
  }

  // Verify administrator has permission to delete this promotion
  // Check if the admin created this promotion or has appropriate permissions
  if (promotion.shopping_mall_administrator_id !== props.admin.id) {
    // Additional permission check could be added here based on admin role
    throw new HttpException(
      "You do not have permission to delete this promotion",
      403,
    );
  }

  // Check if promotion is currently active to prevent disruption
  const currentTime = toISOStringSafe(new Date());
  if (
    promotion.is_active &&
    toISOStringSafe(promotion.start_date) <= currentTime &&
    toISOStringSafe(promotion.end_date) >= currentTime
  ) {
    throw new HttpException(
      "Cannot delete an active promotion. Please deactivate it first.",
      400,
    );
  }

  // Perform soft delete
  const deletedPromotion =
    await MyGlobal.prisma.shopping_mall_promotions.update({
      where: {
        id: promotion.id,
      },
      data: {
        deleted_at: toISOStringSafe(new Date()),
        updated_at: toISOStringSafe(new Date()),
      },
      include: {
        channel: true,
        creator: true,
      },
    });

  // Convert to API response format with proper type handling
  return {
    id: deletedPromotion.id as string & tags.Format<"uuid">,
    name: deletedPromotion.name,
    description: deletedPromotion.description ?? undefined,
    promotion_type: deletedPromotion.promotion_type,
    start_date: toISOStringSafe(deletedPromotion.start_date),
    end_date: toISOStringSafe(deletedPromotion.end_date),
    is_active: deletedPromotion.is_active,
    priority: deletedPromotion.priority,
    created_at: toISOStringSafe(deletedPromotion.created_at),
    updated_at: toISOStringSafe(deletedPromotion.updated_at),
    deleted_at: deletedPromotion.deleted_at
      ? toISOStringSafe(deletedPromotion.deleted_at)
      : undefined,
    channel: deletedPromotion.channel
      ? {
          id: deletedPromotion.channel.id as string & tags.Format<"uuid">,
          name: deletedPromotion.channel.name,
          description: deletedPromotion.channel.description ?? undefined,
          code: deletedPromotion.channel.code,
        }
      : undefined,
    creator: {
      id: deletedPromotion.creator.id as string & tags.Format<"uuid">,
      name: `${deletedPromotion.creator.first_name} ${deletedPromotion.creator.last_name}`,
      email: deletedPromotion.creator.email as string & tags.Format<"email">,
      role: deletedPromotion.creator.role,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingMallAdminCouponsCouponCode(props: {
  admin: AdminPayload;
  couponCode: string;
}): Promise<void> {
  // Use transaction for atomic operation
  await MyGlobal.prisma.$transaction(async (tx) => {
    // First, verify the coupon exists and is not already deleted
    const coupon = await tx.shopping_mall_coupons.findFirst({
      where: {
        code: props.couponCode,
        deleted_at: null,
      },
    });

    if (!coupon) {
      throw new HttpException("Coupon not found or already deleted", 404);
    }

    // Check if coupon is currently active and valid
    const now = toISOStringSafe(new Date());
    if (
      coupon.is_active &&
      toISOStringSafe(coupon.valid_until) > now &&
      toISOStringSafe(coupon.valid_from) <= now
    ) {
      throw new HttpException(
        "Cannot delete active coupon that is currently valid",
        400,
      );
    }

    // Verify admin has permission (in this system, all admins can delete coupons)
    // Additional permission checks could be added here if needed

    // Perform soft deletion by setting deleted_at timestamp
    await tx.shopping_mall_coupons.update({
      where: {
        id: coupon.id,
      },
      data: {
        deleted_at: now,
        updated_at: now,
        is_active: false, // Also deactivate the coupon
      },
    });
  });
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function getShoppingMallAdminOrdersOrderIdPaymentsPaymentId(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<"uuid">;
  paymentId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallPayment> {
  // Verify the order exists and admin has access
  const orderExists = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      id: props.orderId,
    },
    select: {
      id: true,
    },
  });

  if (!orderExists) {
    throw new HttpException("Order not found", 404);
  }

  // Find the payment record with order relationship
  const payment = await MyGlobal.prisma.shopping_mall_payments.findFirst({
    where: {
      id: props.paymentId,
      shopping_mall_order_id: props.orderId,
    },
    include: {
      order: {
        include: {
          customer: true,
        },
      },
    },
  });

  if (!payment) {
    throw new HttpException("Payment not found for the specified order", 404);
  }

  // Convert the payment record to match IShoppingMallPayment interface with proper type handling
  const result: IShoppingMallPayment = {
    id: payment.id,
    payment_method: typia.assert<
      "credit_card" | "paypal" | "bank_transfer" | "digital_wallet"
    >(payment.payment_method),
    payment_gateway: payment.payment_gateway,
    transaction_id: payment.transaction_id,
    amount: payment.amount,
    currency: payment.currency,
    status: typia.assert<
      | "refunded"
      | "disputed"
      | "pending"
      | "authorized"
      | "captured"
      | "declined"
      | "chargeback"
    >(payment.status),
    authorization_code:
      payment.authorization_code === null
        ? undefined
        : payment.authorization_code,
    captured_at:
      payment.captured_at === null
        ? undefined
        : toISOStringSafe(payment.captured_at),
    refunded_amount:
      payment.refunded_amount === null ? undefined : payment.refunded_amount,
    payment_details:
      payment.payment_details === null ? undefined : payment.payment_details,
    created_at: toISOStringSafe(payment.created_at),
    updated_at: toISOStringSafe(payment.updated_at),
    order: payment.order
      ? {
          id: payment.order.id,
          order_number: payment.order.order_number,
          total_amount: payment.order.total_amount,
          subtotal_amount: payment.order.subtotal_amount,
          tax_amount: payment.order.tax_amount,
          shipping_amount: payment.order.shipping_amount,
          currency: payment.order.currency,
          status: payment.order.status,
          shipping_address: payment.order.shipping_address,
          billing_address: payment.order.billing_address,
          created_at: toISOStringSafe(payment.order.created_at),
          updated_at: toISOStringSafe(payment.order.updated_at),
          customer: {
            id: payment.order.customer.id,
            email: payment.order.customer.email,
            first_name: payment.order.customer.first_name,
            last_name: payment.order.customer.last_name,
            phone_number:
              payment.order.customer.phone_number === null
                ? undefined
                : payment.order.customer.phone_number,
            status: payment.order.customer.status,
            created_at: toISOStringSafe(payment.order.customer.created_at),
            updated_at:
              payment.order.customer.updated_at === null
                ? undefined
                : toISOStringSafe(payment.order.customer.updated_at),
          },
        }
      : undefined,
  };

  return result;
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSection";
import { IPageIShoppingMallSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSection";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminChannelsChannelCodeSections(props: {
  admin: AdminPayload;
  channelCode: string;
  body: IShoppingMallSection.IRequest;
}): Promise<IPageIShoppingMallSection.ISummary> {
  // Verify channel exists
  const channel = await MyGlobal.prisma.shopping_mall_channels.findFirst({
    where: {
      code: props.channelCode,
      deleted_at: null,
    },
  });

  if (!channel) {
    throw new HttpException("Channel not found", 404);
  }

  // Build WHERE conditions
  const whereConditions: Record<string, unknown> = {
    shopping_mall_channel_id: channel.id,
    deleted_at: null,
  };

  // Apply search filter
  if (props.body.search) {
    whereConditions.OR = [
      { name: { contains: props.body.search, mode: "insensitive" } },
      { description: { contains: props.body.search, mode: "insensitive" } },
    ];
  }

  // Apply status filter
  if (props.body.status) {
    whereConditions.status = props.body.status;
  }

  // Apply parent section filter
  if (props.body.parent_section_id) {
    whereConditions.parent_section_id = props.body.parent_section_id;
  }

  // Apply date range filter - handle without Date constructor
  if (props.body.created_at_start || props.body.created_at_end) {
    whereConditions.created_at = {};
    if (props.body.created_at_start) {
      (whereConditions.created_at as Record<string, unknown>).gte =
        props.body.created_at_start;
    }
    if (props.body.created_at_end) {
      (whereConditions.created_at as Record<string, unknown>).lte =
        props.body.created_at_end;
    }
  }

  // Calculate pagination
  const page = props.body.page;
  const limit = props.body.limit;
  const skip = (page - 1) * limit;

  // Build ORDER BY
  const orderBy: Record<string, "asc" | "desc"> = {};
  const orderField = props.body.order_by ?? "display_order";
  const orderDirection = props.body.order_direction ?? "asc";

  orderBy[orderField] = orderDirection;

  // Execute queries concurrently
  const [sections, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sections.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_sections.count({
      where: whereConditions,
    }),
  ]);

  // Transform results to summary format
  const data = sections.map((section) => ({
    id: section.id,
    name: section.name,
    description: section.description ?? undefined,
    display_order: section.display_order,
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCoupon";
import { IPageIShoppingMallCoupon } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallCoupon";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function patchShoppingMallAdminCoupons(props: {
  admin: AdminPayload;
  body: IShoppingMallCoupon.IRequest;
}): Promise<IPageIShoppingMallCoupon.ISummary> {
  const page = (props.body.page ?? 1) satisfies number as number;
  const limit = Math.min(props.body.limit ?? 100, 100);
  const skip = (page - 1) * limit;

  // Build WHERE conditions using object spread for cleaner conditional logic
  const whereConditions = {
    deleted_at: null,
    // Search filter (code or name)
    ...(props.body.search && {
      OR: [
        {
          code: {
            contains: props.body.search,
            mode: Prisma.QueryMode.insensitive,
          },
        },
        {
          name: {
            contains: props.body.search,
            mode: Prisma.QueryMode.insensitive,
          },
        },
      ],
    }),
    // Discount type filter
    ...(props.body.discount_type && {
      discount_type: props.body.discount_type,
    }),
    // Active status filter
    ...(props.body.is_active !== undefined &&
      props.body.is_active !== null && {
        is_active: props.body.is_active,
      }),
    // Date range filters - use string comparison since dates are stored as strings
    ...((props.body.valid_from_min || props.body.valid_from_max) && {
      valid_from: {
        ...(props.body.valid_from_min && { gte: props.body.valid_from_min }),
        ...(props.body.valid_from_max && { lte: props.body.valid_from_max }),
      },
    }),
    ...((props.body.valid_until_min || props.body.valid_until_max) && {
      valid_until: {
        ...(props.body.valid_until_min && { gte: props.body.valid_until_min }),
        ...(props.body.valid_until_max && { lte: props.body.valid_until_max }),
      },
    }),
    // Channel filter
    ...(props.body.channel_id && {
      shopping_mall_channel_id: props.body.channel_id,
    }),
    // Creator filter
    ...(props.body.creator_id && {
      shopping_mall_administrator_id: props.body.creator_id,
    }),
    // Usage limit filters
    ...(props.body.usage_limit_per_customer !== undefined &&
      props.body.usage_limit_per_customer !== null && {
        usage_limit_per_customer: props.body.usage_limit_per_customer,
      }),
    ...(props.body.total_usage_limit !== undefined &&
      props.body.total_usage_limit !== null && {
        total_usage_limit: props.body.total_usage_limit,
      }),
    // Usage count range filters
    ...(((props.body.used_count_min !== undefined &&
      props.body.used_count_min !== null) ||
      (props.body.used_count_max !== undefined &&
        props.body.used_count_max !== null)) && {
      used_count: {
        ...(props.body.used_count_min !== undefined &&
          props.body.used_count_min !== null && {
            gte: props.body.used_count_min,
          }),
        ...(props.body.used_count_max !== undefined &&
          props.body.used_count_max !== null && {
            lte: props.body.used_count_max,
          }),
      },
    }),
  };

  // Build ORDER BY
  const orderBy: Record<string, "asc" | "desc"> = {};
  const orderField = props.body.order_by ?? "created_at";
  const orderDirection = props.body.order_direction ?? "desc";
  orderBy[orderField] = orderDirection;

  // Execute queries concurrently
  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_coupons.findMany({
      where: whereConditions,
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_coupons.count({
      where: whereConditions,
    }),
  ]);

  // Map to response format with proper optional field handling
  const mappedData = data.map((coupon) => ({
    id: coupon.id,
    code: coupon.code,
    name: coupon.name,
    discount_type: coupon.discount_type,
    discount_value: coupon.discount_value,
    minimum_order_amount: coupon.minimum_order_amount ?? undefined,
    valid_from: toISOStringSafe(coupon.valid_from),
    valid_until: toISOStringSafe(coupon.valid_until),
    is_active: coupon.is_active,
    used_count: coupon.used_count,
    created_at: toISOStringSafe(coupon.created_at),
    updated_at: toISOStringSafe(coupon.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: mappedData,
  };
}

