import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSupportTicket } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSupportTicket";
import { IShoppingMallInquiry } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallInquiry";
import { IShoppingMallAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdministrator";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function postShoppingMallAdminSupportTickets(props: {
  admin: AdminPayload;
  body: IShoppingMallSupportTicket.ICreate;
}): Promise<IShoppingMallSupportTicket> {
  // Validate priority and category values
  const validPriorities = ["low", "medium", "high", "critical"];
  if (!validPriorities.includes(props.body.priority)) {
    throw new HttpException("Invalid priority value", 400);
  }

  const validCategories = [
    "technical_issue",
    "billing_problem",
    "account_security",
    "product_question",
    "general_feedback",
  ];
  if (!validCategories.includes(props.body.category)) {
    throw new HttpException("Invalid category value", 400);
  }

  // Generate unique ticket number without Date type
  const now = toISOStringSafe(new Date());
  const datePart = now.slice(0, 10).replace(/-/g, "");
  const randomPart = Math.random().toString(36).substring(2, 8).toUpperCase();
  const ticketNumber = `TKT-${datePart}-${randomPart}`;

  // Calculate SLA deadline based on priority
  const slaDeadline = calculateSLADeadline(props.body.priority);

  // Create the support ticket
  const created = await MyGlobal.prisma.shopping_mall_support_tickets.create({
    data: {
      id: v4(),
      ticket_number: ticketNumber,
      title: props.body.title,
      description: props.body.description,
      category: props.body.category,
      priority: props.body.priority,
      status: "new",
      sla_deadline: slaDeadline,
      shopping_mall_inquiry_id: props.body.shopping_mall_inquiry_id,
      shopping_mall_administrator_id: props.admin.id,
      created_at: now,
      updated_at: now,
    },
  });

  // Return the created ticket with proper typing
  return {
    id: created.id,
    ticket_number: created.ticket_number,
    title: created.title,
    description: created.description,
    category: created.category,
    priority: created.priority,
    status: created.status,
    sla_deadline: created.sla_deadline
      ? toISOStringSafe(created.sla_deadline)
      : undefined,
    resolution_notes: created.resolution_notes ?? undefined,
    inquiry: undefined,
    assigned_administrator: undefined,
    shopping_mall_inquiry_id: created.shopping_mall_inquiry_id ?? undefined,
    shopping_mall_administrator_id:
      created.shopping_mall_administrator_id ?? undefined,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    resolved_at: created.resolved_at
      ? toISOStringSafe(created.resolved_at)
      : undefined,
    closed_at: created.closed_at
      ? toISOStringSafe(created.closed_at)
      : undefined,
    deleted_at: created.deleted_at
      ? toISOStringSafe(created.deleted_at)
      : undefined,
  };
}

// Helper function to calculate SLA deadline based on priority
function calculateSLADeadline(priority: string): string | null {
  const now = new Date();
  let deadline: Date;

  switch (priority) {
    case "critical":
      deadline = new Date(now.getTime() + 24 * 60 * 60 * 1000); // 24 hours
      break;
    case "high":
      deadline = new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000); // 3 days
      break;
    case "medium":
      deadline = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days
      break;
    case "low":
      deadline = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000); // 14 days
      break;
    default:
      return null;
  }

  return toISOStringSafe(deadline);
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerCartsCartIdItems(props: {
  customer: CustomerPayload;
  cartId: string & tags.Format<"uuid">;
  body: IShoppingMallCartItem.ICreate;
}): Promise<IShoppingMallCartItem> {
  // Verify cart exists and belongs to the customer
  const cart = await MyGlobal.prisma.shopping_mall_carts.findFirst({
    where: {
      id: props.cartId,
      shopping_mall_customer_session_id: props.customer.session_id,
      deleted_at: null,
      status: "active",
    },
  });

  if (!cart) {
    throw new HttpException(
      "Shopping cart not found or you don't have permission to access it",
      404,
    );
  }

  // Check if cart is expired using string comparison
  const currentTime = toISOStringSafe(new Date());
  if (toISOStringSafe(cart.expires_at) < currentTime) {
    throw new HttpException("Shopping cart has expired", 410);
  }

  // Verify product variant exists and is available
  const productVariant =
    await MyGlobal.prisma.shopping_mall_product_variants.findFirst({
      where: {
        id: props.body.product_variant_id,
        active: true,
        deleted_at: null,
      },
    });

  if (!productVariant) {
    throw new HttpException(
      "Product variant not found or is no longer available",
      404,
    );
  }

  // Check inventory availability
  if (productVariant.stock_quantity < props.body.quantity) {
    throw new HttpException(
      `Only ${productVariant.stock_quantity} units available in stock`,
      400,
    );
  }

  // Use product variant price if available, otherwise default to 0
  const unitPrice = productVariant.price ?? 0;

  // Check for existing cart item with same product variant
  const existingCartItem =
    await MyGlobal.prisma.shopping_mall_cart_items.findFirst({
      where: {
        shopping_mall_cart_id: props.cartId,
        shopping_mall_product_variant_id: props.body.product_variant_id,
      },
    });

  const now = toISOStringSafe(new Date());

  let cartItem;
  if (existingCartItem) {
    // Update quantity if item already exists
    const newQuantity = existingCartItem.quantity + props.body.quantity;

    // Check if new quantity exceeds maximum limit
    if (newQuantity > 999) {
      throw new HttpException(
        "Total quantity cannot exceed 999 units per product variant",
        400,
      );
    }

    cartItem = await MyGlobal.prisma.shopping_mall_cart_items.update({
      where: { id: existingCartItem.id },
      data: {
        quantity: newQuantity,
        unit_price: unitPrice,
        updated_at: now,
        notes: props.body.notes ?? existingCartItem.notes,
      },
    });
  } else {
    // Create new cart item
    cartItem = await MyGlobal.prisma.shopping_mall_cart_items.create({
      data: {
        id: v4() as string & tags.Format<"uuid">,
        shopping_mall_cart_id: props.cartId,
        shopping_mall_product_variant_id: props.body.product_variant_id,
        quantity: props.body.quantity,
        unit_price: unitPrice,
        added_at: now,
        updated_at: now,
        notes: props.body.notes ?? null,
      },
    });
  }

  // Update cart timestamp to reflect activity
  await MyGlobal.prisma.shopping_mall_carts.update({
    where: { id: props.cartId },
    data: { updated_at: now },
  });

  return {
    id: cartItem.id,
    shopping_mall_cart_id: cartItem.shopping_mall_cart_id,
    shopping_mall_product_variant_id: cartItem.shopping_mall_product_variant_id,
    quantity: cartItem.quantity,
    unit_price: cartItem.unit_price,
    added_at: toISOStringSafe(cartItem.added_at),
    updated_at: toISOStringSafe(cartItem.updated_at),
    notes: cartItem.notes ?? undefined,
  };
}

