      created_at: toISOStringSafe(new Date()),
      updated_at: toISOStringSafe(new Date()),
      deleted_at: null,
    },
    include: {
      category: {
        select: {
          id: true,
          name: true,
          description: true,
          display_order: true,
          active: true,
          parent_id: true,
          created_at: true,
          updated_at: true,
          parent: {
            select: {
              id: true,
              name: true,
              description: true,
              display_order: true,
              active: true,
              parent_id: true,
              created_at: true,
              updated_at: true,
