import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerOrdersOrderIdItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  body: IShoppingMallOrderItem.ICreate;
}): Promise<IShoppingMallOrderItem> {
  // Verify the order exists and belongs to the customer
  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: {
      id: props.orderId,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });

  if (!order) {
    throw new HttpException("Order not found or access denied", 404);
  }

  // Verify the product variant exists and is active
  const productVariant =
    await MyGlobal.prisma.shopping_mall_product_variants.findUnique({
      where: {
        id: props.body.shopping_mall_product_variant_id,
        active: true,
        deleted_at: null,
      },
      include: {
        product: {
          select: {
            shopping_mall_seller_id: true,
            name: true,
          },
        },
      },
    });

  if (!productVariant) {
    throw new HttpException("Product variant not found or unavailable", 404);
  }

  // Check if product variant has sufficient stock
  if (productVariant.stock_quantity < props.body.quantity) {
    throw new HttpException("Insufficient stock available", 400);
  }

  // Calculate pricing using variant price
  const unitPrice = productVariant.price;
  if (!unitPrice) {
    throw new HttpException("Product pricing not available", 400);
  }

  const totalPrice = unitPrice * props.body.quantity;
  const now = toISOStringSafe(new Date());

  // Create the order item
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.create({
    data: {
      id: v4() as string & tags.Format<"uuid">,
      shopping_mall_order_id: props.orderId,
      shopping_mall_product_variant_id:
        props.body.shopping_mall_product_variant_id,
      shopping_mall_seller_id: productVariant.product.shopping_mall_seller_id,
      quantity: props.body.quantity,
      unit_price: unitPrice,
      total_price: totalPrice,
      product_name: productVariant.variant_name,
      product_attributes: productVariant.attributes,
      created_at: now,
      updated_at: now,
    },
  });

  return {
    id: orderItem.id,
    shopping_mall_order_id: orderItem.shopping_mall_order_id,
    shopping_mall_product_variant_id:
      orderItem.shopping_mall_product_variant_id,
    shopping_mall_seller_id: orderItem.shopping_mall_seller_id,
    quantity: orderItem.quantity,
    unit_price: orderItem.unit_price,
    total_price: orderItem.total_price,
    product_name: orderItem.product_name,
    product_attributes: orderItem.product_attributes ?? undefined,
    created_at: toISOStringSafe(orderItem.created_at),
    updated_at: toISOStringSafe(orderItem.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function putShoppingMallCustomerOrdersOrderIdItemsItemId(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
  body: IShoppingMallOrderItem.IUpdate;
}): Promise<IShoppingMallOrderItem> {
  // Check if any update fields are provided
  if (Object.keys(props.body).length === 0) {
    throw new HttpException("No update fields provided", 400);
  }

  // Validate quantity if provided
  if (props.body.quantity !== undefined && props.body.quantity < 1) {
    throw new HttpException("Quantity must be at least 1", 400);
  }

  // Validate unit_price if provided
  if (props.body.unit_price !== undefined && props.body.unit_price < 0) {
    throw new HttpException("Unit price cannot be negative", 400);
  }

  // Validate total_price if provided
  if (props.body.total_price !== undefined && props.body.total_price < 0) {
    throw new HttpException("Total price cannot be negative", 400);
  }

  // Verify the order exists and belongs to the authenticated customer
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      id: props.orderId,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });

  if (!order) {
    throw new HttpException("Order not found or access denied", 404);
  }

  // Check if order is in a modifiable state
  const nonModifiableStatuses = [
    "completed",
    "cancelled",
    "refunded",
    "delivered",
    "shipped",
  ];
  if (nonModifiableStatuses.includes(order.status)) {
    throw new HttpException(
      "Order cannot be modified in its current state",
      400,
    );
  }

  // Verify the order item exists and belongs to the specified order
  const existingItem =
    await MyGlobal.prisma.shopping_mall_order_items.findFirst({
      where: {
        id: props.itemId,
        shopping_mall_order_id: props.orderId,
      },
    });

  if (!existingItem) {
    throw new HttpException("Order item not found", 404);
  }

  // Calculate new total price based on updates
  const newQuantity = props.body.quantity ?? existingItem.quantity;
  const newUnitPrice = props.body.unit_price ?? existingItem.unit_price;
  const newTotalPrice = props.body.total_price ?? newQuantity * newUnitPrice;

  // Prepare update data
  const updateData = {
    ...(props.body.quantity !== undefined && { quantity: props.body.quantity }),
    ...(props.body.unit_price !== undefined && {
      unit_price: props.body.unit_price,
    }),
    ...(props.body.total_price !== undefined && {
      total_price: props.body.total_price,
    }),
    ...(props.body.product_name !== undefined && {
      product_name: props.body.product_name,
    }),
    ...(props.body.product_attributes !== undefined && {
      product_attributes: props.body.product_attributes,
    }),
    updated_at: toISOStringSafe(new Date()),
  };

  // If quantity or unit_price changed but total_price wasn't explicitly provided, recalculate
  if (
    (props.body.quantity !== undefined ||
      props.body.unit_price !== undefined) &&
    props.body.total_price === undefined
  ) {
    updateData.total_price = newQuantity * newUnitPrice;
  }

  // Update the order item
  const updated = await MyGlobal.prisma.shopping_mall_order_items.update({
    where: { id: props.itemId },
    data: updateData,
  });

  // Return the updated item with proper type conversions
  return {
    id: updated.id,
    shopping_mall_order_id: updated.shopping_mall_order_id,
    shopping_mall_product_variant_id: updated.shopping_mall_product_variant_id,
    shopping_mall_seller_id: updated.shopping_mall_seller_id,
    quantity: updated.quantity,
    unit_price: updated.unit_price,
    total_price: updated.total_price,
    product_name: updated.product_name,
    product_attributes: updated.product_attributes ?? undefined,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingMallCustomerOrdersOrderIdItemsItemId(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<"uuid">;
  itemId: string & tags.Format<"uuid">;
}): Promise<void> {
  // Verify the order exists and belongs to the customer
  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      id: props.orderId,
      shopping_mall_customer_id: props.customer.id,
      deleted_at: null,
    },
  });

  if (!order) {
    throw new HttpException("Order not found or access denied", 404);
  }

  // Check if order status allows item deletion
  const nonModifiableStatuses = [
    "shipped",
    "delivered",
    "completed",
    "cancelled",
    "refunded",
  ];
  if (nonModifiableStatuses.includes(order.status)) {
    throw new HttpException(
      "Cannot delete items from an order that has already been shipped or completed",
      400,
    );
  }

  // Verify the order item exists and belongs to the specified order
  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findFirst({
    where: {
      id: props.itemId,
      shopping_mall_order_id: props.orderId,
    },
  });

  if (!orderItem) {
    throw new HttpException("Order item not found", 404);
  }

  // Permanently delete the order item
  await MyGlobal.prisma.shopping_mall_order_items.delete({
    where: {
      id: props.itemId,
    },
  });

  // Update order totals after item removal
  const remainingItems =
    await MyGlobal.prisma.shopping_mall_order_items.findMany({
      where: {
        shopping_mall_order_id: props.orderId,
      },
    });

  const newSubtotal = remainingItems.reduce(
    (sum, item) => sum + item.total_price,
    0,
  );
  const newTotal = newSubtotal + order.tax_amount + order.shipping_amount;

  await MyGlobal.prisma.shopping_mall_orders.update({
    where: {
      id: props.orderId,
    },
    data: {
      subtotal_amount: newSubtotal,
      total_amount: newTotal,
      updated_at: toISOStringSafe(new Date()),
    },
  });
}

